  if (irq || (atomic_read(&rtcb->flags) & TCB_FLAG_TTYPE_MASK) ==
      TCB_FLAG_TTYPE_KERNEL)
#endif
    {
      /* Disable KASAN to avoid false positive */

      kasan_stop();

      /* Fatal error, enter panic state. */

      g_nx_initstate = OSINIT_PANIC;
      sched_trace_mark("PANIC");

#ifdef CONFIG_SMP
      if (os_ready)
        {
          pause_all_cpu();
        }
#endif
