   369	static void start_rt_timer(struct rt_timer_s *timer,
   370	                           uint64_t timeout,
   371	                           bool repeat)
   372	{
   373	  struct esp32s3_rt_priv_s *priv = &g_rt_priv;
   374	
   375	  /* Only idle timer can be started */
   376	
   377	  if (timer->state == RT_TIMER_IDLE)
   378	    {
   379	      struct rt_timer_s *temp_p;
   380	      bool inserted = false;
   381	
   382	      /* Calculate the timer's alarm value */
   383	
   384	      uint64_t counter = rt_timer_getcounter();
   385	      counter = CYCLES_TO_USEC(counter);
   386	      timer->timeout = timeout;
   387	      timer->alarm = timer->timeout + counter;
   388	
   389	      if (repeat)
   390	        {
   391	          timer->flags |= RT_TIMER_REPEAT;
   392	        }
   393	      else
   394	        {
   395	          timer->flags &= ~RT_TIMER_REPEAT;
   396	        }
   397	
   398	      /* Scan the timer list and insert the new timer into previous node of
   399	       * timer whose alarm value is larger than new one.
   400	       */
   401	
   402	      list_for_every_entry(&priv->runlist, temp_p, struct rt_timer_s, list)
   403	        {
   404	          if (temp_p->alarm > timer->alarm)
   405	            {
   406	              list_add_before(&temp_p->list, &timer->list);
   407	              inserted = true;
   408	              break;
   409	            }
   410	        }
   411	
   412	      /* If we didn't find a larger one, insert the new timer at the tail of
   413	       * the list.
   414	       */
   415	
   416	      if (!inserted)
   417	        {
   418	          list_add_tail(&priv->runlist, &timer->list);
   419	        }
   420	
   421	      timer->state = RT_TIMER_READY;
   422	
   423	      /* Check if this timer is at the head of the list */
   424	
   425	      if (timer == container_of(priv->runlist.next, struct rt_timer_s, list))
   426	        {
   427	          /* Reset the hardware timer alarm */
   428	
   429	          rt_timer_setalarm(false);
   430	          rt_timer_setalarmvalue(USEC_TO_CYCLES(timer->alarm));
   431	          rt_timer_setalarm(true);
   432	        }
   433	    }
