///////////////////////////////////////////////////////////////////
//-- DOG GAIT MOVEMENTS -----------------------------------------//
///////////////////////////////////////////////////////////////////

void EDARobotDog::Turn(float steps, int period, int dir) {

  if (GetRestState() == true) {
    SetRestState(false);
  }

  for (int step = 0; step < (int)steps; step++) {
    if (dir == LEFT) {

      int current_pos[SERVO_COUNT];
      for (int i = 0; i < SERVO_COUNT; i++) {
        if (servo_pins_[i] != -1) {
          current_pos[i] = servo_[i].GetPosition();
        } else {
          current_pos[i] = LEG_HOME_POSITION;
        }
      }
      //左转 - 
      //23
      current_pos[RIGHT_FRONT_LEG] = 135;
      current_pos[LEFT_REAR_LEG] = 135;
      MoveServos(150, current_pos);

      //14
      current_pos[LEFT_FRONT_LEG] = 45; 
      current_pos[RIGHT_REAR_LEG] = 45; 
