    }

  if (argc >= 4)
    {
      errno = 0;
      value = strtol(argv[3], &end, 10);
      if (errno != 0 || *end != '\0' || value < ROBOTCTL_MIN_PERIOD ||
          value > ROBOTCTL_MAX_PERIOD)
        {
          return -EINVAL;
        }

      *period_ms = (int)value;
    }

  return 0;
}

static void robotctl_usage(void)
{
  printf("Usage: robotctl <command> [steps] [period_ms]\n");
  printf("Commands: help status home off forward backward left right\n");
  printf("Motion limits: steps 1..10, period_ms 800..3000.\n");
}

static void robotctl_status(void)
{
  printf("robotctl %s\n", ROBOTCTL_VERSION);
  printf("PWM: %s\n", access(ROBOTCTL_PWM_PATH, F_OK) == 0 ?
         "available (/dev/pwm0)" : "unavailable");
  printf("I2C: %s\n", access(ROBOTCTL_I2C_PATH, F_OK) == 0 ?
         "available (/dev/i2c0)" : "unavailable");
  printf("OLED: not implemented\n");
  printf("Servo: OFF (no active robotctl command)\n");
  printf("Wi-Fi: use wapi, renew, ifconfig, and ping.\n");
}

static int robotctl_off(void)
{
  int fd;
  int ret;

  fd = open(ROBOTCTL_PWM_PATH, O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "robotctl: open %s: %d\n", ROBOTCTL_PWM_PATH, errno);
      return -errno;
    }

  ret = ioctl(fd, PWMIOC_STOP, 0);
  if (ret < 0)
    {
      fprintf(stderr, "robotctl: PWMIOC_STOP: %d\n", errno);
      ret = -errno;
    }

  close(fd);
  return ret;
}

static int robotctl_motion(const char *command, int argc, char *argv[])
{
  static const int g_forward[8][ROBOTCTL_SERVO_COUNT] =
  {
    {135,  90,  45,  90, 85}, {135,  45,  45, 135, 85},
    { 90,  45,  90, 135, 85}, { 90,  90,  90,  90, 85},
    { 90, 135,  90,  45, 85}, { 45, 135, 135,  45, 85},
    { 45,  90, 135,  90, 85}, { 90,  90,  90,  90, 85}
  };
  static const int g_backward[8][ROBOTCTL_SERVO_COUNT] =
  {
    { 45,  90, 135,  90, 85}, { 45, 135, 135,  45, 85},
    { 90, 135,  90,  45, 85}, { 90,  90,  90,  90, 85},
    { 90,  45,  90, 135, 85}, {135,  45,  45, 135, 85},
    {135,  90,  45,  90, 85}, { 90,  90,  90,  90, 85}
  };
  static const int g_left[8][ROBOTCTL_SERVO_COUNT] =
  {
    {135,  90, 135,  90, 85}, {135,  45, 135,  45, 85},
    { 90,  45,  90,  45, 85}, { 90,  90,  90,  90, 85},
    { 90, 135,  90, 135, 85}, { 45, 135,  45, 135, 85},
    { 45,  90,  45,  90, 85}, { 90,  90,  90,  90, 85}
  };
  static const int g_right[8][ROBOTCTL_SERVO_COUNT] =
  {
    { 45,  90,  45,  90, 85}, { 45, 135,  45, 135, 85},
    { 90, 135,  90, 135, 85}, { 90,  90,  90,  90, 85},
    { 45,  45,  90,  90, 85}, {135,  45, 135,  90, 85},
    { 90,  90, 135,  90, 85}, { 90,  90,  90,  90, 85}
  };
  const int (*gait)[ROBOTCTL_SERVO_COUNT];
  int current[ROBOTCTL_SERVO_COUNT];
  int period_ms;
  int steps;
  int fd;
  int ret;

  ret = robotctl_parse_motion_args(argc, argv, &steps, &period_ms);
  if (ret < 0)
    {
      fprintf(stderr, "robotctl: %s requires steps 1..10 and period_ms 800..3000\n",
              command);
      return ret;
    }

  if (strcmp(command, "forward") == 0)
    {
      gait = g_forward;
    }
  else if (strcmp(command, "backward") == 0)
    {
      gait = g_backward;
    }
  else if (strcmp(command, "left") == 0)
    {
      gait = g_left;
    }
  else
    {
      gait = g_right;
    }

  fd = open(ROBOTCTL_PWM_PATH, O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "robotctl: open %s: %d\n", ROBOTCTL_PWM_PATH, errno);
      return -errno;
    }

  robotctl_get_positions(fd, current);
  ret = robotctl_run_gait(fd, current, gait, steps, period_ms);
  close(fd);
  return ret;
}

static int robotctl_home(void)
{
  int current[ROBOTCTL_SERVO_COUNT];
  int fd;
  int ret;

  fd = open(ROBOTCTL_PWM_PATH, O_RDONLY);
  if (fd < 0)
    {
      fprintf(stderr, "robotctl: open %s: %d\n", ROBOTCTL_PWM_PATH, errno);
      return -errno;
    }

  robotctl_get_positions(fd, current);
  ret = robotctl_move_home(fd, current);
  close(fd);
  return ret;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  int ret;

  if (argc < 2 || strcmp(argv[1], "help") == 0)
    {
      robotctl_usage();
      return EXIT_SUCCESS;
    }

  if (strcmp(argv[1], "status") == 0)
    {
      robotctl_status();
      return EXIT_SUCCESS;
    }

  if (strcmp(argv[1], "off") == 0)
    {
      ret = robotctl_off();
    }
  else if (strcmp(argv[1], "home") == 0)
    {
      ret = robotctl_home();
    }
  else if (strcmp(argv[1], "forward") == 0 ||
           strcmp(argv[1], "backward") == 0 ||
           strcmp(argv[1], "left") == 0 || strcmp(argv[1], "right") == 0)
    {
      ret = robotctl_motion(argv[1], argc, argv);
    }
  else
    {
      fprintf(stderr, "robotctl: unknown command: %s\n", argv[1]);
      robotctl_usage();
      return EXIT_FAILURE;
    }

  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

