+
+const int g_robotctl_home[ROBOTCTL_SERVO_COUNT] =
+{
+  90, 90, 90, 90, 85
+};
+
+/****************************************************************************
+ * Private Data
+ ****************************************************************************/
+
+static const int g_trim[ROBOTCTL_SERVO_COUNT] =
+{
+  0, 0, 0, 0, 0
+};
+
+static const char *const g_servo_names[ROBOTCTL_SERVO_COUNT] =
+{
+  "RF", "RR", "LR", "LF", "TAIL"
+};
