+static int robotctl_safe_interval(int period_ms)
+{
+  int interval_ms = period_ms / 100;
+
+  if (interval_ms < 25)
+    {
+      interval_ms = 25;
+    }
+  else if (interval_ms > 30)
+    {
+      interval_ms = 30;
+    }
+
+  return interval_ms;
+}
+
+static int robotctl_safe_settle(int period_ms)
+{
+  int settle_ms = period_ms / 12;
+
+  if (settle_ms < 150)
+    {
+      settle_ms = 150;
+    }
+  else if (settle_ms > 250)
+    {
+      settle_ms = 250;
+    }
+
+  return settle_ms;
+}
