    52	/****************************************************************************
    53	 * Private Type Definitions
    54	 ****************************************************************************/
    55	
    56	/* This structure describes the state of the upper half driver */
    57	
    58	struct pwm_upperhalf_s
    59	{
    60	  uint8_t           crefs;          /* The number of times the device has
    61	                                     * been opened */
    62	  volatile bool     started;        /* True: pulsed output is being
    63	                                     * generated */
    64	#ifdef CONFIG_PWM_PULSECOUNT
    65	  volatile bool     waiting;        /* True: Caller is waiting for the pulse
    66	                                     * count to expire */
    67	#endif
    68	  mutex_t           lock;           /* Supports mutual exclusion */
    69	#ifdef CONFIG_PWM_PULSECOUNT
    70	  sem_t             waitsem;        /* Used to wait for the pulse count to
    71	                                     * expire */
    72	#endif
    73	  struct pwm_info_s info;           /* Pulsed output characteristics */
    74	  FAR struct pwm_lowerhalf_s *dev;  /* lower-half state */
    75	};
