   148	/****************************************************************************
   149	 * Name: pwm_open
   150	 *
   151	 * Description:
   152	 *   This function is called whenever the PWM device is opened.
   153	 *
   154	 ****************************************************************************/
   155	
   156	static int pwm_open(FAR struct file *filep)
   157	{
   158	  FAR struct inode           *inode = filep->f_inode;
   159	  FAR struct pwm_upperhalf_s *upper = inode->i_private;
   160	  uint8_t                     tmp;
   161	  int                         ret = OK;
   162	
   163	  pwminfo("crefs: %d\n", upper->crefs);
   164	
   165	  /* Get exclusive access to the device structures */
   166	
   167	  nxmutex_lock(&upper->lock);
   168	
   169	  /* Increment the count of references to the device.  If this the first
   170	   * time that the driver has been opened for this device, then initialize
   171	   * the device.
   172	   */
   173	
   174	  tmp = upper->crefs + 1;
   175	  if (tmp == 0)
   176	    {
   177	      /* More than 255 opens; uint8_t overflows to zero */
   178	
   179	      ret = -EMFILE;
   180	      goto errout_with_lock;
   181	    }
   182	
   183	  /* Check if this is the first time that the driver has been opened. */
   184	
   185	  if (tmp == 1)
   186	    {
   187	      FAR struct pwm_lowerhalf_s *lower = upper->dev;
   188	
   189	      /* Yes.. perform one time hardware initialization. */
   190	
   191	      DEBUGASSERT(lower->ops->setup != NULL);
   192	      pwminfo("calling setup\n");
   193	
   194	      ret = lower->ops->setup(lower);
   195	      if (ret < 0)
   196	        {
   197	          goto errout_with_lock;
   198	        }
   199	    }
   200	
   201	  /* Save the new open count on success */
   202	
   203	  upper->crefs = tmp;
   204	
   205	errout_with_lock:
   206	  nxmutex_unlock(&upper->lock);
   207	
   208	  return ret;
   209	}
