   605	/****************************************************************************
   606	 * Name: pwm_setup
   607	 *
   608	 * Description:
   609	 *   This method is called when the driver is opened.  The lower half driver
   610	 *   should configure and initialize the device so that it is ready for use.
   611	 *   It should not, however, output pulses until the start method is called.
   612	 *
   613	 * Input Parameters:
   614	 *   dev - A reference to the lower half PWM driver state structure
   615	 *
   616	 * Returned Value:
   617	 *   Zero on success; a negated errno value on failure
   618	 *
   619	 ****************************************************************************/
   620	
   621	static int pwm_setup(struct pwm_lowerhalf_s *dev)
   622	{
   623	  struct esp32s3_ledc_s *priv = (struct esp32s3_ledc_s *)dev;
   624	
   625	  pwminfo("PWM timer%u\n", priv->num);
   626	
   627	  ledc_enable_clk();
   628	
   629	  /* Setup channel GPIO pins */
   630	
   631	  for (int i = 0; i < priv->channels; i++)
   632	    {
   633	      pwminfo("channel%d --> pin%d\n", priv->chans[i].num,
   634	              priv->chans[i].pin);
   635	
   636	      esp32s3_configgpio(priv->chans[i].pin, OUTPUT | PULLUP);
   637	      esp32s3_gpio_matrix_out(priv->chans[i].pin,
   638	                              LEDC_LS_SIG_OUT0_IDX + priv->chans[i].num,
   639	                              0, 0);
   640	    }
   641	
   642	  return 0;
   643	}
   644	
   645	/****************************************************************************
   646	 * Name: pwm_shutdown
   647	 *
   648	 * Description:
   649	 *   This method is called when the driver is closed.  The lower half driver
   650	 *   stop pulsed output, free any resources, disable the timer hardware, and
   651	 *   put the system into the lowest possible power usage state
   652	 *
   653	 * Input Parameters:
   654	 *   dev - A reference to the lower half PWM driver state structure
   655	 *
   656	 * Returned Value:
   657	 *   Zero on success; a negated errno value on failure
   658	 *
   659	 ****************************************************************************/
   660	
   661	static int pwm_shutdown(struct pwm_lowerhalf_s *dev)
   662	{
   663	  struct esp32s3_ledc_s *priv = (struct esp32s3_ledc_s *)dev;
   664	#ifdef CONFIG_PWM_NCHANNELS
   665	  int channels = MIN(priv->channels, CONFIG_PWM_NCHANNELS);
   666	#else
   667	  int channels = 1;
   668	#endif
   669	
   670	  /* Stop timer */
   671	
   672	  pwm_stop(dev);
   673	
   674	  /* Clear timer and channel configuration */
   675	
   676	  priv->frequency = 0;
   677	  priv->reload    = 0;
   678	  for (int i = 0; i < channels; i++)
   679	    {
   680	      priv->chans[i].duty = 0;
   681	    }
   682	
   683	  ledc_disable_clk();
   684	
   685	  return 0;
   686	}
   687	
   688	/****************************************************************************
   689	 * Name: pwm_start
   690	 *
   691	 * Description:
   692	 *   (Re-)initialize the timer resources and start the pulsed output
   693	 *
   694	 * Input Parameters:
   695	 *   dev  - A reference to the lower half PWM driver state structure
   696	 *   info - A reference to the characteristics of the pulsed output
   697	 *
   698	 * Returned Value:
   699	 *   Zero on success; a negated errno value on failure
   700	 *
   701	 ****************************************************************************/
   702	
   703	static int pwm_start(struct pwm_lowerhalf_s *dev,
   704	                     const struct pwm_info_s *info)
   705	{
   706	  struct esp32s3_ledc_s *priv = (struct esp32s3_ledc_s *)dev;
   707	#ifdef CONFIG_PWM_NCHANNELS
   708	  int channels = MIN(priv->channels, CONFIG_PWM_NCHANNELS);
   709	#else
   710	  int channels = 1;
   711	#endif
   712	
   713	  pwminfo("PWM timer%d\n", priv->num);
   714	
   715	  /* Update timer with given PWM timer frequency */
   716	
   717	  if (priv->frequency != info->frequency)
   718	    {
   719	      priv->frequency = info->frequency;
   720	      setup_timer(priv);
   721	    }
   722	
   723	  /* Update timer with given PWM channel duty */
   724	
   725	  for (int i = 0; i < channels; i++)
   726	    {
   727	#ifdef CONFIG_PWM_NCHANNELS
   728	      if (priv->chans[i].duty != info->channels[i].duty)
   729	#else
   730	      if (priv->chans[i].duty != info[i].duty)
   731	#endif
   732	        {
   733	#ifdef CONFIG_PWM_NCHANNELS
   734	          priv->chans[i].duty = info->channels[i].duty;
   735	#else
   736	          priv->chans[i].duty = info[i].duty;
   737	#endif
   738	          setup_channel(priv, i);
   739	        }
   740	    }
   741	
   742	  return 0;
   743	}
   744	
   745	/****************************************************************************
   746	 * Name: pwm_stop
   747	 *
   748	 * Description:
   749	 *   Stop the pulsed output and reset the timer resources.
   750	 *
   751	 * Input Parameters:
   752	 *   dev - A reference to the lower half PWM driver state structure
   753	 *
   754	 * Returned Value:
   755	 *   Zero on success; a negated errno value on failure
   756	 *
   757	 ****************************************************************************/
   758	
   759	static int pwm_stop(struct pwm_lowerhalf_s *dev)
   760	{
   761	  irqstate_t flags;
   762	  struct esp32s3_ledc_s *priv = (struct esp32s3_ledc_s *)dev;
   763	
   764	  pwminfo("PWM timer%d\n", priv->num);
   765	
   766	  flags = enter_critical_section();
   767	
   768	  /* Stop timer */
   769	
   770	  SET_TIMER_BITS(priv, LEDC_TIMER0_CONF_REG, LEDC_TIMER0_PAUSE);
   771	
   772	  /* Reset timer */
   773	
   774	  SET_TIMER_BITS(priv, LEDC_TIMER0_CONF_REG, LEDC_TIMER0_RST);
   775	
   776	  leave_critical_section(flags);
   777	  return 0;
   778	}
   779	
   780	/****************************************************************************
   781	 * Name: pwm_ioctl
   782	 *
   783	 * Description:
   784	 *   Lower-half logic may support platform-specific ioctl commands
   785	 *
   786	 * Input Parameters:
   787	 *   dev - A reference to the lower half PWM driver state structure
   788	 *   cmd - The ioctl command
   789	 *   arg - The argument accompanying the ioctl command
   790	 *
   791	 * Returned Value:
   792	 *   Zero on success; a negated errno value on failure
   793	 *
   794	 ****************************************************************************/
   795	
   796	static int pwm_ioctl(struct pwm_lowerhalf_s *dev, int cmd,
   797	                     unsigned long arg)
   798	{
   799	#ifdef CONFIG_DEBUG_PWM_INFO
   800	  struct esp32s3_ledc_s *priv = (struct esp32s3_ledc_s *)dev;
   801	
   802	  pwminfo("PWM timer%d\n", priv->num);
   803	#endif
   804	
   805	  return -ENOTTY;
   806	}
   807	
   808	/****************************************************************************
   809	 * Public Functions
   810	 ****************************************************************************/
   811	
   812	/****************************************************************************
   813	 * Name: esp32s3_ledc_init
   814	 *
   815	 * Description:
   816	 *   Initialize one LEDC timer for use with the upper_level PWM driver.
   817	 *
   818	 * Input Parameters:
   819	 *   timer - A number identifying the timer use.
   820	 *
   821	 * Returned Value:
   822	 *   On success, a pointer to the ESP32S3 LEDC lower half PWM driver is
   823	 *   returned. NULL is returned on any failure.
   824	 *
   825	 ****************************************************************************/
   826	
   827	struct pwm_lowerhalf_s *esp32s3_ledc_init(int timer)
   828	{
   829	  struct esp32s3_ledc_s *lower = NULL;
   830	
   831	  pwminfo("TIM%u\n", timer);
   832	
   833	  switch (timer)
   834	    {
   835	#ifdef CONFIG_ESP32S3_LEDC_TIM0
   836	      case 0:
   837	        lower = &g_pwm0dev;
   838	        break;
   839	#endif
   840	
   841	#ifdef CONFIG_ESP32S3_LEDC_TIM1
   842	      case 1:
   843	        lower = &g_pwm1dev;
   844	        break;
   845	#endif
   846	
   847	#ifdef CONFIG_ESP32S3_LEDC_TIM2
   848	      case 2:
   849	        lower = &g_pwm2dev;
   850	        break;
   851	#endif
   852	
   853	#ifdef CONFIG_ESP32S3_LEDC_TIM3
   854	      case 3:
   855	        lower = &g_pwm3dev;
   856	        break;
   857	#endif
   858	
   859	      default:
   860	        pwmerr("ERROR: No such timer configured %d\n", timer);
   861	        lower = NULL;
   862	        break;
   863	    }
   864	
   865	  return (struct pwm_lowerhalf_s *)lower;
   866	}

