 70	static int robotctl_clamp_angle(int angle)
 71	{
 72	  if (angle < 0)
 73	    {
 74	      return 0;
 75	    }
 76	
 77	  if (angle > 180)
 78	    {
 79	      return 180;
 80	    }
 81	
 82	  return angle;
 83	}
 84	
 85	static ub16_t robotctl_angle_to_duty(int angle)
 86	{
 87	  uint32_t pulse_us;
 88	
 89	  angle = robotctl_clamp_angle(angle);
 90	  pulse_us = ROBOTCTL_SERVO_MIN_US +
 91	             ((ROBOTCTL_SERVO_MAX_US - ROBOTCTL_SERVO_MIN_US) * angle) / 180;
 92	
 93	  return (ub16_t)(((uint64_t)pulse_us << 16) / ROBOTCTL_SERVO_PERIOD_US);
 94	}
 95	
 96	static int robotctl_duty_to_angle(ub16_t duty)
 97	{
 98	  uint32_t pulse_us;
 99	
100	  pulse_us = ((uint64_t)duty * ROBOTCTL_SERVO_PERIOD_US) >> 16;
101	  if (pulse_us < ROBOTCTL_SERVO_MIN_US ||
102	      pulse_us > ROBOTCTL_SERVO_MAX_US)
103	    {
104	      return -1;
105	    }
106	
107	  return (int)(((pulse_us - ROBOTCTL_SERVO_MIN_US) * 180) /
108	               (ROBOTCTL_SERVO_MAX_US - ROBOTCTL_SERVO_MIN_US));
109	}
