111	static int robotctl_apply_frame(struct robotctl_servo_ctx_s *ctx,
112	                                const int angle[ROBOTCTL_SERVO_COUNT],
113	                                unsigned int active_mask)
114	{
115	  struct pwm_info_s info;
116	  int saved_errno;
117	  int ret;
118	  int i;
119	
120	  memset(&info, 0, sizeof(info));
121	  info.frequency = ROBOTCTL_PWM_FREQUENCY;
122	
123	  for (i = 0; i < ROBOTCTL_SERVO_COUNT; i++)
124	    {
125	      info.channels[i].channel = i + 1;
126	      if ((active_mask & (1u << i)) != 0)
127	        {
128	          info.channels[i].duty =
129	            robotctl_angle_to_duty(angle[i] + g_trim[i]);
130	        }
131	
132	      info.channels[i].cpol = PWM_CPOL_NDEF;
133	      info.channels[i].dcpol = PWM_DCPOL_LOW;
134	    }
135	
136	  ret = ioctl(ctx->fd, PWMIOC_SETCHARACTERISTICS,
137	              (unsigned long)((uintptr_t)&info));
138	  if (ret < 0)
139	    {
140	      saved_errno = errno;
141	      fprintf(stderr,
142	              "robotctl: PWMIOC_SETCHARACTERISTICS failed errno=%d\n",
143	              saved_errno);
144	      return -saved_errno;
145	    }
146	
147	  ret = ioctl(ctx->fd, PWMIOC_START, 0);
148	  if (ret < 0)
149	    {
150	      saved_errno = errno;
151	      fprintf(stderr, "robotctl: PWMIOC_START failed errno=%d\n",
152	              saved_errno);
153	      return -saved_errno;
154	    }
155	
156	  return 0;
157	}
