201	              ROBOTCTL_PWM_PATH, saved_errno);
202	      return -saved_errno;
203	    }
204	
205	  memset(&info, 0, sizeof(info));
206	  if (ioctl(ctx->fd, PWMIOC_GETCHARACTERISTICS,
207	            (unsigned long)((uintptr_t)&info)) == 0 &&
208	      info.frequency == ROBOTCTL_PWM_FREQUENCY)
209	    {
210	      for (i = 0; i < ROBOTCTL_SERVO_COUNT; i++)
211	        {
212	          angle = robotctl_duty_to_angle(info.channels[i].duty);
213	          if (angle >= 0)
214	            {
215	              ctx->angle[i] = robotctl_clamp_angle(angle - g_trim[i]);
216	            }
217	        }
218	    }
219	
220	  return 0;
