   149	void EDARobotDog::OscillateServos(int amplitude[SERVO_COUNT],
   150	                             int offset[SERVO_COUNT], int period,
   151	                             double phase_diff[SERVO_COUNT], float cycle = 1) {
   152	  for (int i = 0; i < SERVO_COUNT; i++) {
   153	    if (servo_pins_[i] != -1) {
   154	      servo_[i].SetO(offset[i]);
   155	      servo_[i].SetA(amplitude[i]);
   156	      servo_[i].SetT(period);
   157	      servo_[i].SetPh(phase_diff[i]);
   158	    }
   159	  }
   160	
   161	  double ref = millis();
   162	  double end_time = period * cycle + ref;
   163	
   164	  while (millis() < end_time) {
   165	    for (int i = 0; i < SERVO_COUNT; i++) {
   166	      if (servo_pins_[i] != -1) {
   167	        servo_[i].Refresh();
   168	      }
   169	    }
   170	    vTaskDelay(5);
   171	  }
   172	  vTaskDelay(pdMS_TO_TICKS(10));
   173	}
