static int robotctl_servo_open_device(struct robotctl_servo_ctx_s *ctx)
{
  int saved_errno;

  ctx->fd = open(ROBOTCTL_PWM_PATH, O_RDONLY);
  if (ctx->fd < 0)
    {
      saved_errno = errno;
      fprintf(stderr, "robotctl: open %s failed errno=%d\n",
