      return -saved_errno;
    }

  return 0;
}

static void robotctl_servo_stop_and_close(struct robotctl_servo_ctx_s *ctx)
{
  if (ctx->fd >= 0)
    {
      (void)robotctl_servo_stop(ctx, false);
      robotctl_servo_close(ctx);
    }
}

/****************************************************************************
