static void voice_complete(struct i2s_dev_s *dev, struct ap_buffer_s *apb,
                           void *arg, int result)
{
  struct voice_transfer_s *transfer = arg;

  (void)dev;
  if (transfer->retain_apb && apb != NULL && result >= 0)
    {
      apb_reference(apb);
      transfer->apb = apb;
    }

  transfer->result = result;
  nxsem_post(&transfer->done);
}

static int voice_wait_transfer(struct voice_transfer_s *transfer)
{
  int ret;

  do
    {
      ret = nxsem_wait(&transfer->done);
    }
  while (ret < 0 && errno == EINTR);

  return ret < 0 ? -errno : transfer->result;
}

static int voice_buffer_alloc(struct ap_buffer_s **apb)
{
  struct audio_buf_desc_s desc;

  memset(&desc, 0, sizeof(desc));
  desc.numbytes = VOICE_DMA_BYTES;
  desc.u.pbuffer = apb;
  return apb_alloc(&desc) < 0 ? -ENOMEM : 0;
}

static int voice_configure_i2s(struct i2s_dev_s *mic,
                               struct i2s_dev_s *speaker)
{
  if (I2S_RXCHANNELS(mic, VOICE_CHANNELS) < 0 ||
      I2S_RXSAMPLERATE(mic, VOICE_INPUT_RATE) != VOICE_INPUT_RATE ||
      I2S_RXDATAWIDTH(mic, VOICE_SAMPLE_BITS) != VOICE_SAMPLE_BITS ||
      I2S_TXCHANNELS(speaker, VOICE_CHANNELS) < 0 ||
      I2S_TXSAMPLERATE(speaker, VOICE_OUTPUT_RATE) != VOICE_OUTPUT_RATE ||
      I2S_TXDATAWIDTH(speaker, VOICE_SAMPLE_BITS) != VOICE_SAMPLE_BITS)
    {
      return -ENOTSUP;
    }

  return 0;
}

static void voice_oled_pixel(uint8_t *row, unsigned int x, bool on)
{
  uint8_t mask;

#ifdef CONFIG_LCD_PACKEDMSFIRST
  mask = 0x80 >> (x & 7);
#else
  mask = 1 << (x & 7);
#endif

  if (on)
    {
      row[x >> 3] |= mask;
    }
}

static int voice_oled_show(struct voice_oled_s *oled, const char *line1,
                           const char *line2)
{
  const char *lines[2] = {line1, line2};
  uint8_t row[128 / 8];
  unsigned int y;
  int ret = 0;

  if (!oled->available)
    {
      return 0;
    }

  for (y = 0; y < 64; y++)
    {
      const char *text;
      unsigned int x;
      unsigned int charrow;

      memset(row, 0, sizeof(row));
      text = lines[y / 32];
      charrow = (y % 32) / 3;

      if (charrow < 7)
        {
          for (x = 0; text[x] != '\0' && x < 20; x++)
            {
              uint8_t glyph = (uint8_t)text[x];
              unsigned int col;

              if (glyph >= sizeof(g_font) || glyph < ' ')
                {
                  glyph = ' ';
                }

              for (col = 0; col < 5; col++)
                {
                  if ((g_font[glyph][col] & (1u << charrow)) != 0)
                    {
                      voice_oled_pixel(row, x * 6 + col, true);
                    }
                }
            }
        }

      ret = oled->plane.putrun(oled->dev, y, 0, row, 128);
      if (ret < 0)
        {
          oled->available = false;
          printf("OLED unavailable\n");
          return ret;
        }
    }

  return 0;
}

static void voice_oled_init(struct voice_oled_s *oled)
{
  memset(oled, 0, sizeof(*oled));

  if (board_oled_initialize() < 0)
    {
      printf("OLED unavailable\n");
      return;
    }

  oled->dev = board_oled_getdev();
  if (oled->dev == NULL || oled->dev->getplaneinfo(oled->dev, 0,
                                                    &oled->plane) < 0)
    {
      printf("OLED unavailable\n");
      return;
    }

  oled->available = true;
}

static int voice_record(struct i2s_dev_s *mic, int16_t *samples,
                        size_t capacity, size_t *count,
                        int16_t *minimum, int16_t *maximum, int16_t *peak)
{
  unsigned int empty_transfers = 0;

  *count = 0;
  *minimum = INT16_MAX;
  *maximum = INT16_MIN;
  *peak = 0;

  while (*count < capacity)
    {
      struct ap_buffer_s *apb;
      struct voice_transfer_s transfer;
      size_t nbytes;
      size_t nsamples;
      size_t i;
      int ret;

      ret = voice_buffer_alloc(&apb);
      if (ret < 0)
        {
          return ret;
        }

      nxsem_init(&transfer.done, 0, 0);
      transfer.result = -EINPROGRESS;
      transfer.apb = NULL;
      transfer.retain_apb = true;
      ret = I2S_RECEIVE(mic, apb, voice_complete, &transfer,
                        MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
      if (ret >= 0)
        {
          ret = voice_wait_transfer(&transfer);
        }

      nxsem_destroy(&transfer.done);
      if (ret < 0)
        {
          apb_free(apb);
          return ret;
        }

      if (transfer.apb == NULL)
        {
          apb_free(apb);
          return -EIO;
        }

      nbytes = transfer.apb->nbytes;
      nbytes -= nbytes % sizeof(int16_t);
      nbytes = nbytes > (capacity - *count) * sizeof(int16_t) ?
               (capacity - *count) * sizeof(int16_t) : nbytes;
      nsamples = nbytes / sizeof(int16_t);
      memcpy(&samples[*count], transfer.apb->samp, nbytes);
      apb_free(transfer.apb);
      apb_free(apb);

      for (i = 0; i < nsamples; i++)
        {
          int16_t value = samples[*count + i];
          int16_t absolute = value == INT16_MIN ? INT16_MAX :
                             (value < 0 ? -value : value);

          if (value < *minimum)
            {
              *minimum = value;
            }

          if (value > *maximum)
            {
              *maximum = value;
            }

          if (absolute > *peak)
            {
              *peak = absolute;
            }
        }

      *count += nsamples;
      if (nsamples == 0)
        {
          if (++empty_transfers >= 6)
            {
              return -ETIMEDOUT;
            }
        }
      else
        {
          empty_transfers = 0;
        }
    }

  return 0;
}

static int voice_play(struct i2s_dev_s *speaker, const int16_t *samples,
                      size_t count)
{
  size_t output_count = (count * VOICE_OUTPUT_RATE + VOICE_INPUT_RATE - 1) /
                        VOICE_INPUT_RATE;
  size_t output_index = 0;

  while (output_index < output_count)
    {
      struct ap_buffer_s *apb;
      struct voice_transfer_s transfer;
      size_t chunk = output_count - output_index;
      size_t i;
      int ret;

      if (chunk > VOICE_DMA_BYTES / sizeof(int16_t))
        {
          chunk = VOICE_DMA_BYTES / sizeof(int16_t);
        }

      ret = voice_buffer_alloc(&apb);
      if (ret < 0)
        {
          return ret;
        }

      for (i = 0; i < chunk; i++)
        {
          size_t source = ((output_index + i) * VOICE_INPUT_RATE) /
                          VOICE_OUTPUT_RATE;

          ((int16_t *)apb->samp)[i] = samples[source];
        }

      apb->nbytes = chunk * sizeof(int16_t);
      apb->nsamples = chunk;
      nxsem_init(&transfer.done, 0, 0);
      transfer.result = -EINPROGRESS;
      transfer.apb = NULL;
      transfer.retain_apb = false;
      ret = I2S_SEND(speaker, apb, voice_complete, &transfer,
                     MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
      if (ret >= 0)
        {
          ret = voice_wait_transfer(&transfer);
        }

      nxsem_destroy(&transfer.done);
      apb_free(apb);
      if (ret < 0)
        {
          return ret;
        }

      output_index += chunk;
    }

  return 0;
}

int main(int argc, char *argv[])
{
  struct i2s_dev_s *mic;
  struct i2s_dev_s *speaker;
  struct voice_oled_s oled;
  int16_t *samples;
  size_t capacity = VOICE_INPUT_RATE * VOICE_ECHO_RECORD_SECONDS;
  bool once_alias = argc == 2 && strcmp(argv[1], "--once") == 0;
  int ret;

  if (argc > 2 || (argc == 2 && !once_alias))
    {
      printf("Usage: voice_echo [--once]\n");
      return EXIT_FAILURE;
    }

  mic = board_voice_mic_i2s();
  speaker = board_voice_speaker_i2s();
  if (mic == NULL || speaker == NULL)
    {
      printf("I2S unavailable\n");
      return EXIT_FAILURE;
    }

  ret = voice_configure_i2s(mic, speaker);
  if (ret < 0)
    {
      printf("I2S format configuration failed: %d\n", ret);
      return EXIT_FAILURE;
    }

  samples = malloc(capacity * sizeof(*samples));
  if (samples == NULL)
    {
      printf("Record buffer allocation failed\n");
      return EXIT_FAILURE;
    }

  voice_oled_init(&oled);
  printf("MIC: I2S0 RX, SPK: I2S1 TX\n");
  printf("Rate: %d Hz -> %d Hz, slot: %d bit, sample: %d bit, mono\n",
         VOICE_INPUT_RATE, VOICE_OUTPUT_RATE, VOICE_SLOT_BITS,
         VOICE_SAMPLE_BITS);
  printf("Record duration: %d s\n", VOICE_ECHO_RECORD_SECONDS);

  {
    int16_t minimum;
    int16_t maximum;
    int16_t peak;
    size_t count;

    voice_oled_show(&oled, "REC", "5 SEC");
    printf("voice_echo: recording %d seconds...\n",
           VOICE_ECHO_RECORD_SECONDS);
    ret = voice_record(mic, samples, capacity, &count, &minimum, &maximum,
                       &peak);
    if (ret < 0)
      {
        printf("voice_echo: MIC RX failed: %d\n", ret);
        voice_oled_show(&oled, "MIC ERROR", "");
      }
    else
      {
        printf("voice_echo: captured %zu bytes\n",
               count * sizeof(*samples));
        printf("voice_echo: min=%d max=%d peak=%d\n", minimum, maximum,
               peak);
        voice_oled_show(&oled, "PLAY", "");
        printf("voice_echo: playing...\n");
        ret = voice_play(speaker, samples, count);
        if (ret < 0)
          {
            printf("voice_echo: SPK TX failed: %d\n", ret);
            voice_oled_show(&oled, "SPK ERROR", "");
          }
        else
          {
            printf("voice_echo: playback complete\n");
            voice_oled_show(&oled, "DONE", "");
          }
      }
  }

  free(samples);
  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

