int nxsem_tickwait_slow(FAR sem_t *sem, clock_t delay)
{
  FAR struct tcb_s *rtcb = this_task();
  irqstate_t flags;
  int ret = -EINVAL;

  DEBUGASSERT(sem != NULL && up_interrupt_context() == false);

  /* Try to take the semaphore without waiting. */

  if (delay != 0u)
