376	                               i2s_callback_t callback, FAR void *arg,
377	                               uint32_t timeout)
378	{
379	  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
380	  FAR struct contest_i2s_xfer_s *xfer = &priv->xfer;
381	  irqstate_t flags;
382	  size_t nbytes;
383	  uint32_t queued;
384	  uint32_t eof_samples;
385	
386	  (void)timeout;
387	
388	  if (apb == NULL || callback == NULL || apb->samp == NULL)
389	    {
390	      return -EINVAL;
391	    }
392	
393	  nbytes = apb->nmaxbytes - apb->curbyte;
394	  nbytes -= nbytes % (priv->data_width / 8);
395	  if (nbytes == 0)
396	    {
397	      return -EINVAL;
398	    }
399	
400	  flags = spin_lock_irqsave(&priv->lock);
401	  if (!priv->streaming || priv->active != NULL || priv->done != NULL)
