135	static void contest_i2s_set_rate(FAR struct contest_i2s_s *priv)
136	{
137	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
138	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
139	  uint32_t remainder = CONTEST_I2S_SOURCE_CLOCK % mclk;
140	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS * priv->data_width;
141	  uint32_t bclk_div = mclk / bclk;
142	  uint32_t regval;
143	  uint32_t numerator = 0;
144	  uint32_t denominator = 1;
145	  uint32_t a;
146	
147	  /* Match the ESP32-S3 reference driver's CLK160 fractional divider. */
148	
149	  if (remainder != 0)
150	    {
151	      for (a = 2; a <= 63; a++)
152	        {
153	          uint32_t b = (remainder * a + mclk / 2) / mclk;
154	
155	          if (b != 0 && remainder * a == mclk * b)
156	            {
157	              numerator = b;
158	              denominator = a;
159	              break;
160	            }
161	        }
162	    }
163	
164	  if (numerator == 0)
165	    {
166	      denominator = 1;
167	    }
168	
169	  regval = getreg32(I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
170	  regval &= ~I2S_RX_CLKM_DIV_NUM_M;
171	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_NUM, mclk_div);
172	  putreg32(regval, I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
173	
174	  regval = getreg32(I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
175	  regval &= ~(I2S_RX_CLKM_DIV_Z_M | I2S_RX_CLKM_DIV_Y_M |
176	              I2S_RX_CLKM_DIV_X_M | I2S_RX_CLKM_DIV_YN1_M);
177	  if (numerator != 0)
178	    {
179	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Z, numerator);
180	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Y, denominator % numerator);
180	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Y, denominator % numerator);
181	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_X,
182	                               denominator / numerator - 1);
183	    }
184	
185	  putreg32(regval, I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
186	
187	  modifyreg32(I2S_RX_CONF1_REG(CONTEST_I2S_PORT), I2S_RX_BCK_DIV_NUM_M,
188	              FIELD_TO_VALUE(I2S_RX_BCK_DIV_NUM, bclk_div - 1));
189	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_UPDATE);
190	}
