192	static void contest_i2s_rx_worker(FAR void *arg)
193	{
194	  FAR struct contest_i2s_s *priv = arg;
195	  FAR struct contest_i2s_xfer_s *xfer;
196	  FAR struct ap_buffer_s *apb;
197	  i2s_callback_t callback;
198	  FAR void *callback_arg;
199	  int result;
200	  uint32_t irq_status;
201	  irqstate_t flags;
202	  size_t nbytes = 0;
203	  unsigned int i;
204	
205	  flags = spin_lock_irqsave(&priv->lock);
206	  xfer = priv->done;
207	  priv->done = NULL;
208	  irq_status = priv->irq_status;
209	  spin_unlock_irqrestore(&priv->lock, flags);
210	
211	  if (xfer == NULL)
212	    {
213	      return;
214	    }
215	
216	  for (i = 0; i < CONTEST_I2S_DMA_DESC_COUNT; i++)
217	    {
218	      uint32_t length = (xfer->desc[i].ctrl >>
219	                         ESP32S3_DMA_CTRL_DATALEN_S) &
220	                        ESP32S3_DMA_CTRL_DATALEN_V;
221	
222	      nbytes += length;
223	      if (xfer->desc[i].next == NULL)
224	        {
225	          break;
226	        }
227	    }
228	
229	  if (nbytes > xfer->nbytes)
230	    {
231	      nbytes = xfer->nbytes;
232	    }
233	
234	  xfer->apb->nbytes = nbytes;
235	  xfer->apb->nsamples = nbytes / (priv->data_width / 8);
236	
237	  /* The callback can cause the next transaction to be submitted.  Save all
238	   * current transaction state before invoking it because the single static
239	   * transaction object may then be reused by I2S_RECEIVE.
240	   */
241	
242	  apb = xfer->apb;
243	  callback = xfer->callback;
244	  callback_arg = xfer->arg;
245	  result = xfer->result;
246	
247	  syslog(LOG_INFO, "[C-I2S] rx irq status=%08lx\n",
248	         (unsigned long)irq_status);
249	  syslog(LOG_INFO, "[C-I2S] rx worker bytes=%zu\n", nbytes);
250	  syslog(LOG_INFO, "[C-I2S] rx callback\n");
251	  callback(&priv->dev, apb, callback_arg, result);
252	  apb_free(apb);
253	}
