   193	static void contest_i2s_rx_worker(FAR void *arg)
   194	{
   195	  FAR struct contest_i2s_s *priv = arg;
   196	  FAR struct contest_i2s_xfer_s *xfer;
   197	  FAR struct ap_buffer_s *apb;
   198	  i2s_callback_t callback;
   199	  FAR void *callback_arg;
   200	  int result;
   201	  uint32_t irq_status;
   202	  irqstate_t flags;
   203	  size_t nbytes = 0;
   204	  unsigned int i;
   205	
   206	  flags = spin_lock_irqsave(&priv->lock);
   207	  xfer = priv->done;
   208	  priv->done = NULL;
   209	  irq_status = priv->irq_status;
   210	  spin_unlock_irqrestore(&priv->lock, flags);
   211	
   212	  if (xfer == NULL)
   213	    {
   214	      return;
   215	    }
   216	
   217	  for (i = 0; i < CONTEST_I2S_DMA_DESC_COUNT; i++)
   218	    {
   219	      uint32_t length = (xfer->desc[i].ctrl >>
   220	                         ESP32S3_DMA_CTRL_DATALEN_S) &
   221	                        ESP32S3_DMA_CTRL_DATALEN_V;
   222	
   223	      nbytes += length;
   224	      if (xfer->desc[i].next == NULL)
   225	        {
   226	          break;
   227	        }
   228	    }
   229	
   230	  if (nbytes > xfer->nbytes)
   231	    {
   232	      nbytes = xfer->nbytes;
   233	    }
   234	
   235	  xfer->apb->nbytes = nbytes;
   236	  xfer->apb->nsamples = nbytes / (priv->data_width / 8);
   237	
   238	  /* The callback can cause the next transaction to be submitted.  Save all
   239	   * current transaction state before invoking it because the single static
   240	   * transaction object may then be reused by I2S_RECEIVE.
   241	   */
   242	
   243	  apb = xfer->apb;
   244	  callback = xfer->callback;
   245	  callback_arg = xfer->arg;
   246	  result = xfer->result;
   247	
   248	  syslog(LOG_INFO, "[C-I2S] rx irq status=%08lx\n",
   249	         (unsigned long)irq_status);
   250	  syslog(LOG_INFO, "[C-I2S] rx worker bytes=%zu\n", nbytes);
   251	  syslog(LOG_INFO, "[C-I2S] rx callback\n");
   252	  callback(&priv->dev, apb, callback_arg, result);
   253	  apb_free(apb);
   254	}
