   260	  uint32_t status;
   261	  irqstate_t flags;
   262	
   263	  (void)irq;
   264	  (void)context;
   265	
   266	  status = GET_GDMA_CH_REG(DMA_IN_INT_ST_CH0_REG, priv->dma_channel);
   267	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
   268	
