   425	  queued = esp32s3_dma_setup(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
   426	                              apb->samp + apb->curbyte, nbytes, false,
   427	                              priv->dma_channel);
   428	  if (queued != nbytes)
   429	    {
   430	      flags = spin_lock_irqsave(&priv->lock);
   431	      priv->reserved = false;
   432	      spin_unlock_irqrestore(&priv->lock, flags);
   433	      apb_free(apb);
   434	      return -ENOMEM;
   435	    }
   436	
   437	  eof_samples = nbytes * 8 / priv->data_width;
   438	  if (eof_samples == 0 || eof_samples > I2S_RX_EOF_NUM_V + 1)
   439	    {
   440	      flags = spin_lock_irqsave(&priv->lock);
   441	      priv->reserved = false;
   442	      spin_unlock_irqrestore(&priv->lock, flags);
   443	      apb_free(apb);
   444	      return -EINVAL;
   445	    }
   446	
   447	  /* Publish active before enabling EOF so a completion cannot be lost. */
   448	
   449	  flags = spin_lock_irqsave(&priv->lock);
   450	  if (!priv->streaming)
   451	    {
   452	      priv->reserved = false;
   453	      spin_unlock_irqrestore(&priv->lock, flags);
   454	      apb_free(apb);
   455	      return -ECANCELED;
   456	    }
   457	
   458	  priv->active = xfer;
   459	  priv->reserved = false;
   460	  esp32s3_dma_load(xfer->desc, priv->dma_channel, false);
   461	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
   462	  SET_GDMA_CH_BITS(DMA_IN_INT_ENA_CH0_REG, priv->dma_channel,
   463	                   DMA_IN_SUC_EOF_CH0_INT_ENA | DMA_IN_ERR_EOF_CH0_INT_ENA);
   464	  modifyreg32(I2S_RXEOF_NUM_REG(CONTEST_I2S_PORT), I2S_RX_EOF_NUM_M,
   465	              FIELD_TO_VALUE(I2S_RX_EOF_NUM, eof_samples - 1));
   466	  esp32s3_dma_enable(priv->dma_channel, false);
   467	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_START);
   468	  spin_unlock_irqrestore(&priv->lock, flags);
   469	
   470	  syslog(LOG_INFO, "[C-I2S] rx submit bytes=%zu\n", nbytes);
   471	  syslog(LOG_INFO, "[C-I2S] rx dma start eof=%lu\n",
   472	         (unsigned long)(eof_samples - 1));
   473	  return OK;
   474	}
