   115	static void voice_complete(struct i2s_dev_s *dev, struct ap_buffer_s *apb,
   116	                           void *arg, int result)
   117	{
   118	  struct voice_transfer_s *transfer = arg;
   119	  size_t nbytes = apb == NULL ? 0 : apb->nbytes;
   120	  bool abandoned;
   121	
   122	  (void)dev;
   123	
   124	  if (transfer->log_rx)
   125	    {
   126	      printf("voice_echo: RX callback chunk=%u result=%d bytes=%zu\n",
   127	             transfer->chunk, result, nbytes);
   128	      voice_rx_release();
   129	    }
   130	
   131	  nxmutex_lock(&transfer->lock);
   132	  abandoned = transfer->abandoned;
   133	
   134	  if (abandoned)
   135	    {
   136	      /* The lower-half still owns one reference and will release it after
   137	       * this callback.  Release the application's original reference here.
   138	       */
   139	
   140	      nxmutex_unlock(&transfer->lock);
   141	      if (apb != NULL)
   142	        {
   143	          apb_free(apb);
   144	        }
   145	      nxmutex_destroy(&transfer->lock);
   146	      nxsem_destroy(&transfer->done);
   147	      free(transfer);
   148	      return;
   149	    }
   150	
   151	  if (transfer->retain_apb && apb != NULL && result >= 0)
   152	    {
   153	      apb_reference(apb);
   154	      transfer->apb = apb;
   155	    }
   156	
   157	  transfer->result = result;
   158	  transfer->callback_done = true;
   159	  nxsem_post(&transfer->done);
   160	  nxmutex_unlock(&transfer->lock);
   161	}
