   163	static int voice_wait_transfer(struct voice_transfer_s *transfer,
   164	                               clock_t timeout)
   165	{
   166	  int ret;
   167	
   168	  do
   169	    {
   170	      ret = nxsem_tickwait(&transfer->done, timeout);
   171	    }
   172	  while (ret == -EINTR);
   173	
   174	  if (ret >= 0)
   175	    {
   176	      nxmutex_lock(&transfer->lock);
   177	      ret = transfer->result;
   178	      nxmutex_unlock(&transfer->lock);
   179	    }
   180	
   181	  return ret;
   182	}
   183	
   184	static int voice_wait_transfer_unbounded(struct voice_transfer_s *transfer)
   185	{
   186	  int ret;
   187	
   188	  do
   189	    {
   190	      ret = nxsem_wait(&transfer->done);
   191	    }
   192	  while (ret < 0 && errno == EINTR);
   193	
   194	  return ret < 0 ? -errno : transfer->result;
   195	}
