   200	  if (transfer->callback_done)
   201	    {
   202	      nxmutex_unlock(&transfer->lock);
   203	      return false;
   204	    }
   205	
   206	  transfer->abandoned = true;
   207	  nxmutex_unlock(&transfer->lock);
   208	  return true;
   209	}
