   314	  const char *lines[2] = {line1, line2};
   315	  uint8_t row[128 / 8];
   316	  unsigned int y;
   317	  int ret = 0;
   318	
   319	  if (!oled->available)
   320	    {
   321	      return 0;
   322	    }
