   332	      charrow = (y % 32) / 3;
   333	
   334	      if (charrow < 7)
   335	        {
   336	          for (x = 0; text[x] != '\0' && x < 20; x++)
   337	            {
   338	              uint8_t glyph = (uint8_t)text[x];
   339	              unsigned int col;
   340	
   341	              if (glyph >= sizeof(g_font) || glyph < ' ')
   342	                {
   343	                  glyph = ' ';
   344	                }
   345	
   346	              for (col = 0; col < 5; col++)
   347	                {
   348	                  if ((g_font[glyph][col] & (1u << charrow)) != 0)
   349	                    {
   350	                      voice_oled_pixel(row, x * 6 + col, true);
   351	                    }
   352	                }
   353	            }
   354	        }
   355	
   356	      ret = oled->plane.putrun(oled->dev, y, 0, row, 128);
   357	      if (ret < 0)
   358	        {
   359	          oled->available = false;
   360	          printf("OLED unavailable\n");
   361	          return ret;
   362	        }
   363	    }
   364	
   365	  return 0;
   366	}
