   389	static int voice_record(struct i2s_dev_s *mic, int16_t *samples,
   390	                        size_t capacity, size_t *count,
   391	                        int16_t *minimum, int16_t *maximum, int16_t *peak)
   392	{
   393	  unsigned int empty_transfers = 0;
   394	  unsigned int chunk = 0;
   395	  clock_t deadline;
   396	  int ret;
   397	
   398	  *count = 0;
   399	  *minimum = INT16_MAX;
   400	  *maximum = INT16_MIN;
   401	  *peak = 0;
   402	
   403	  ret = I2S_IOCTL(mic, AUDIOIOC_START, 0);
   404	  printf("voice_echo: MIC start ret=%d\n", ret);
   405	  if (ret < 0)
   406	    {
   407	      return ret;
   408	    }
   409	
   410	  deadline = clock_systime_ticks() + MSEC2TICK(VOICE_RECORD_TIMEOUT_MS);
   411	
   412	  while (*count < capacity)
   413	    {
   414	      struct ap_buffer_s *apb;
   415	      struct voice_transfer_s *transfer;
   416	      size_t nbytes;
   417	      size_t nsamples;
   418	      size_t i;
   419	      clock_t remaining;
   420	      clock_t wait_ticks;
   421	      size_t request_bytes;
   422	      bool submitted;
   423	
   424	      request_bytes = MIN(VOICE_DMA_BYTES,
   425	                          (capacity - *count) * sizeof(int16_t));
   426	      ret = voice_buffer_alloc(&apb, request_bytes);
   427	      if (ret < 0)
   428	        {
   429	          goto errout;
   430	        }
   431	
   432	      transfer = calloc(1, sizeof(*transfer));
   433	      if (transfer == NULL)
   434	        {
   435	          apb_free(apb);
   436	          ret = -ENOMEM;
   437	          goto errout;
   438	        }
   439	
   440	      voice_transfer_init(transfer, true, true, chunk);
   441	
   442	      remaining = deadline - clock_systime_ticks();
   443	      if ((int32_t)remaining <= 0)
   444	        {
   445	          voice_transfer_destroy(transfer);
   446	          free(transfer);
   447	          apb_free(apb);
   448	          ret = -ETIMEDOUT;
   449	          goto errout;
   450	        }
   451	
   452	      wait_ticks = MIN(MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS), remaining);
   453	      if (!voice_rx_claim())
   454	        {
   455	          printf("voice_echo: previous RX transaction still pending\n");
   456	          voice_transfer_destroy(transfer);
   457	          free(transfer);
   458	          apb_free(apb);
   459	          ret = -EBUSY;
   460	          goto errout;
   461	        }
   462	
   463	      printf("voice_echo: RX submit chunk=%u bytes=%zu\n", chunk,
   464	             request_bytes);
   465	      ret = I2S_RECEIVE(mic, apb, voice_complete, transfer, wait_ticks);
   466	      submitted = ret >= 0;
   467	      if (!submitted)
   468	        {
   469	          voice_rx_release();
   470	        }
   471	      printf("voice_echo: RX submit chunk=%u ret=%d\n", chunk, ret);
   472	      if (submitted)
   473	        {
   474	          ret = voice_wait_transfer(transfer, wait_ticks);
   475	        }
   476	
   477	      if (ret < 0)
   478	        {
   479	          printf("voice_echo: RX wait chunk=%u failed: %d\n", chunk, ret);
   480	          if (submitted && ret == -ETIMEDOUT)
   481	            {
   482	              /* The ESP32-S3 lower-half currently does not cancel an
   483	               * enqueued RX transaction on its timeout field.  Keep the
   484	               * context alive for a late callback instead of creating a
   485	               * use-after-free.  The callback releases the APB and context.
   486	               */
   487	
   488	              if (voice_abandon_transfer(transfer))
   489	                {
   490	                  (void)I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
   491	                  goto errout;
   492	                }
   493	
   494	              nxmutex_lock(&transfer->lock);
   495	              ret = transfer->result;
   496	              nxmutex_unlock(&transfer->lock);
   497	            }
   498	          else
   499	            {
   500	              voice_transfer_destroy(transfer);
   501	              free(transfer);
   502	              apb_free(apb);
   503	            }
   504	
   505	          if (ret < 0)
   506	            {
   507	              goto errout;
   508	            }
   509	        }
   510	
   511	      voice_transfer_destroy(transfer);
   512	      if (transfer->apb == NULL)
   513	        {
   514	          free(transfer);
   515	          apb_free(apb);
   516	          ret = -EIO;
   517	          goto errout;
   518	        }
   519	
   520	      nbytes = transfer->apb->nbytes;
   521	      nbytes -= nbytes % sizeof(int16_t);
   522	      nbytes = nbytes > (capacity - *count) * sizeof(int16_t) ?
   523	               (capacity - *count) * sizeof(int16_t) : nbytes;
   524	      nsamples = nbytes / sizeof(int16_t);
