  1186	#ifdef I2S_HAVE_TX
  1187	static void i2s_tx_worker(void *arg)
  1188	{
  1189	  struct esp32s3_i2s_s *priv = (struct esp32s3_i2s_s *)arg;
  1190	  struct esp32s3_buffer_s *bfcontainer;
  1191	  irqstate_t flags;
  1192	
  1193	  DEBUGASSERT(priv);
  1194	
  1195	  /* When the transfer was started, the active buffer containers were removed
  1196	   * from the tx.pend queue and saved in the tx.act queue.  We get here when
  1197	   * the DMA is finished.
  1198	   *
  1199	   * In any case, the buffer containers in tx.act will be moved to the end
  1200	   * of the tx.done queue and tx.act will be emptied before this worker is
  1201	   * started.
  1202	   *
  1203	   */
  1204	
  1205	  i2sinfo("tx.act.head=%p tx.done.head=%p\n",
  1206	          priv->tx.act.head, priv->tx.done.head);
  1207	
  1208	  /* Process each buffer in the tx.done queue */
  1209	
  1210	  while (sq_peek(&priv->tx.done) != NULL)
  1211	    {
  1212	      /* Remove the buffer container from the tx.done queue.  NOTE that
  1213	       * interrupts must be disabled to do this because the tx.done queue is
  1214	       * also modified from the interrupt level.
  1215	       */
  1216	
  1217	      flags = spin_lock_irqsave(&priv->slock);
  1218	      bfcontainer = (struct esp32s3_buffer_s *)sq_remfirst(&priv->tx.done);
  1219	      spin_unlock_irqrestore(&priv->slock, flags);
  1220	
  1221	      /* Perform the TX transfer done callback */
  1222	
  1223	      DEBUGASSERT(bfcontainer && bfcontainer->callback);
  1224	      bfcontainer->callback(&priv->dev, bfcontainer->apb,
  1225	                            bfcontainer->arg, bfcontainer->result);
  1226	
  1227	      /* Release the internal buffer used by the DMA outlink */
  1228	
  1229	      free(bfcontainer->buf);
  1230	
  1231	      /* And release the buffer container */
  1232	
  1233	      i2s_buf_free(priv, bfcontainer);
  1234	    }
  1235	}
