+  /* This is the CLK160 fractional-divider procedure used by the reference
+   * ESP32-S3 I2S lower-half.  At 24 kHz it resolves to 26 + 1/24.
+   */
+
+  if (freq_diff != 0)
+    {
+      for (a = 2; a <= 63; a++)
+        {
+          uint32_t b = (freq_diff * a + mclk / 2) / mclk;
+
+          if (b != 0 && freq_diff * a == mclk * b)
+            {
+              numerator = b;
+              denominator = a;
+              break;
+            }
+        }
+    }
