+      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Y, denominator % numerator);
+      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_X,
+                               denominator / numerator - 1);
+    }
