   691	  struct voice_oled_s oled;
   692	  int16_t *samples;
   693	  size_t capacity = VOICE_INPUT_RATE * VOICE_ECHO_RECORD_SECONDS;
   694	  bool once_alias = argc == 2 && strcmp(argv[1], "--once") == 0;
   695	  int ret;
   696	
   697	  if (argc > 2 || (argc == 2 && !once_alias))
   698	    {
   699	      printf("Usage: voice_echo [--once]\n");
   700	      return EXIT_FAILURE;
   500	    }
   501	
   502	  /* Publish active before enabling EOF so a completion cannot be lost. */
   503	
   504	  flags = spin_lock_irqsave(&priv->lock);
   505	  if (!priv->streaming)
   506	    {
   507	      priv->reserved = false;
   508	      spin_unlock_irqrestore(&priv->lock, flags);
   509	      apb_free(apb);
   510	      return -ECANCELED;
   511	    }
   512	
   513	  priv->active = xfer;
   514	  priv->reserved = false;
   515	  esp32s3_dma_load(xfer->desc, priv->dma_channel, false);
   516	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
   517	  SET_GDMA_CH_BITS(DMA_IN_INT_ENA_CH0_REG, priv->dma_channel,
   518	                   DMA_IN_SUC_EOF_CH0_INT_ENA | DMA_IN_ERR_EOF_CH0_INT_ENA);
   519	  modifyreg32(I2S_RXEOF_NUM_REG(CONTEST_I2S_PORT), I2S_RX_EOF_NUM_M,
   520	              FIELD_TO_VALUE(I2S_RX_EOF_NUM, eof_samples - 1));
   521	  esp32s3_dma_enable(priv->dma_channel, false);
   522	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_START);
   523	  spin_unlock_irqrestore(&priv->lock, flags);
   524	
   525	  syslog(LOG_INFO, "[C-I2S] rx submit bytes=%zu\n", nbytes);
   526	  syslog(LOG_INFO, "[C-I2S] rx dma start eof=%lu\n",
   527	         (unsigned long)(eof_samples - 1));
   528	  return OK;
   529	}
