   531	static int contest_i2s_ioctl(FAR struct i2s_dev_s *dev, int cmd,
   532	                             unsigned long arg)
   533	{
   534	  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
   535	  FAR struct contest_i2s_xfer_s *xfer = NULL;
   536	  irqstate_t flags;
   537	
   538	  (void)arg;
   539	
   540	  switch (cmd)
   541	    {
   542	      case AUDIOIOC_START:
   543	        priv->streaming = true;
   544	        return OK;
   545	
   546	      case AUDIOIOC_STOP:
   547	        flags = spin_lock_irqsave(&priv->lock);
   548	        priv->streaming = false;
   549	        if (priv->active != NULL)
   550	          {
   551	            xfer = priv->active;
   552	            xfer->result = -ECANCELED;
   553	            priv->done = xfer;
   554	            priv->active = NULL;
   555	            contest_i2s_stop_hw(priv);
   556	          }
   557	
   558	        spin_unlock_irqrestore(&priv->lock, flags);
   559	        if (xfer != NULL)
   560	          {
   561	            work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker,
   562	                       priv, 0);
   563	          }
   564	
   565	        return OK;
   566	
   567	      default:
   568	        return -ENOTTY;
   569	    }
   570	}
