   615	static void contest_i2s_tx_set_format(FAR struct contest_i2s_tx_s *priv)
   616	{
   617	  uint32_t value = priv->data_width - 1;
   618	
   619	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT), I2S_TX_BITS_MOD_M,
   620	              FIELD_TO_VALUE(I2S_TX_BITS_MOD, value));
   621	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT),
   622	              I2S_TX_TDM_CHAN_BITS_M,
   623	              FIELD_TO_VALUE(I2S_TX_TDM_CHAN_BITS, value));
   624	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT),
   625	              I2S_TX_HALF_SAMPLE_BITS_M,
   626	              FIELD_TO_VALUE(I2S_TX_HALF_SAMPLE_BITS, value));
   627	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT),
   628	              I2S_TX_TDM_WS_WIDTH_M,
   629	              FIELD_TO_VALUE(I2S_TX_TDM_WS_WIDTH, value));
   630	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_UPDATE);
   631	}
