   633	static void contest_i2s_tx_set_rate(FAR struct contest_i2s_tx_s *priv)
   634	{
   635	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
   636	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
   637	  uint32_t freq_diff = CONTEST_I2S_SOURCE_CLOCK % mclk;
   638	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS * priv->data_width;
   639	  uint32_t bclk_div = mclk / bclk;
   640	  uint32_t numerator = 0;
   641	  uint32_t denominator = 1;
   642	  uint32_t regval;
   643	  uint32_t a;
   644	
   645	  /* This is the CLK160 fractional-divider procedure used by the reference
   646	   * ESP32-S3 I2S lower-half.  At 24 kHz it resolves to 26 + 1/24.
   647	   */
   648	
   649	  if (freq_diff != 0)
   650	    {
   651	      for (a = 2; a <= 63; a++)
   652	        {
   653	          uint32_t b = (freq_diff * a + mclk / 2) / mclk;
   654	
   655	          if (b != 0 && freq_diff * a == mclk * b)
   656	            {
   657	              numerator = b;
   658	              denominator = a;
   659	              break;
   660	            }
   661	        }
   662	    }
   663	
   664	  regval = getreg32(I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
   665	  regval &= ~I2S_TX_CLKM_DIV_NUM_M;
   666	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_NUM, mclk_div);
   667	  putreg32(regval, I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
   668	
   669	  regval = getreg32(I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT));
   670	  regval &= ~(I2S_TX_CLKM_DIV_Z_M | I2S_TX_CLKM_DIV_Y_M |
   671	              I2S_TX_CLKM_DIV_X_M | I2S_TX_CLKM_DIV_YN1_M);
   672	  if (numerator != 0)
   673	    {
   674	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Z, numerator);
   675	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Y, denominator % numerator);
   676	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_X,
   677	                               denominator / numerator - 1);
   678	    }
   679	
   680	  putreg32(regval, I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT));
   681	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT), I2S_TX_BCK_DIV_NUM_M,
   682	              FIELD_TO_VALUE(I2S_TX_BCK_DIV_NUM, bclk_div - 1));
   683	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_UPDATE);
   684	}
