   699	  esp32s3_gpio_matrix_out(AUDIO_I2S_SPK_GPIO_LRCK, I2S1O_WS_OUT_IDX, 0, 0);
   700	  esp32s3_gpiowrite(AUDIO_I2S_SPK_GPIO_BCLK, 1);
   701	  esp32s3_configgpio(AUDIO_I2S_SPK_GPIO_BCLK, OUTPUT_FUNCTION_2);
   702	  esp32s3_gpio_matrix_out(AUDIO_I2S_SPK_GPIO_BCLK, I2S1O_BCK_OUT_IDX, 0, 0);
   703	  esp32s3_gpiowrite(AUDIO_I2S_SPK_GPIO_DOUT, 1);
   704	  esp32s3_configgpio(AUDIO_I2S_SPK_GPIO_DOUT, OUTPUT_FUNCTION_2);
   705	  esp32s3_gpio_matrix_out(AUDIO_I2S_SPK_GPIO_DOUT, I2S1O_SD_OUT_IDX, 0, 0);
   706	
   707	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_RESET);
   708	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), I2S_TX_RESET, 0);
   709	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0,
   710	              I2S_TX_FIFO_RESET);
   711	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), I2S_TX_FIFO_RESET, 0);
   712	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), I2S_TX_SLAVE_MOD, 0);
   713	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), I2S_TX_TDM_EN_M,
   714	              I2S_TX_TDM_EN);
   715	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT), I2S_TX_MSB_SHIFT_M,
   716	              I2S_TX_MSB_SHIFT);
   717	  contest_i2s_tx_set_format(priv);
   718	  contest_i2s_tx_set_rate(priv);
   719	
   720	  syslog(LOG_INFO, "[C-I2S] tx gpio configured\n");
   721	  syslog(LOG_INFO, "[C-I2S] tx rate=%lu width=%u\n",
   722	         (unsigned long)priv->rate, priv->data_width);
   723	}
