   725	static void contest_i2s_tx_worker(FAR void *arg)
   726	{
   727	  FAR struct contest_i2s_tx_s *priv = arg;
   728	  FAR struct contest_i2s_xfer_s *xfer;
   729	  FAR struct ap_buffer_s *apb;
   730	  i2s_callback_t callback;
   731	  FAR void *callback_arg;
   732	  uint32_t irq_status;
   733	  int result;
   734	  irqstate_t flags;
   735	
   736	  flags = spin_lock_irqsave(&priv->lock);
   737	  xfer = priv->done;
   738	  priv->done = NULL;
   739	  irq_status = priv->irq_status;
   740	  spin_unlock_irqrestore(&priv->lock, flags);
   741	
   742	  if (xfer == NULL)
   743	    {
   744	      return;
   745	    }
   746	
   747	  /* A completion callback may submit the next transaction.  Save the
   748	   * completed transaction before the single static context can be reused.
   749	   */
   750	
   751	  apb = xfer->apb;
   752	  callback = xfer->callback;
   753	  callback_arg = xfer->arg;
   754	  result = xfer->result;
   755	
   756	  syslog(LOG_INFO, "[C-I2S] tx irq status=%08lx\n",
   757	         (unsigned long)irq_status);
   758	  syslog(LOG_INFO, "[C-I2S] tx worker bytes=%zu\n", xfer->nbytes);
   759	  syslog(LOG_INFO, "[C-I2S] tx callback\n");
   760	  callback(&priv->dev, apb, callback_arg, result);
   761	  apb_free(apb);
   762	}
