   764	static int contest_i2s_tx_interrupt(int irq, FAR void *context, FAR void *arg)
   765	{
   766	  FAR struct contest_i2s_tx_s *priv = arg;
   767	  uint32_t status;
   768	  irqstate_t flags;
   769	
   770	  (void)irq;
   771	  (void)context;
   772	
   773	  status = GET_GDMA_CH_REG(DMA_OUT_INT_ST_CH0_REG, priv->dma_channel);
   774	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
   775	
   776	  if ((status & (DMA_OUT_TOTAL_EOF_CH0_INT_ST |
   777	                 DMA_OUT_DSCR_ERR_CH0_INT_ST)) == 0)
   778	    {
   779	      return OK;
   780	    }
   781	
   782	  flags = spin_lock_irqsave(&priv->lock);
   783	  if (priv->active != NULL)
   784	    {
   785	      priv->active->result = (status & DMA_OUT_TOTAL_EOF_CH0_INT_ST) != 0 ?
   786	                             OK : -EIO;
   787	      priv->done = priv->active;
   788	      priv->active = NULL;
   789	      priv->irq_status = status;
   790	      contest_i2s_tx_stop_hw(priv);
   791	      work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker, priv, 0);
   792	    }
   793	
   794	  spin_unlock_irqrestore(&priv->lock, flags);
   795	  return OK;
   796	}
