   842	static int contest_i2s_send(FAR struct i2s_dev_s *dev,
   843	                            FAR struct ap_buffer_s *apb,
   844	                            i2s_callback_t callback, FAR void *arg,
   845	                            uint32_t timeout)
   846	{
   847	  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;
   848	  FAR struct contest_i2s_xfer_s *xfer = &priv->xfer;
   849	  irqstate_t flags;
   850	  uint32_t queued;
   851	  size_t nbytes;
   852	  unsigned int last;
   853	
   854	  (void)timeout;
   855	
   856	  if (apb == NULL || callback == NULL || apb->samp == NULL)
   857	    {
   858	      return -EINVAL;
   859	    }
   860	
   861	  nbytes = apb->nbytes - apb->curbyte;
   862	  nbytes -= nbytes % (priv->data_width / 8);
   863	  if (nbytes == 0)
   864	    {
   865	      return -EINVAL;
   866	    }
   867	
   868	  apb_reference(apb);
   869	  flags = spin_lock_irqsave(&priv->lock);
   870	  if (!priv->streaming || priv->reserved || priv->active != NULL ||
   871	      priv->done != NULL)
   872	    {
   873	      spin_unlock_irqrestore(&priv->lock, flags);
   874	      apb_free(apb);
   875	      return -EBUSY;
