   191	              I2S_RX_HALF_SAMPLE_BITS_M,
   192	              FIELD_TO_VALUE(I2S_RX_HALF_SAMPLE_BITS, value));
   193	  modifyreg32(I2S_RX_CONF1_REG(CONTEST_I2S_PORT), I2S_RX_TDM_WS_WIDTH_M,
   194	              FIELD_TO_VALUE(I2S_RX_TDM_WS_WIDTH, 1));
