   198	static void contest_i2s_set_rate(FAR struct contest_i2s_s *priv)
   199	{
   200	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
   201	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
   202	  uint32_t remainder = CONTEST_I2S_SOURCE_CLOCK % mclk;
   203	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS * priv->data_width;
   204	  uint32_t bclk_div = mclk / bclk;
   205	  uint32_t regval;
   206	  uint32_t numerator = 0;
   207	  uint32_t denominator = 1;
   208	  uint32_t a;
   209	
   210	  /* Match the ESP32-S3 reference driver's CLK160 fractional divider. */
   211	
   212	  if (remainder != 0)
   213	    {
   214	      for (a = 2; a <= 63; a++)
   215	        {
   216	          uint32_t b = (remainder * a + mclk / 2) / mclk;
   217	
   218	          if (b != 0 && remainder * a == mclk * b)
   219	            {
   220	              numerator = b;
   221	              denominator = a;
   222	              break;
   223	            }
   224	        }
   225	    }
   226	
   227	  if (numerator == 0)
   228	    {
   229	      denominator = 1;
   230	    }
   231	
   232	  regval = getreg32(I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
   233	  regval &= ~I2S_RX_CLKM_DIV_NUM_M;
   234	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_NUM, mclk_div);
   235	  putreg32(regval, I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
   236	
   237	  regval = getreg32(I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
   238	  regval &= ~(I2S_RX_CLKM_DIV_Z_M | I2S_RX_CLKM_DIV_Y_M |
   239	              I2S_RX_CLKM_DIV_X_M | I2S_RX_CLKM_DIV_YN1_M);
   240	  if (numerator != 0)
   241	    {
   242	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Z, numerator);
   243	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Y, denominator % numerator);
   244	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_X,
   245	                               denominator / numerator - 1);
   246	    }
   247	
   248	  putreg32(regval, I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
   249	
   250	  modifyreg32(I2S_RX_CONF1_REG(CONTEST_I2S_PORT), I2S_RX_BCK_DIV_NUM_M,
   251	              FIELD_TO_VALUE(I2S_RX_BCK_DIV_NUM, bclk_div - 1));
   252	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_UPDATE);
   253	}
