   255	static void contest_i2s_rx_worker(FAR void *arg)
   256	{
   257	  FAR struct contest_i2s_s *priv = arg;
   258	  FAR struct contest_i2s_xfer_s *xfer;
   259	  FAR struct ap_buffer_s *apb;
   260	  i2s_callback_t callback;
   261	  FAR void *callback_arg;
   262	  int result;
   263	  uint32_t irq_status;
   264	  irqstate_t flags;
   265	  size_t nbytes = 0;
   266	  unsigned int i;
   267	
   268	  flags = spin_lock_irqsave(&priv->lock);
   269	  xfer = priv->done;
   270	  priv->done = NULL;
   271	  irq_status = priv->irq_status;
   272	  spin_unlock_irqrestore(&priv->lock, flags);
   273	
   274	  if (xfer == NULL)
   275	    {
   276	      return;
   277	    }
   278	
   279	  for (i = 0; i < CONTEST_I2S_DMA_DESC_COUNT; i++)
   280	    {
   281	      uint32_t length = (xfer->desc[i].ctrl >>
   282	                         ESP32S3_DMA_CTRL_DATALEN_S) &
   283	                        ESP32S3_DMA_CTRL_DATALEN_V;
   284	
   285	      nbytes += length;
   286	      if (xfer->desc[i].next == NULL)
   287	        {
   288	          break;
   289	        }
   290	    }
   291	
   292	  if (nbytes > xfer->nbytes)
   293	    {
   294	      nbytes = xfer->nbytes;
   295	    }
   296	
   297	  xfer->apb->nbytes = nbytes;
   298	  xfer->apb->nsamples = nbytes / (priv->data_width / 8);
   299	
   300	  /* The callback can cause the next transaction to be submitted.  Save all
   301	   * current transaction state before invoking it because the single static
   302	   * transaction object may then be reused by I2S_RECEIVE.
   303	   */
   304	
   305	  apb = xfer->apb;
   306	  callback = xfer->callback;
   307	  callback_arg = xfer->arg;
   308	  result = xfer->result;
   309	
   310	  syslog(LOG_INFO, "[C-I2S] rx irq status=%08lx\n",
   311	         (unsigned long)irq_status);
   312	  syslog(LOG_INFO, "[C-I2S] rx worker bytes=%zu\n", nbytes);
   313	  syslog(LOG_INFO, "[C-I2S] rx callback\n");
   314	  callback(&priv->dev, apb, callback_arg, result);
   315	  apb_free(apb);
   316	}
