   318	static int contest_i2s_rx_interrupt(int irq, FAR void *context,
   319	                                    FAR void *arg)
   320	{
   321	  FAR struct contest_i2s_s *priv = arg;
   322	  uint32_t status;
   323	  irqstate_t flags;
   324	
   325	  (void)irq;
   326	  (void)context;
   327	
   328	  status = GET_GDMA_CH_REG(DMA_IN_INT_ST_CH0_REG, priv->dma_channel);
   329	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
   330	
   331	  if ((status & (DMA_IN_SUC_EOF_CH0_INT_ST |
   332	                 DMA_IN_ERR_EOF_CH0_INT_ST)) == 0)
   333	    {
   334	      return OK;
   335	    }
   336	
   337	  flags = spin_lock_irqsave(&priv->lock);
   338	  if (priv->active != NULL)
   339	    {
   340	      priv->active->result = (status & DMA_IN_SUC_EOF_CH0_INT_ST) != 0 ?
   341	                             OK : -EIO;
   342	      priv->done = priv->active;
   343	      priv->active = NULL;
   344	      priv->irq_status = status;
   345	      contest_i2s_stop_hw(priv);
   346	      work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker, priv, 0);
   347	    }
   348	
   349	  spin_unlock_irqrestore(&priv->lock, flags);
   350	  return OK;
   351	}
