   384	static int voice_record(struct i2s_dev_s *mic, int16_t *samples,
   385	                        size_t capacity, size_t *count,
   386	                        int16_t *minimum, int16_t *maximum, int16_t *peak)
   387	{
   388	  unsigned int empty_transfers = 0;
   389	  unsigned int chunk = 0;
   390	  clock_t deadline;
   391	  int ret;
   392	
   393	  *count = 0;
   394	  *minimum = INT16_MAX;
   395	  *maximum = INT16_MIN;
   396	  *peak = 0;
   397	
   398	  ret = I2S_IOCTL(mic, AUDIOIOC_START, 0);
   399	  printf("voice_echo: MIC start ret=%d\n", ret);
   400	  if (ret < 0)
   401	    {
   402	      return ret;
   403	    }
   404	
   405	  deadline = clock_systime_ticks() + MSEC2TICK(VOICE_RECORD_TIMEOUT_MS);
   406	
   407	  while (*count < capacity)
   408	    {
   409	      struct ap_buffer_s *apb;
   410	      struct voice_transfer_s *transfer;
   411	      size_t nbytes;
   412	      size_t nsamples;
   413	      size_t i;
   414	      clock_t remaining;
   415	      clock_t wait_ticks;
   416	      size_t request_bytes;
   417	      bool submitted;
   418	
   419	      request_bytes = MIN(VOICE_DMA_BYTES,
   420	                          (capacity - *count) * sizeof(int16_t));
   421	      ret = voice_buffer_alloc(&apb, request_bytes);
   422	      if (ret < 0)
   423	        {
   424	          goto errout;
   425	        }
   426	
   427	      transfer = calloc(1, sizeof(*transfer));
   428	      if (transfer == NULL)
   429	        {
   430	          apb_free(apb);
   431	          ret = -ENOMEM;
   432	          goto errout;
   433	        }
   434	
   435	      voice_transfer_init(transfer, true, true, false, chunk);
   436	
   437	      remaining = deadline - clock_systime_ticks();
   438	      if ((int32_t)remaining <= 0)
   439	        {
   440	          voice_transfer_destroy(transfer);
   441	          free(transfer);
   442	          apb_free(apb);
   443	          ret = -ETIMEDOUT;
   444	          goto errout;
   445	        }
   446	
   447	      wait_ticks = MIN(MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS), remaining);
   448	      if (!voice_rx_claim())
   449	        {
   450	          printf("voice_echo: previous RX transaction still pending\n");
   451	          voice_transfer_destroy(transfer);
   452	          free(transfer);
   453	          apb_free(apb);
   454	          ret = -EBUSY;
   455	          goto errout;
   456	        }
   457	
   458	      printf("voice_echo: RX submit chunk=%u bytes=%zu\n", chunk,
   459	             request_bytes);
   460	      ret = I2S_RECEIVE(mic, apb, voice_complete, transfer, wait_ticks);
   461	      submitted = ret >= 0;
   462	      if (!submitted)
   463	        {
   464	          voice_rx_release();
   465	        }
   466	      printf("voice_echo: RX submit chunk=%u ret=%d\n", chunk, ret);
   467	      if (submitted)
   468	        {
   469	          ret = voice_wait_transfer(transfer, wait_ticks);
   470	        }
   471	
   472	      if (ret < 0)
   473	        {
   474	          printf("voice_echo: RX wait chunk=%u failed: %d\n", chunk, ret);
   475	          if (submitted && ret == -ETIMEDOUT)
   476	            {
   477	              /* The ESP32-S3 lower-half currently does not cancel an
   478	               * enqueued RX transaction on its timeout field.  Keep the
   479	               * context alive for a late callback instead of creating a
   480	               * use-after-free.  The callback releases the APB and context.
   481	               */
   482	
   483	              if (voice_abandon_transfer(transfer))
   484	                {
   485	                  (void)I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
   486	                  goto errout;
   487	                }
   488	
   489	              nxmutex_lock(&transfer->lock);
   490	              ret = transfer->result;
   491	              nxmutex_unlock(&transfer->lock);
   492	            }
   493	          else
   494	            {
   495	              voice_transfer_destroy(transfer);
   496	              free(transfer);
   497	              apb_free(apb);
   498	            }
   499	
   500	          if (ret < 0)
   501	            {
   502	              goto errout;
   503	            }
   504	        }
   505	
   506	      voice_transfer_destroy(transfer);
   507	      if (transfer->apb == NULL)
   508	        {
   509	          free(transfer);
   510	          apb_free(apb);
   511	          ret = -EIO;
   512	          goto errout;
   513	        }
   514	
   515	      nbytes = transfer->apb->nbytes;
   516	      nbytes -= nbytes % sizeof(int16_t);
   517	      nbytes = nbytes > (capacity - *count) * sizeof(int16_t) ?
   518	               (capacity - *count) * sizeof(int16_t) : nbytes;
   519	      nsamples = nbytes / sizeof(int16_t);
   520	      memcpy(&samples[*count], transfer->apb->samp, nbytes);
   521	      apb_free(transfer->apb);
   522	      apb_free(apb);
   523	      free(transfer);
   524	
   525	      for (i = 0; i < nsamples; i++)
   526	        {
   527	          int16_t value = samples[*count + i];
   528	          int16_t absolute = value == INT16_MIN ? INT16_MAX :
   529	                             (value < 0 ? -value : value);
   530	
   531	          if (value < *minimum)
   532	            {
   533	              *minimum = value;
   534	            }
   535	
   536	          if (value > *maximum)
   537	            {
   538	              *maximum = value;
   539	            }
   540	
   541	          if (absolute > *peak)
   542	            {
   543	              *peak = absolute;
   544	            }
   545	        }
   546	
   547	      *count += nsamples;
   548	      chunk++;
   549	      if (nsamples == 0)
   550	        {
   551	          if (++empty_transfers >= 6)
   552	            {
   553	              ret = -ETIMEDOUT;
   554	              goto errout;
   555	            }
   556	        }
   557	      else
   558	        {
   559	          empty_transfers = 0;
   560	        }
   561	    }
   562	
   563	  ret = 0;
   564	
   565	errout:
   566	  {
   567	    int stop_ret = I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
   568	    printf("voice_echo: MIC stop ret=%d\n", stop_ret);
   569	    if (ret >= 0 && stop_ret < 0)
   570	      {
   571	        ret = stop_ret;
   572	      }
   573	  }
   574	
   575	  return ret;
   576	}
