   578	static int voice_play(struct i2s_dev_s *speaker, const int16_t *samples,
   579	                      size_t count)
   580	{
   581	  size_t output_count = (count * VOICE_OUTPUT_RATE + VOICE_INPUT_RATE - 1) /
   582	                        VOICE_INPUT_RATE;
   583	  size_t output_index = 0;
   584	  unsigned int chunk_index = 0;
   585	  int ret;
   586	
   587	  ret = I2S_IOCTL(speaker, AUDIOIOC_START, 0);
   588	  printf("voice_echo: SPK start ret=%d\n", ret);
   589	  if (ret < 0)
   590	    {
   591	      return ret;
   592	    }
   593	
   594	  while (output_index < output_count)
   595	    {
   596	      struct ap_buffer_s *apb;
   597	      struct voice_transfer_s *transfer;
   598	      size_t chunk = output_count - output_index;
   599	      size_t i;
   600	      bool submitted;
   601	
   602	      if (chunk > VOICE_DMA_BYTES / sizeof(int16_t))
   603	        {
   604	          chunk = VOICE_DMA_BYTES / sizeof(int16_t);
   605	        }
   606	
   607	      ret = voice_buffer_alloc(&apb, VOICE_DMA_BYTES);
   608	      if (ret < 0)
   609	        {
   610	          goto errout;
   611	        }
   612	
   613	      transfer = calloc(1, sizeof(*transfer));
   614	      if (transfer == NULL)
   615	        {
   616	          apb_free(apb);
   617	          ret = -ENOMEM;
   618	          goto errout;
   619	        }
   620	
   621	      for (i = 0; i < chunk; i++)
   622	        {
   623	          size_t source = ((output_index + i) * VOICE_INPUT_RATE) /
   624	                          VOICE_OUTPUT_RATE;
   625	
   626	          ((int16_t *)apb->samp)[i] = samples[source];
   627	        }
   628	
   629	      apb->nbytes = chunk * sizeof(int16_t);
   630	      apb->nsamples = chunk;
   631	      voice_transfer_init(transfer, false, false, true, chunk_index);
   632	      printf("voice_echo: TX submit chunk=%u bytes=%zu\n", chunk_index,
   633	             apb->nbytes);
   634	      ret = I2S_SEND(speaker, apb, voice_complete, transfer,
   635	                     MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
   636	      submitted = ret >= 0;
   637	      printf("voice_echo: TX submit chunk=%u ret=%d\n", chunk_index, ret);
   638	      if (submitted)
   639	        {
   640	          ret = voice_wait_transfer(transfer,
   641	                                    MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
   642	        }
   643	
   644	      if (ret < 0)
   645	        {
   646	          printf("voice_echo: TX wait chunk=%u failed: %d\n", chunk_index,
   647	                 ret);
   648	          if (submitted && voice_abandon_transfer(transfer))
   649	            {
   650	              int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);
   651	
   652	              printf("voice_echo: SPK stop ret=%d\n", stop_ret);
   653	              /* The callback owns transfer and the application's APB
   654	               * reference after abandonment.  It releases both safely.
   655	               */
   656	
   657	              return ret;
   658	            }
   659	
   660	          voice_transfer_destroy(transfer);
   661	          free(transfer);
   662	          apb_free(apb);
   663	          goto errout;
   664	        }
   665	
   666	      voice_transfer_destroy(transfer);
   667	      free(transfer);
   668	      apb_free(apb);
   669	      output_index += chunk;
   670	      chunk_index++;
   671	    }
   672	
   673	errout:
   674	  {
   675	    int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);
   676	
   677	    printf("voice_echo: SPK stop ret=%d\n", stop_ret);
   678	    if (ret >= 0 && stop_ret < 0)
   679	      {
   680	        ret = stop_ret;
   681	      }
   682	  }
   683	
   684	  return ret;
   685	}
