 909	      flags = spin_lock_irqsave(&priv->lock);
 910	      priv->reserved = false;
 911	      spin_unlock_irqrestore(&priv->lock, flags);
 912	      apb_free(apb);
 913	      return -ENOMEM;
 914	    }
 915	
 916	  for (last = 0; last + 1 < CONTEST_I2S_DMA_DESC_COUNT &&
 917	                 xfer->desc[last].next != NULL; last++)
 918	    {
 919	    }
 920	
 921	  if ((xfer->desc[last].ctrl & ESP32S3_DMA_CTRL_EOF) == 0)
 922	    {
 923	      flags = spin_lock_irqsave(&priv->lock);
 924	      priv->reserved = false;
 925	      spin_unlock_irqrestore(&priv->lock, flags);
 926	      apb_free(apb);
 927	      return -EIO;
 928	    }
 929	
 930	  flags = spin_lock_irqsave(&priv->lock);
 931	  if (!priv->streaming)
 932	    {
 933	      priv->reserved = false;
 934	      spin_unlock_irqrestore(&priv->lock, flags);
 935	      apb_free(apb);
 936	      return -ECANCELED;
 937	    }
 938	
 939	  /* Publish active before DMA and I2S start, so EOF cannot be lost. */
 940	
 941	  priv->active = xfer;
 942	  priv->reserved = false;
 943	  CLR_GDMA_CH_BITS(DMA_OUT_CONF1_CH0_REG, priv->dma_channel,
 944	                   DMA_OUT_CHECK_OWNER_CH0);
 945	  esp32s3_dma_load(xfer->desc, priv->dma_channel, true);
 946	  SET_GDMA_CH_REG(DMA_OUT_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
 947	  SET_GDMA_CH_BITS(DMA_OUT_INT_ENA_CH0_REG, priv->dma_channel,
 948	                   DMA_OUT_TOTAL_EOF_CH0_INT_ENA |
 949	                   DMA_OUT_DSCR_ERR_CH0_INT_ENA);
 950	  esp32s3_dma_enable(priv->dma_channel, true);
 951	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_START);
 952	  spin_unlock_irqrestore(&priv->lock, flags);
 953	
 954	  syslog(LOG_INFO, "[C-I2S] tx submit bytes=%zu\n", nbytes);
 955	  syslog(LOG_INFO, "[C-I2S] tx dma start\n");
 956	  return OK;
 957	}
