 959	static int contest_i2s_tx_ioctl(FAR struct i2s_dev_s *dev, int cmd,
 960	                                unsigned long arg)
 961	{
 962	  FAR struct contest_i2s_tx_s *priv = (FAR struct contest_i2s_tx_s *)dev;
 963	  FAR struct contest_i2s_xfer_s *xfer = NULL;
 964	  irqstate_t flags;
 965	
 966	  (void)arg;
 967	
 968	  switch (cmd)
 969	    {
 970	      case AUDIOIOC_START:
 971	        flags = spin_lock_irqsave(&priv->lock);
 972	        priv->streaming = true;
 973	        spin_unlock_irqrestore(&priv->lock, flags);
 974	        up_enable_irq(priv->tx_irq);
 975	        return OK;
 976	
 977	      case AUDIOIOC_STOP:
 978	        flags = spin_lock_irqsave(&priv->lock);
 979	        priv->streaming = false;
 980	        if (priv->active != NULL)
 981	          {
 982	            xfer = priv->active;
 983	            contest_i2s_tx_capture_state(priv, xfer);
 984	            xfer->result = -ECANCELED;
 985	            priv->done = xfer;
 986	            priv->active = NULL;
 987	            contest_i2s_tx_stop_hw(priv);
 988	          }
 989	
 990	        spin_unlock_irqrestore(&priv->lock, flags);
 991	        if (xfer != NULL)
 992	          {
 993	            contest_i2s_tx_dump_state(priv);
 994	            work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker,
 995	                       priv, 0);
 996	          }
 997	
 998	        return OK;
 999	
1000	      default:
1001	        return -ENOTTY;
1002	    }
1003	}
