170	static int voice_wait_transfer(struct voice_transfer_s *transfer,
171	                               clock_t timeout)
172	{
173	  int ret;
174	
175	  do
176	    {
177	      ret = nxsem_tickwait(&transfer->done, timeout);
178	    }
179	  while (ret == -EINTR);
180	
181	  if (ret >= 0)
182	    {
183	      nxmutex_lock(&transfer->lock);
184	      ret = transfer->result;
185	      nxmutex_unlock(&transfer->lock);
186	    }
187	
188	  return ret;
189	}
