 437	static int contest_i2s_receive(FAR struct i2s_dev_s *dev,
 438	                               FAR struct ap_buffer_s *apb,
 439	                               i2s_callback_t callback, FAR void *arg,
 440	                               uint32_t timeout)
 441	{
 442	  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
 443	  FAR struct contest_i2s_xfer_s *xfer = &priv->xfer;
 444	  irqstate_t flags;
 445	  size_t nbytes;
 446	  uint32_t queued;
 447	  uint32_t eof_samples;
 448	
 449	  (void)timeout;
 450	
 451	  if (apb == NULL || callback == NULL || apb->samp == NULL)
 452	    {
 453	      return -EINVAL;
 454	    }
 455	
 456	  nbytes = apb->nmaxbytes - apb->curbyte;
 457	  nbytes -= nbytes % (priv->data_width / 8);
 458	  if (nbytes == 0)
 459	    {
 460	      return -EINVAL;
 461	    }
 462	
 463	  apb_reference(apb);
 464	
 465	  /* Reserve the one supported transaction while the DMA descriptor is built
 466	   * outside the spinlock.  apb_reference() and DMA setup are not IRQ-side
 467	   * operations and must not run while interrupts are locked.
 468	   */
 469	
 470	  flags = spin_lock_irqsave(&priv->lock);
 471	  if (!priv->streaming || priv->reserved || priv->active != NULL ||
 472	      priv->done != NULL)
 473	    {
 474	      spin_unlock_irqrestore(&priv->lock, flags);
 475	      apb_free(apb);
 476	      return -EBUSY;
 477	    }
 478	
 479	  priv->reserved = true;
 480	  spin_unlock_irqrestore(&priv->lock, flags);
 481	
 482	  xfer->apb = apb;
 483	  xfer->callback = callback;
 484	  xfer->arg = arg;
 485	  xfer->nbytes = nbytes;
 486	  xfer->result = -EINPROGRESS;
 487	  queued = esp32s3_dma_setup(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
 488	                              apb->samp + apb->curbyte, nbytes, false,
 489	                              priv->dma_channel);
 490	  if (queued != nbytes)
 491	    {
 492	      flags = spin_lock_irqsave(&priv->lock);
 493	      priv->reserved = false;
 494	      spin_unlock_irqrestore(&priv->lock, flags);
 495	      apb_free(apb);
 496	      return -ENOMEM;
 497	    }
 498	
 499	  eof_samples = nbytes * 8 / priv->data_width;
 500	  if (eof_samples == 0 || eof_samples > I2S_RX_EOF_NUM_V + 1)
 501	    {
 502	      flags = spin_lock_irqsave(&priv->lock);
 503	      priv->reserved = false;
 504	      spin_unlock_irqrestore(&priv->lock, flags);
 505	      apb_free(apb);
 506	      return -EINVAL;
 507	    }
 508	
 509	  /* Publish active before enabling EOF so a completion cannot be lost. */
 510	
 511	  flags = spin_lock_irqsave(&priv->lock);
 512	  if (!priv->streaming)
 513	    {
 514	      priv->reserved = false;
 515	      spin_unlock_irqrestore(&priv->lock, flags);
 516	      apb_free(apb);
 517	      return -ECANCELED;
 518	    }
 519	
 520	  priv->active = xfer;
 521	  priv->reserved = false;
 522	  esp32s3_dma_load(xfer->desc, priv->dma_channel, false);
 523	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
 524	  SET_GDMA_CH_BITS(DMA_IN_INT_ENA_CH0_REG, priv->dma_channel,
 525	                   DMA_IN_SUC_EOF_CH0_INT_ENA | DMA_IN_ERR_EOF_CH0_INT_ENA);
 526	  modifyreg32(I2S_RXEOF_NUM_REG(CONTEST_I2S_PORT), I2S_RX_EOF_NUM_M,
 527	              FIELD_TO_VALUE(I2S_RX_EOF_NUM, eof_samples - 1));
 528	  esp32s3_dma_enable(priv->dma_channel, false);
 529	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_START);
 530	  spin_unlock_irqrestore(&priv->lock, flags);
 531	
 532	  syslog(LOG_INFO, "[C-I2S] rx submit bytes=%zu\n", nbytes);
 533	  syslog(LOG_INFO, "[C-I2S] rx dma start eof=%lu\n",
 534	         (unsigned long)(eof_samples - 1));
 535	  return OK;
 536	}
