static void contest_i2s_rx_worker(FAR void *arg)
{
  FAR struct contest_i2s_s *priv = arg;
  FAR struct contest_i2s_xfer_s *xfer;
  FAR struct ap_buffer_s *apb;
  i2s_callback_t callback;
  FAR void *callback_arg;
  int result;
  uint32_t irq_status;
  irqstate_t flags;
  size_t nbytes = 0;
  unsigned int i;

  flags = spin_lock_irqsave(&priv->lock);
  xfer = priv->done;
  priv->done = NULL;
  irq_status = priv->irq_status;
  spin_unlock_irqrestore(&priv->lock, flags);

  if (xfer == NULL)
    {
      return;
    }

  for (i = 0; i < CONTEST_I2S_DMA_DESC_COUNT; i++)
    {
      uint32_t length = (xfer->desc[i].ctrl >>
                         ESP32S3_DMA_CTRL_DATALEN_S) &
                        ESP32S3_DMA_CTRL_DATALEN_V;

      nbytes += length;
      if (xfer->desc[i].next == NULL)
        {
          break;
        }
    }

  if (nbytes > xfer->nbytes)
    {
      nbytes = xfer->nbytes;
    }

  xfer->apb->nbytes = nbytes;
  xfer->apb->nsamples = nbytes / (priv->data_width / 8);

  /* The callback can cause the next transaction to be submitted.  Save all
   * current transaction state before invoking it because the single static
   * transaction object may then be reused by I2S_RECEIVE.
   */

  apb = xfer->apb;
  callback = xfer->callback;
  callback_arg = xfer->arg;
  result = xfer->result;

  syslog(LOG_INFO, "[C-I2S] rx irq status=%08lx\n",
         (unsigned long)irq_status);
  syslog(LOG_INFO, "[C-I2S] rx worker bytes=%zu\n", nbytes);
  syslog(LOG_INFO, "[C-I2S] rx callback\n");
  callback(&priv->dev, apb, callback_arg, result);
  apb_free(apb);
}

static int contest_i2s_rx_interrupt(int irq, FAR void *context,
                                    FAR void *arg)
{
  FAR struct contest_i2s_s *priv = arg;
  uint32_t status;
  irqstate_t flags;

  (void)irq;
  (void)context;

  status = GET_GDMA_CH_REG(DMA_IN_INT_ST_CH0_REG, priv->dma_channel);
  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);

  if ((status & (DMA_IN_SUC_EOF_CH0_INT_ST |
                 DMA_IN_ERR_EOF_CH0_INT_ST)) == 0)
    {
      return OK;
    }

  flags = spin_lock_irqsave(&priv->lock);
  if (priv->active != NULL)
    {
      priv->active->result = (status & DMA_IN_SUC_EOF_CH0_INT_ST) != 0 ?
                             OK : -EIO;
      priv->done = priv->active;
      priv->active = NULL;
      priv->irq_status = status;
      contest_i2s_stop_hw(priv);
      work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker, priv, 0);
    }

  spin_unlock_irqrestore(&priv->lock, flags);
  spin_unlock_irqrestore(&priv->lock, flags);
  return OK;
}

