static void contest_i2s_rx_worker(FAR void *arg)
{
  FAR struct contest_i2s_s *priv = arg;
  FAR struct contest_i2s_xfer_s *xfer;
  FAR struct ap_buffer_s *apb;
  i2s_callback_t callback;
  FAR void *callback_arg;
  int result;
  uint32_t irq_status;
  irqstate_t flags;
  size_t logical_bytes;
  size_t raw_bytes;
  size_t logical_samples;
  unsigned int i;

  flags = spin_lock_irqsave(&priv->lock);
  xfer = priv->done;
  priv->done = NULL;
  irq_status = priv->irq_status;
  spin_unlock_irqrestore(&priv->lock, flags);

  if (xfer == NULL)
    {
      return;
    }

  result = xfer->result;
  logical_bytes = priv->logical_bytes;
  raw_bytes = priv->raw_bytes;
  logical_samples = logical_bytes / sizeof(int16_t);

  if (result >= 0 &&
      (logical_bytes == 0 ||
       raw_bytes != logical_samples * sizeof(uint32_t)))
    {
      result = -EIO;
    }

  if (result >= 0)
    {
      FAR int16_t *pcm = (FAR int16_t *)(xfer->apb->samp +
                                         xfer->apb->curbyte);

      up_invalidate_dcache((uintptr_t)priv->raw,
                           (uintptr_t)priv->raw + raw_bytes);

      if (!priv->raw_logged)
        {
          int32_t raw_min = INT32_MAX;
          int32_t raw_max = INT32_MIN;
          unsigned int raw_nonzero = 0;
          unsigned int raw_low8_nonzero = 0;
      unsigned int words = logical_samples < 16 ? logical_samples : 16;

          for (i = 0; i < logical_samples; i++)
            {
              int32_t value = (int32_t)priv->raw[i];

              if (value != 0)
                {
                  raw_nonzero++;
                }

              if ((priv->raw[i] & 0xff) != 0)
                {
                  raw_low8_nonzero++;
                }

              if (value < raw_min)
                {
                  raw_min = value;
                }

              if (value > raw_max)
                {
                  raw_max = value;
                }
            }

          for (i = 0; i < words; i++)
            {
              syslog(LOG_INFO, "[C-I2S] raw[%u]=%08lx\n", i,
                     (unsigned long)priv->raw[i]);
            }

          syslog(LOG_INFO,
                 "[C-I2S] raw_nonzero=%u raw_low8_nonzero=%u "
                 "raw_min=%ld raw_max=%ld\n",
                 raw_nonzero, raw_low8_nonzero, (long)raw_min,
                 (long)raw_max);
          priv->raw_logged = true;
        }

      for (i = 0; i < logical_samples; i++)
        {
          pcm[i] = (int16_t)((int32_t)priv->raw[i] >>
                             CONTEST_I2S_RX_PCM_SHIFT);
        }

      xfer->apb->nbytes = logical_bytes;
      xfer->apb->nsamples = logical_samples;
    }
  else
    {
      xfer->apb->nbytes = 0;
      xfer->apb->nsamples = 0;
    }

  /* The callback can cause the next transaction to be submitted.  Save all
   * current transaction state before invoking it because the single static
   * transaction object may then be reused by I2S_RECEIVE.
   */

  apb = xfer->apb;
  callback = xfer->callback;
  callback_arg = xfer->arg;

  syslog(LOG_INFO, "[C-I2S] rx irq status=%08lx\n",
         (unsigned long)irq_status);
  syslog(LOG_INFO, "[C-I2S] rx worker bytes=%zu\n", logical_bytes);
  syslog(LOG_INFO, "[C-I2S] rx callback\n");
  callback(&priv->dev, apb, callback_arg, result);
  apb_free(apb);
}

static int contest_i2s_rx_interrupt(int irq, FAR void *context,
                                    FAR void *arg)
{
  FAR struct contest_i2s_s *priv = arg;
  uint32_t status;
  irqstate_t flags;

  (void)irq;
  (void)context;

  status = GET_GDMA_CH_REG(DMA_IN_INT_ST_CH0_REG, priv->dma_channel);
  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);

  if ((status & (DMA_IN_SUC_EOF_CH0_INT_ST |
                 DMA_IN_ERR_EOF_CH0_INT_ST)) == 0)
    {
      return OK;
    }

  flags = spin_lock_irqsave(&priv->lock);
  if (priv->active != NULL)
    {
      priv->active->result = (status & DMA_IN_SUC_EOF_CH0_INT_ST) != 0 ?
                             OK : -EIO;
      priv->done = priv->active;
      priv->active = NULL;
      priv->irq_status = status;
      contest_i2s_stop_hw(priv);
      work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker, priv, 0);
    }

  spin_unlock_irqrestore(&priv->lock, flags);
  return OK;
}

static void contest_i2s_configure(FAR struct contest_i2s_s *priv)
{
  modifyreg32(SYSTEM_PERIP_CLK_EN0_REG, 0, SYSTEM_I2S0_CLK_EN);
  modifyreg32(SYSTEM_PERIP_RST_EN0_REG, 0, SYSTEM_I2S0_RST);
  modifyreg32(SYSTEM_PERIP_RST_EN0_REG, SYSTEM_I2S0_RST, 0);

