static int voice_configure_i2s(struct i2s_dev_s *mic,
                               struct i2s_dev_s *speaker)
{
  int actual;
  int ret;

  ret = I2S_RXCHANNELS(mic, VOICE_CHANNELS);
  printf("voice_echo: MIC set channels ret=%d\n", ret);
  if (ret < 0)
    {
      return ret;
    }

  actual = (int)I2S_RXSAMPLERATE(mic, VOICE_INPUT_RATE);
  printf("voice_echo: MIC set rate ret=%d\n", actual);
  if (actual != VOICE_INPUT_RATE)
    {
      return actual < 0 ? actual : -ENOTSUP;
    }

  actual = (int)I2S_RXDATAWIDTH(mic, VOICE_SAMPLE_BITS);
  printf("voice_echo: MIC set width ret=%d\n", actual);
  if (actual != VOICE_SAMPLE_BITS)
    {
      return actual < 0 ? actual : -ENOTSUP;
    }

  ret = I2S_TXCHANNELS(speaker, VOICE_CHANNELS);
  printf("voice_echo: SPK set channels ret=%d\n", ret);
  if (ret < 0)
    {
      return ret;
    }

  actual = (int)I2S_TXSAMPLERATE(speaker, VOICE_OUTPUT_RATE);
  printf("voice_echo: SPK set rate ret=%d\n", actual);
  if (actual != VOICE_OUTPUT_RATE)
    {
      return actual < 0 ? actual : -ENOTSUP;
    }

  actual = (int)I2S_TXDATAWIDTH(speaker, VOICE_SAMPLE_BITS);
  printf("voice_echo: SPK set width ret=%d\n", actual);
  if (actual != VOICE_SAMPLE_BITS)
    {
      return actual < 0 ? actual : -ENOTSUP;
    }

  return 0;
}

static void voice_oled_pixel(uint8_t *row, unsigned int x, bool on)
{
  uint8_t mask;

#ifdef CONFIG_LCD_PACKEDMSFIRST
  mask = 0x80 >> (x & 7);
#else
  mask = 1 << (x & 7);
#endif

  if (on)
    {
      row[x >> 3] |= mask;
    }
}

static int voice_oled_show(struct voice_oled_s *oled, const char *line1,
                           const char *line2)
{
  const char *lines[2] = {line1, line2};
  uint8_t row[128 / 8];
  unsigned int y;
  int ret = 0;

  if (!oled->available)
    {
      return 0;
    }

  for (y = 0; y < 64; y++)
    {
      const char *text;
      unsigned int x;
      unsigned int charrow;

      memset(row, 0, sizeof(row));
      text = lines[y / 32];
      charrow = (y % 32) / 3;

      if (charrow < 7)
        {
          for (x = 0; text[x] != '\0' && x < 20; x++)
            {
              uint8_t glyph = (uint8_t)text[x];
              unsigned int col;

              if (glyph >= sizeof(g_font) || glyph < ' ')
                {
                  glyph = ' ';
                }

              for (col = 0; col < 5; col++)
                {
                  if ((g_font[glyph][col] & (1u << charrow)) != 0)
                    {
                      voice_oled_pixel(row, x * 6 + col, true);
                    }
                }
            }
        }

      ret = oled->plane.putrun(oled->dev, y, 0, row, 128);
      if (ret < 0)
        {
          oled->available = false;
          printf("OLED unavailable\n");
          return ret;
        }
    }

  return 0;
}

static void voice_oled_init(struct voice_oled_s *oled)
{
  memset(oled, 0, sizeof(*oled));

  if (board_oled_initialize() < 0)
    {
      printf("OLED unavailable\n");
      return;
    }

  oled->dev = board_oled_getdev();
  if (oled->dev == NULL || oled->dev->getplaneinfo(oled->dev, 0,
                                                    &oled->plane) < 0)
    {
      printf("OLED unavailable\n");
      return;
    }

  oled->available = true;
}

static int voice_record(struct i2s_dev_s *mic, int16_t *samples,
                        size_t capacity, size_t *count,
                        int16_t *minimum, int16_t *maximum, int16_t *peak,
                        int64_t *sum, uint64_t *squares, size_t *clip_count)
{
  unsigned int empty_transfers = 0;
  unsigned int chunk = 0;
  clock_t deadline;
  int ret;

  *count = 0;
  *minimum = INT16_MAX;
  *maximum = INT16_MIN;
  *peak = 0;
  *sum = 0;
  *squares = 0;
  *clip_count = 0;

  ret = I2S_IOCTL(mic, AUDIOIOC_START, 0);
  printf("voice_echo: MIC start ret=%d\n", ret);
  if (ret < 0)
    {
      return ret;
    }

  deadline = clock_systime_ticks() + MSEC2TICK(VOICE_RECORD_TIMEOUT_MS);

  while (*count < capacity)
    {
      struct ap_buffer_s *apb;
      struct voice_transfer_s *transfer;
      size_t nbytes;
      size_t nsamples;
      size_t i;
      clock_t remaining;
      clock_t wait_ticks;
      size_t request_bytes;
      bool submitted;

      request_bytes = MIN(VOICE_DMA_BYTES,
                          (capacity - *count) * sizeof(int16_t));
      ret = voice_buffer_alloc(&apb, request_bytes);
      if (ret < 0)
        {
          goto errout;
        }

      transfer = calloc(1, sizeof(*transfer));
      if (transfer == NULL)
        {
          apb_free(apb);
          ret = -ENOMEM;
          goto errout;
        }

      voice_transfer_init(transfer, true, true, false, chunk);

      remaining = deadline - clock_systime_ticks();
      if ((int32_t)remaining <= 0)
        {
          voice_transfer_destroy(transfer);
          free(transfer);
          apb_free(apb);
          ret = -ETIMEDOUT;
          goto errout;
        }

      wait_ticks = MIN(MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS), remaining);
      if (!voice_rx_claim())
        {
          printf("voice_echo: previous RX transaction still pending\n");
          voice_transfer_destroy(transfer);
          free(transfer);
          apb_free(apb);
          ret = -EBUSY;
          goto errout;
        }

      printf("voice_echo: RX submit chunk=%u bytes=%zu\n", chunk,
             request_bytes);
      ret = I2S_RECEIVE(mic, apb, voice_complete, transfer, wait_ticks);
      submitted = ret >= 0;
      if (!submitted)
        {
          voice_rx_release();
        }
      printf("voice_echo: RX submit chunk=%u ret=%d\n", chunk, ret);
      if (submitted)
        {
          ret = voice_wait_transfer(transfer, wait_ticks);
        }

      if (ret < 0)
        {
          printf("voice_echo: RX wait chunk=%u failed: %d\n", chunk, ret);
          if (submitted && ret == -ETIMEDOUT)
            {
              /* The ESP32-S3 lower-half currently does not cancel an
               * enqueued RX transaction on its timeout field.  Keep the
               * context alive for a late callback instead of creating a
               * use-after-free.  The callback releases the APB and context.
               */

              if (voice_abandon_transfer(transfer))
                {
                  (void)I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
                  goto errout;
                }

              nxmutex_lock(&transfer->lock);
              ret = transfer->result;
              nxmutex_unlock(&transfer->lock);
            }
          else
            {
              voice_transfer_destroy(transfer);
              free(transfer);
              apb_free(apb);
            }

          if (ret < 0)
            {
              goto errout;
            }
        }

      voice_transfer_destroy(transfer);
      if (transfer->apb == NULL)
        {
          free(transfer);
          apb_free(apb);
          ret = -EIO;
          goto errout;
        }

      nbytes = transfer->apb->nbytes;
      nbytes -= nbytes % sizeof(int16_t);
      nbytes = nbytes > (capacity - *count) * sizeof(int16_t) ?
               (capacity - *count) * sizeof(int16_t) : nbytes;
      nsamples = nbytes / sizeof(int16_t);
      memcpy(&samples[*count], transfer->apb->samp, nbytes);
      apb_free(transfer->apb);
      apb_free(apb);
      free(transfer);

      for (i = 0; i < nsamples; i++)
        {
          int16_t value = samples[*count + i];
          int16_t absolute = value == INT16_MIN ? INT16_MAX :
                             (value < 0 ? -value : value);

          if (value < *minimum)
            {
              *minimum = value;
            }

          if (value > *maximum)
            {
              *maximum = value;
            }

          if (absolute > *peak)
            {
              *peak = absolute;
            }

          *sum += value;
          *squares += (int64_t)value * value;
          if (value == INT16_MIN || value == INT16_MAX)
            {
              (*clip_count)++;
            }
        }

      *count += nsamples;
      chunk++;
      if (nsamples == 0)
        {
          if (++empty_transfers >= 6)
            {
              ret = -ETIMEDOUT;
              goto errout;
            }
        }
      else
        {
          empty_transfers = 0;
        }
    }

  ret = 0;

errout:
  {
    int stop_ret = I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
    printf("voice_echo: MIC stop ret=%d\n", stop_ret);
    if (ret >= 0 && stop_ret < 0)

