   213	static void contest_i2s_set_rate(FAR struct contest_i2s_s *priv)
   214	{
   215	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
   216	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
   217	  uint32_t remainder = CONTEST_I2S_SOURCE_CLOCK % mclk;
   218	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS *
   219	                  CONTEST_INMP441_SLOT_BITS;
   220	  uint32_t bclk_div = mclk / bclk;
   221	  uint32_t regval;
   222	  uint32_t numerator = 0;
   223	  uint32_t denominator = 1;
   224	  uint32_t a;
   225	
   226	  /* Match the ESP32-S3 reference driver's CLK160 fractional divider. */
   227	
   228	  if (remainder != 0)
   229	    {
   230	      for (a = 2; a <= 63; a++)
   231	        {
   232	          uint32_t b = (remainder * a + mclk / 2) / mclk;
   233	
   234	          if (b != 0 && remainder * a == mclk * b)
   235	            {
   236	              numerator = b;
   237	              denominator = a;
   238	              break;
   239	            }
   240	        }
   241	    }
   242	
   243	  if (numerator == 0)
   244	    {
   245	      denominator = 1;
   246	    }
   247	
   248	  regval = getreg32(I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
   249	  regval &= ~I2S_RX_CLKM_DIV_NUM_M;
   250	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_NUM, mclk_div);
   251	  putreg32(regval, I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
   252	
   253	  regval = getreg32(I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
   254	  regval &= ~(I2S_RX_CLKM_DIV_Z_M | I2S_RX_CLKM_DIV_Y_M |
   255	              I2S_RX_CLKM_DIV_X_M | I2S_RX_CLKM_DIV_YN1_M);
   256	  if (numerator != 0)
   257	    {
   258	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Z, numerator);
   259	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Y, denominator % numerator);
   260	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_X,
   261	                               denominator / numerator - 1);
   262	    }
   263	
   264	  putreg32(regval, I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
   265	
   266	  modifyreg32(I2S_RX_CONF1_REG(CONTEST_I2S_PORT), I2S_RX_BCK_DIV_NUM_M,
   267	              FIELD_TO_VALUE(I2S_RX_BCK_DIV_NUM, bclk_div - 1));
   268	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_UPDATE);
   269	}
