   271	static void contest_i2s_rx_worker(FAR void *arg)
   272	{
   273	  FAR struct contest_i2s_s *priv = arg;
   274	  FAR struct contest_i2s_xfer_s *xfer;
   275	  FAR struct ap_buffer_s *apb;
   276	  i2s_callback_t callback;
   277	  FAR void *callback_arg;
   278	  int result;
   279	  uint32_t irq_status;
   280	  irqstate_t flags;
   281	  size_t logical_bytes;
   282	  size_t raw_bytes;
   283	  size_t logical_samples;
   284	  unsigned int i;
   285	
   286	  flags = spin_lock_irqsave(&priv->lock);
   287	  xfer = priv->done;
   288	  priv->done = NULL;
   289	  irq_status = priv->irq_status;
   290	  spin_unlock_irqrestore(&priv->lock, flags);
   291	
   292	  if (xfer == NULL)
   293	    {
   294	      return;
   295	    }
   296	
   297	  result = xfer->result;
   298	  logical_bytes = priv->logical_bytes;
   299	  raw_bytes = priv->raw_bytes;
   300	  logical_samples = logical_bytes / sizeof(int16_t);
   301	
   302	  if (result >= 0 &&
   303	      (logical_bytes == 0 ||
   304	       raw_bytes != logical_samples * sizeof(uint32_t)))
   305	    {
   306	      result = -EIO;
   307	    }
   308	
   309	  if (result >= 0)
   310	    {
   311	      FAR int16_t *pcm = (FAR int16_t *)(xfer->apb->samp +
   312	                                         xfer->apb->curbyte);
   313	
   314	      up_invalidate_dcache((uintptr_t)priv->raw,
   315	                           (uintptr_t)priv->raw + raw_bytes);
   316	
   317	      if (!priv->raw_logged)
   318	        {
   319	          int32_t raw_min = INT32_MAX;
   320	          int32_t raw_max = INT32_MIN;
   321	          unsigned int raw_nonzero = 0;
   322	          unsigned int raw_low8_nonzero = 0;
   323	      unsigned int words = logical_samples < 16 ? logical_samples : 16;
   324	
   325	          for (i = 0; i < logical_samples; i++)
   326	            {
   327	              int32_t value = (int32_t)priv->raw[i];
   328	
   329	              if (value != 0)
   330	                {
   331	                  raw_nonzero++;
   332	                }
   333	
   334	              if ((priv->raw[i] & 0xff) != 0)
   335	                {
   336	                  raw_low8_nonzero++;
   337	                }
   338	
   339	              if (value < raw_min)
   340	                {
   341	                  raw_min = value;
   342	                }
   343	
   344	              if (value > raw_max)
   345	                {
   346	                  raw_max = value;
   347	                }
   348	            }
   349	
   350	          for (i = 0; i < words; i++)
   351	            {
   352	              syslog(LOG_INFO, "[C-I2S] raw[%u]=%08lx\n", i,
   353	                     (unsigned long)priv->raw[i]);
   354	            }
   355	
   356	          syslog(LOG_INFO,
   357	                 "[C-I2S] raw_nonzero=%u raw_low8_nonzero=%u "
   358	                 "raw_min=%ld raw_max=%ld\n",
   359	                 raw_nonzero, raw_low8_nonzero, (long)raw_min,
   360	                 (long)raw_max);
   361	          priv->raw_logged = true;
   362	        }
   363	
   364	      for (i = 0; i < logical_samples; i++)
   365	        {
   366	          pcm[i] = (int16_t)((int32_t)priv->raw[i] >>
   367	                             CONTEST_I2S_RX_PCM_SHIFT);
   368	        }
   369	
   370	      xfer->apb->nbytes = logical_bytes;
   371	      xfer->apb->nsamples = logical_samples;
   372	    }
   373	  else
   374	    {
   375	      xfer->apb->nbytes = 0;
   376	      xfer->apb->nsamples = 0;
   377	    }
   378	
   379	  /* The callback can cause the next transaction to be submitted.  Save all
   380	   * current transaction state before invoking it because the single static
   381	   * transaction object may then be reused by I2S_RECEIVE.
   382	   */
   383	
   384	  apb = xfer->apb;
   385	  callback = xfer->callback;
   386	  callback_arg = xfer->arg;
   387	
   388	  syslog(LOG_INFO, "[C-I2S] rx irq status=%08lx\n",
   389	         (unsigned long)irq_status);
   390	  syslog(LOG_INFO, "[C-I2S] rx worker bytes=%zu\n", logical_bytes);
   391	  syslog(LOG_INFO, "[C-I2S] rx callback\n");
   392	  callback(&priv->dev, apb, callback_arg, result);
   393	  apb_free(apb);
   394	}
