   396	static int contest_i2s_rx_interrupt(int irq, FAR void *context,
   397	                                    FAR void *arg)
   398	{
   399	  FAR struct contest_i2s_s *priv = arg;
   400	  uint32_t status;
   401	  irqstate_t flags;
   402	
   403	  (void)irq;
   404	  (void)context;
   405	
   406	  status = GET_GDMA_CH_REG(DMA_IN_INT_ST_CH0_REG, priv->dma_channel);
   407	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
   408	
   409	  if ((status & (DMA_IN_SUC_EOF_CH0_INT_ST |
   410	                 DMA_IN_ERR_EOF_CH0_INT_ST)) == 0)
   411	    {
   412	      return OK;
   413	    }
   414	
   415	  flags = spin_lock_irqsave(&priv->lock);
   416	  if (priv->active != NULL)
   417	    {
   418	      priv->active->result = (status & DMA_IN_SUC_EOF_CH0_INT_ST) != 0 ?
   419	                             OK : -EIO;
   420	      priv->done = priv->active;
   421	      priv->active = NULL;
   422	      priv->irq_status = status;
   423	      contest_i2s_stop_hw(priv);
   424	      work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker, priv, 0);
   425	    }
   426	
   427	  spin_unlock_irqrestore(&priv->lock, flags);
   428	  return OK;
   429	}
