   520	static int contest_i2s_receive(FAR struct i2s_dev_s *dev,
   521	                               FAR struct ap_buffer_s *apb,
   522	                               i2s_callback_t callback, FAR void *arg,
   523	                               uint32_t timeout)
   524	{
   525	  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
   526	  FAR struct contest_i2s_xfer_s *xfer = &priv->xfer;
   527	  irqstate_t flags;
   528	  size_t logical_bytes;
   529	  size_t logical_samples;
   530	  size_t raw_bytes;
   531	  uint32_t queued;
   532	  uint32_t eof_samples;
   533	
   534	  (void)timeout;
   535	
   536	  if (apb == NULL || callback == NULL || apb->samp == NULL)
   537	    {
   538	      return -EINVAL;
   539	    }
   540	
   541	  logical_bytes = apb->nmaxbytes - apb->curbyte;
   542	  logical_bytes -= logical_bytes % sizeof(int16_t);
   543	  logical_samples = logical_bytes / sizeof(int16_t);
   544	  raw_bytes = logical_samples * sizeof(uint32_t);
   545	  if (logical_bytes == 0 || raw_bytes > sizeof(priv->raw))
   546	    {
   547	      return -EINVAL;
   548	    }
   549	
   550	  apb_reference(apb);
   551	
   552	  /* Reserve the one supported transaction while the DMA descriptor is built
   553	   * outside the spinlock.  apb_reference() and DMA setup are not IRQ-side
   554	   * operations and must not run while interrupts are locked.
   555	   */
   556	
   557	  flags = spin_lock_irqsave(&priv->lock);
   558	  if (!priv->streaming || priv->reserved || priv->active != NULL ||
   559	      priv->done != NULL)
   560	    {
   561	      spin_unlock_irqrestore(&priv->lock, flags);
   562	      apb_free(apb);
   563	      return -EBUSY;
   564	    }
   565	
   566	  priv->reserved = true;
   567	  spin_unlock_irqrestore(&priv->lock, flags);
   568	
   569	  xfer->apb = apb;
   570	  xfer->callback = callback;
   571	  xfer->arg = arg;
   572	  xfer->nbytes = logical_bytes;
   573	  xfer->result = -EINPROGRESS;
   574	  priv->logical_bytes = logical_bytes;
   575	  priv->raw_bytes = raw_bytes;
   576	  queued = esp32s3_dma_setup(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
   577	                              (FAR uint8_t *)priv->raw, raw_bytes, false,
   578	                              priv->dma_channel);
   579	  if (queued != raw_bytes)
   580	    {
   581	      flags = spin_lock_irqsave(&priv->lock);
   582	      priv->reserved = false;
   583	      spin_unlock_irqrestore(&priv->lock, flags);
   584	      apb_free(apb);
   585	      return -ENOMEM;
   586	    }
   587	
   588	  eof_samples = raw_bytes * 8 / CONTEST_INMP441_SLOT_BITS;
   589	  if (eof_samples == 0 || eof_samples > I2S_RX_EOF_NUM_V + 1)
   590	    {
   591	      flags = spin_lock_irqsave(&priv->lock);
   592	      priv->reserved = false;
   593	      spin_unlock_irqrestore(&priv->lock, flags);
   594	      apb_free(apb);
   595	      return -EINVAL;
   596	    }
   597	
   598	  /* Publish active before enabling EOF so a completion cannot be lost. */
   599	
   600	  flags = spin_lock_irqsave(&priv->lock);
   601	  if (!priv->streaming)
   602	    {
   603	      priv->reserved = false;
   604	      spin_unlock_irqrestore(&priv->lock, flags);
   605	      apb_free(apb);
   606	      return -ECANCELED;
   607	    }
   608	
   609	  priv->active = xfer;
   610	  priv->reserved = false;
   611	  esp32s3_dma_load(xfer->desc, priv->dma_channel, false);
   612	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
