   589	static uint32_t voice_isqrt(uint64_t value)
   590	{
   591	  uint64_t bit = UINT64_C(1) << 62;
   592	  uint64_t root = 0;
   593	
   594	  while (bit > value)
   595	    {
   596	      bit >>= 2;
   597	    }
   598	
   599	  while (bit != 0)
   600	    {
   601	      if (value >= root + bit)
   602	        {
   603	          value -= root + bit;
   604	          root = (root >> 1) + bit;
   605	        }
   606	      else
   607	        {
   608	          root >>= 1;
   609	        }
   610	
   611	      bit >>= 2;
   612	    }
   613	
   614	  return (uint32_t)root;
   615	}
