   193	              FIELD_TO_VALUE(I2S_RX_BITS_MOD,
   194	                             CONTEST_INMP441_VALID_BITS - 1));
   195	  modifyreg32(I2S_RX_CONF1_REG(CONTEST_I2S_PORT), I2S_RX_TDM_CHAN_BITS_M,
   196	              FIELD_TO_VALUE(I2S_RX_TDM_CHAN_BITS,
   197	                             CONTEST_INMP441_SLOT_BITS - 1));
   198	  modifyreg32(I2S_RX_CONF1_REG(CONTEST_I2S_PORT),
   199	              I2S_RX_HALF_SAMPLE_BITS_M,
   200	              FIELD_TO_VALUE(I2S_RX_HALF_SAMPLE_BITS,
   201	                             CONTEST_INMP441_SLOT_BITS - 1));
   202	  modifyreg32(I2S_RX_CONF1_REG(CONTEST_I2S_PORT), I2S_RX_TDM_WS_WIDTH_M,
   203	              FIELD_TO_VALUE(I2S_RX_TDM_WS_WIDTH,
   204	                             CONTEST_INMP441_SLOT_BITS - 1));
   205	  modifyreg32(I2S_RX_TDM_CTRL_REG(CONTEST_I2S_PORT),
   206	              I2S_RX_TDM_TOT_CHAN_NUM_M | CONTEST_I2S_RX_TDM_CHAN_MASK,
   207	              FIELD_TO_VALUE(I2S_RX_TDM_TOT_CHAN_NUM,
   208	                             CONTEST_I2S_SLOTS - 1) |
   209	              CONTEST_INMP441_RX_SLOT_MASK);
   210	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_UPDATE);
