   384	static int voice_record(struct i2s_dev_s *mic, int16_t *samples,
   385	                        size_t capacity, size_t *count,
   386	                        int16_t *minimum, int16_t *maximum, int16_t *peak,
   387	                        int64_t *sum, uint64_t *squares, size_t *clip_count)
   388	{
   389	  unsigned int empty_transfers = 0;
   390	  unsigned int chunk = 0;
   391	  clock_t deadline;
   392	  int ret;
   393	
   394	  *count = 0;
   395	  *minimum = INT16_MAX;
   396	  *maximum = INT16_MIN;
   397	  *peak = 0;
   398	  *sum = 0;
   399	  *squares = 0;
   400	  *clip_count = 0;
   401	
   402	  ret = I2S_IOCTL(mic, AUDIOIOC_START, 0);
   403	  printf("voice_echo: MIC start ret=%d\n", ret);
   404	  if (ret < 0)
   405	    {
   406	      return ret;
   407	    }
   408	
   409	  deadline = clock_systime_ticks() + MSEC2TICK(VOICE_RECORD_TIMEOUT_MS);
   410	
   411	  while (*count < capacity)
   412	    {
   413	      struct ap_buffer_s *apb;
   414	      struct voice_transfer_s *transfer;
   415	      size_t nbytes;
   416	      size_t nsamples;
   417	      size_t i;
   418	      clock_t remaining;
   419	      clock_t wait_ticks;
   420	      size_t request_bytes;
   421	      bool submitted;
   422	
   423	      request_bytes = MIN(VOICE_DMA_BYTES,
   424	                          (capacity - *count) * sizeof(int16_t));
   425	      ret = voice_buffer_alloc(&apb, request_bytes);
   426	      if (ret < 0)
   427	        {
   428	          goto errout;
   429	        }
   430	
   431	      transfer = calloc(1, sizeof(*transfer));
   432	      if (transfer == NULL)
   433	        {
   434	          apb_free(apb);
   435	          ret = -ENOMEM;
   436	          goto errout;
   437	        }
   438	
   439	      voice_transfer_init(transfer, true, true, false, chunk);
   440	
   441	      remaining = deadline - clock_systime_ticks();
   442	      if ((int32_t)remaining <= 0)
   443	        {
   444	          voice_transfer_destroy(transfer);
   445	          free(transfer);
   446	          apb_free(apb);
   447	          ret = -ETIMEDOUT;
   448	          goto errout;
   449	        }
   450	
   451	      wait_ticks = MIN(MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS), remaining);
   452	      if (!voice_rx_claim())
   453	        {
   454	          printf("voice_echo: previous RX transaction still pending\n");
   455	          voice_transfer_destroy(transfer);
   456	          free(transfer);
   457	          apb_free(apb);
   458	          ret = -EBUSY;
   459	          goto errout;
   460	        }
   461	
   462	      printf("voice_echo: RX submit chunk=%u bytes=%zu\n", chunk,
   463	             request_bytes);
   464	      ret = I2S_RECEIVE(mic, apb, voice_complete, transfer, wait_ticks);
   465	      submitted = ret >= 0;
   466	      if (!submitted)
   467	        {
   468	          voice_rx_release();
   469	        }
   470	      printf("voice_echo: RX submit chunk=%u ret=%d\n", chunk, ret);
   471	      if (submitted)
   472	        {
   473	          ret = voice_wait_transfer(transfer, wait_ticks);
   474	        }
   475	
   476	      if (ret < 0)
   477	        {
   478	          printf("voice_echo: RX wait chunk=%u failed: %d\n", chunk, ret);
   479	          if (submitted && ret == -ETIMEDOUT)
   480	            {
   481	              /* The ESP32-S3 lower-half currently does not cancel an
   482	               * enqueued RX transaction on its timeout field.  Keep the
   483	               * context alive for a late callback instead of creating a
   484	               * use-after-free.  The callback releases the APB and context.
   485	               */
   486	
   487	              if (voice_abandon_transfer(transfer))
   488	                {
   489	                  (void)I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
   490	                  goto errout;
   491	                }
   492	
   493	              nxmutex_lock(&transfer->lock);
   494	              ret = transfer->result;
   495	              nxmutex_unlock(&transfer->lock);
   496	            }
   497	          else
   498	            {
   499	              voice_transfer_destroy(transfer);
   500	              free(transfer);
   501	              apb_free(apb);
   502	            }
   503	
   504	          if (ret < 0)
   505	            {
   506	              goto errout;
   507	            }
   508	        }
   509	
   510	      voice_transfer_destroy(transfer);
   511	      if (transfer->apb == NULL)
   512	        {
   513	          free(transfer);
   514	          apb_free(apb);
   515	          ret = -EIO;
   516	          goto errout;
   517	        }
   518	
   519	      nbytes = transfer->apb->nbytes;
   520	      nbytes -= nbytes % sizeof(int16_t);

