   742	static void contest_i2s_tx_set_rate(FAR struct contest_i2s_tx_s *priv)
   743	{
   744	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
   745	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
   746	  uint32_t freq_diff = CONTEST_I2S_SOURCE_CLOCK % mclk;
   747	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS * priv->data_width;
   748	  uint32_t bclk_div = mclk / bclk;
   749	  uint32_t numerator = 0;
   750	  uint32_t denominator = 1;
   751	  uint32_t regval;
   752	  uint32_t a;
   753	
   754	  /* This is the CLK160 fractional-divider procedure used by the reference
   755	   * ESP32-S3 I2S lower-half.  At 24 kHz it resolves to 26 + 1/24.
   756	   */
   757	
   758	  if (freq_diff != 0)
   759	    {
   760	      for (a = 2; a <= 63; a++)
   761	        {
   762	          uint32_t b = (freq_diff * a + mclk / 2) / mclk;
   763	
   764	          if (b != 0 && freq_diff * a == mclk * b)
   765	            {
   766	              numerator = b;
   767	              denominator = a;
   768	              break;
   769	            }
   770	        }
   771	    }
   772	
   773	  regval = getreg32(I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
   774	  regval &= ~I2S_TX_CLKM_DIV_NUM_M;
   775	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_NUM, mclk_div);
   776	  putreg32(regval, I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
   777	
   778	  regval = getreg32(I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT));
   779	  regval &= ~(I2S_TX_CLKM_DIV_Z_M | I2S_TX_CLKM_DIV_Y_M |
   780	              I2S_TX_CLKM_DIV_X_M | I2S_TX_CLKM_DIV_YN1_M);
   781	  if (numerator != 0)
   782	    {
   783	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Z, numerator);
   784	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Y, denominator % numerator);
   785	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_X,
   786	                               denominator / numerator - 1);
