      for (i = 0; i < chunk; i++)
        {
          size_t source = ((output_index + i) * VOICE_INPUT_RATE) /
                          VOICE_OUTPUT_RATE;

          ((int16_t *)apb->samp)[i] = samples[source];
        }

      apb->nbytes = chunk * sizeof(int16_t);
      apb->nsamples = chunk;
      voice_transfer_init(transfer, false, false, true, chunk_index);
      printf("voice_echo: TX submit chunk=%u bytes=%zu\n", chunk_index,
             apb->nbytes);
      ret = I2S_SEND(speaker, apb, voice_complete, transfer,
                     MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
      submitted = ret >= 0;
      printf("voice_echo: TX submit chunk=%u ret=%d\n", chunk_index, ret);
      if (submitted)
        {
          ret = voice_wait_transfer(transfer,
                                    MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
        }

      if (ret < 0)
        {
          printf("voice_echo: TX wait chunk=%u failed: %d\n", chunk_index,
                 ret);
          if (submitted && voice_abandon_transfer(transfer))
            {
              int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);

              printf("voice_echo: SPK stop ret=%d\n", stop_ret);
              /* The callback owns transfer and the application's APB
               * reference after abandonment.  It releases both safely.
               */

              return ret;
            }

          voice_transfer_destroy(transfer);
          free(transfer);
          apb_free(apb);
          goto errout;
        }

      voice_transfer_destroy(transfer);
      free(transfer);
      apb_free(apb);
      output_index += chunk;
      chunk_index++;
    }

errout:
  {
    int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);

    printf("voice_echo: SPK stop ret=%d\n", stop_ret);
    if (ret >= 0 && stop_ret < 0)
      {
        ret = stop_ret;
      }
  }

  return ret;
}

int main(int argc, char *argv[])
{
  struct i2s_dev_s *mic;
  struct i2s_dev_s *speaker;
  struct voice_oled_s oled;
  int16_t *samples;
  size_t capacity = VOICE_INPUT_RATE * VOICE_ECHO_RECORD_SECONDS;
  bool once_alias = argc == 2 && strcmp(argv[1], "--once") == 0;
  int ret;

  if (argc > 2 || (argc == 2 && !once_alias))
    {
      printf("Usage: voice_echo [--once]\n");
      return EXIT_FAILURE;
    }

  printf("voice_echo: MIC acquire start\n");
  mic = board_voice_mic_i2s();
  if (mic != NULL)
    {
      printf("voice_echo: MIC acquire OK\n");
    }

  speaker = board_voice_speaker_i2s();
  if (mic == NULL || speaker == NULL)
    {
      printf("I2S unavailable\n");
      return EXIT_FAILURE;
    }

  ret = voice_configure_i2s(mic, speaker);
  if (ret < 0)
    {
      printf("I2S format configuration failed: %d\n", ret);
      return EXIT_FAILURE;
    }

  samples = malloc(capacity * sizeof(*samples));
  if (samples == NULL)
    {
      printf("Record buffer allocation failed\n");
      return EXIT_FAILURE;
    }

  voice_oled_init(&oled);
  printf("MIC: I2S0 RX, SPK: I2S1 TX\n");
  printf("Rate: %d Hz -> %d Hz, slot: %d bit, sample: %d bit, mono\n",
         VOICE_INPUT_RATE, VOICE_OUTPUT_RATE, VOICE_SLOT_BITS,
         VOICE_SAMPLE_BITS);
  printf("Record duration: %d s\n", VOICE_ECHO_RECORD_SECONDS);

  {
    int16_t minimum;
    int16_t maximum;
    int16_t peak;
    int64_t sum;
    uint64_t squares;
    size_t clip_count;
    size_t count;

    voice_oled_show(&oled, "REC", "5 SEC");
    printf("voice_echo: recording %d seconds...\n",
           VOICE_ECHO_RECORD_SECONDS);
    ret = voice_record(mic, samples, capacity, &count, &minimum, &maximum,
                       &peak, &sum, &squares, &clip_count);
    if (ret < 0)
      {
        printf("voice_echo: MIC RX failed: %d\n", ret);
        voice_oled_show(&oled, "MIC ERROR", "");
      }
    else
      {
        printf("voice_echo: captured %zu bytes\n",
               count * sizeof(*samples));
        printf("voice_echo: min=%d max=%d peak=%d\n", minimum, maximum,
               peak);
        printf("voice_echo: mean=%ld rms=%lu clip_count=%zu\n",
               (long)(sum / (int64_t)count),
               (unsigned long)voice_isqrt(squares / count), clip_count);
        voice_oled_show(&oled, "PLAY", "");
        printf("voice_echo: playing...\n");
        ret = voice_play(speaker, samples, count);
        if (ret < 0)
          {
            printf("voice_echo: SPK TX failed: %d\n", ret);
            voice_oled_show(&oled, "SPK ERROR", "");
          }
        else
          {
            printf("voice_echo: playback complete\n");
            voice_oled_show(&oled, "DONE", "");
          }
      }
  }

  free(samples);
  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}
    }

  priv->rx_irq = ESP32S3_PERIPH2IRQ(periph);
  ret = irq_attach(priv->rx_irq, contest_i2s_rx_interrupt, priv);
  if (ret < 0)
    {
      esp32s3_teardown_irq(priv->cpu, periph, cpuint);
      esp32s3_dma_release(priv->dma_channel);
      priv->dma_channel = -1;
      return NULL;
    }

  up_enable_irq(priv->rx_irq);
  priv->initialized = true;
  syslog(LOG_INFO, "[C-I2S] init port=0\n");
  syslog(LOG_INFO, "[C-I2S] dma_channel=%d irq=%d\n", priv->dma_channel,
         priv->rx_irq);
  return &priv->dev;
}

FAR struct i2s_dev_s *contest_i2s_initialize(int port)
{
  if (port == CONTEST_I2S_PORT)
    {
      return contest_i2s0_initialize();
    }

  if (port == CONTEST_I2S_TX_PORT)
    {
      return contest_i2s1_initialize();
    }

  return NULL;
}

