static uint32_t voice_isqrt(uint64_t value)
{
  uint64_t bit = UINT64_C(1) << 62;
  uint64_t root = 0;

  while (bit > value)
    {
      bit >>= 2;
    }

  while (bit != 0)
    {
      if (value >= root + bit)
        {
          value -= root + bit;
          root = (root >> 1) + bit;
        }
      else
        {
          root >>= 1;
        }

      bit >>= 2;
    }

  return (uint32_t)root;
}

static int voice_play(struct i2s_dev_s *speaker, const int16_t *samples,
                      size_t count)
{
  size_t output_count = (count * VOICE_OUTPUT_RATE + VOICE_INPUT_RATE - 1) /
                        VOICE_INPUT_RATE;
  size_t output_index = 0;
  unsigned int chunk_index = 0;
  int ret;

  ret = I2S_IOCTL(speaker, AUDIOIOC_START, 0);
  printf("voice_echo: SPK start ret=%d\n", ret);
  if (ret < 0)
    {
      return ret;
    }

  while (output_index < output_count)
    {
      struct ap_buffer_s *apb;
      struct voice_transfer_s *transfer;
      size_t chunk = output_count - output_index;
      size_t i;
      bool submitted;

      if (chunk > VOICE_DMA_BYTES / sizeof(int16_t))
        {
          chunk = VOICE_DMA_BYTES / sizeof(int16_t);
        }

      ret = voice_buffer_alloc(&apb, VOICE_DMA_BYTES);
      if (ret < 0)
        {
          goto errout;
        }

      transfer = calloc(1, sizeof(*transfer));
      if (transfer == NULL)
        {
          apb_free(apb);
          ret = -ENOMEM;
          goto errout;
        }

      for (i = 0; i < chunk; i++)
        {
          size_t source = ((output_index + i) * VOICE_INPUT_RATE) /
                          VOICE_OUTPUT_RATE;

          ((int16_t *)apb->samp)[i] = samples[source];
        }

      apb->nbytes = chunk * sizeof(int16_t);
      apb->nsamples = chunk;
      voice_transfer_init(transfer, false, false, true, chunk_index);
      printf("voice_echo: TX submit chunk=%u bytes=%zu\n", chunk_index,
             apb->nbytes);
      ret = I2S_SEND(speaker, apb, voice_complete, transfer,
                     MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
      submitted = ret >= 0;
      printf("voice_echo: TX submit chunk=%u ret=%d\n", chunk_index, ret);
      if (submitted)
        {
          ret = voice_wait_transfer(transfer,
                                    MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
        }

      if (ret < 0)
        {
          printf("voice_echo: TX wait chunk=%u failed: %d\n", chunk_index,
                 ret);
          if (submitted && voice_abandon_transfer(transfer))
            {
              int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);

              printf("voice_echo: SPK stop ret=%d\n", stop_ret);
              /* The callback owns transfer and the application's APB
               * reference after abandonment.  It releases both safely.
               */

              return ret;
            }

          voice_transfer_destroy(transfer);
          free(transfer);
          apb_free(apb);
          goto errout;
        }

      voice_transfer_destroy(transfer);
      free(transfer);
      apb_free(apb);
      output_index += chunk;
      chunk_index++;
    }

errout:
  {
    int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);

    printf("voice_echo: SPK stop ret=%d\n", stop_ret);
    if (ret >= 0 && stop_ret < 0)
      {
        ret = stop_ret;
      }
  }

  return ret;
}

int main(int argc, char *argv[])
{
  struct i2s_dev_s *mic;
  struct i2s_dev_s *speaker;
  struct voice_oled_s oled;
  int16_t *samples;
  size_t capacity = VOICE_INPUT_RATE * VOICE_ECHO_RECORD_SECONDS;
  bool once_alias = argc == 2 && strcmp(argv[1], "--once") == 0;
  int ret;

  if (argc > 2 || (argc == 2 && !once_alias))
    {
      printf("Usage: voice_echo [--once]\n");
      return EXIT_FAILURE;
    }

  printf("voice_echo: MIC acquire start\n");
  mic = board_voice_mic_i2s();
  if (mic != NULL)
    {
      printf("voice_echo: MIC acquire OK\n");
    }

  speaker = board_voice_speaker_i2s();
  if (mic == NULL || speaker == NULL)
    {
      printf("I2S unavailable\n");
      return EXIT_FAILURE;
    }

  ret = voice_configure_i2s(mic, speaker);
  if (ret < 0)
    {
      printf("I2S format configuration failed: %d\n", ret);
      return EXIT_FAILURE;
    }

  samples = malloc(capacity * sizeof(*samples));
  if (samples == NULL)
    {
      printf("Record buffer allocation failed\n");
      return EXIT_FAILURE;
    }

  voice_oled_init(&oled);
  printf("MIC: I2S0 RX, SPK: I2S1 TX\n");
  printf("Rate: %d Hz -> %d Hz, slot: %d bit, sample: %d bit, mono\n",
         VOICE_INPUT_RATE, VOICE_OUTPUT_RATE, VOICE_SLOT_BITS,
         VOICE_SAMPLE_BITS);
  printf("Record duration: %d s\n", VOICE_ECHO_RECORD_SECONDS);

  {
    int16_t minimum;
    int16_t maximum;
    int16_t peak;
    int64_t sum;
    uint64_t squares;
    size_t clip_count;
    size_t count;

    voice_oled_show(&oled, "REC", "5 SEC");
    printf("voice_echo: recording %d seconds...\n",
           VOICE_ECHO_RECORD_SECONDS);
    ret = voice_record(mic, samples, capacity, &count, &minimum, &maximum,
                       &peak, &sum, &squares, &clip_count);
    if (ret < 0)
      {
        printf("voice_echo: MIC RX failed: %d\n", ret);
        voice_oled_show(&oled, "MIC ERROR", "");
      }
    else
      {
        printf("voice_echo: captured %zu bytes\n",
               count * sizeof(*samples));
        printf("voice_echo: min=%d max=%d peak=%d\n", minimum, maximum,
               peak);
        printf("voice_echo: mean=%ld rms=%lu clip_count=%zu\n",
               (long)(sum / (int64_t)count),
               (unsigned long)voice_isqrt(squares / count), clip_count);
        voice_oled_show(&oled, "PLAY", "");
        printf("voice_echo: playing...\n");
        ret = voice_play(speaker, samples, count);
        if (ret < 0)
          {
            printf("voice_echo: SPK TX failed: %d\n", ret);
            voice_oled_show(&oled, "SPK ERROR", "");
          }
        else
          {
            printf("voice_echo: playback complete\n");
            voice_oled_show(&oled, "DONE", "");
          }
      }
  }

  free(samples);
  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

RESULT 4:
# INMP441 Physical I2S RX Format Requirements

## 1. Current State

`contest_i2s.c` owns I2S0 RX for the contest board.  The public I2S API
exposes logical 16-bit, mono PCM at 16 kHz to `voice_echo`.

The current RX transaction DMA-writes directly into the logical APB buffer.
It programs the bus width from the logical 16-bit width and reports descriptor
byte counts to the application.  On hardware this produces a 512 kHz BCLK and
reports 1024 bytes for a 2048-byte request.  The captured stream is not valid
INMP441 PCM.

The current I2S1 TX implementation, 16 kHz to 24 kHz playback conversion,
Wi-Fi, OLED, PWM, and robot control are outside this change.

## 2. New Feature Requirements

The I2S0 hardware interface shall use the INMP441 physical framing while the
public API remains logical signed 16-bit mono PCM:

| Property | Required value |
| --- | --- |
| Sample rate | 16000 Hz |
| I2S standard | Philips/I2S |
| Hardware slots | 2 per frame |
| Hardware slot width | 32 BCLK cycles |
| Microphone valid width | 24 signed bits |
| Hardware BCLK | 1024000 Hz |
| Selected RX slot | LEFT (`MIC_L/R` is LOW) |
| Public PCM | signed `int16_t`, mono |

For a logical 2048-byte APB request, the lower-half shall receive 1024
logical samples into a separate 4096-byte raw DMA buffer.  The HPWORK worker
shall convert the raw words into exactly 2048 bytes of signed 16-bit PCM,
set `apb->nbytes` to 2048 and `apb->nsamples` to 1024, and invoke the normal
I2S callback once.

The raw DMA buffer and the large `voice_echo` record buffer have different
ownership.  The raw buffer is owned by the contest I2S transaction and must
remain DMA-safe until the completion worker has run.  The large record buffer
remains application storage and must not be used for DMA.

## 3. L/R Slot Selection

The approved schematic establishes the microphone channel selection:

```text
MIC1 L/R -> MIC_L/R -> R10 10K -> GND
```

`MIC_L/R` is therefore hardware-tied LOW.  The contest-local I2S0 driver
shall select the standard **LEFT** slot only, using active-channel mask
`0x01`.  It shall not probe, switch to, or otherwise attempt the RIGHT slot
at runtime.

## 4. Hardware Configuration and Data Flow

The RX lower-half shall configure I2S0 as master RX with GPIO16 BCLK output,
GPIO17 WS output, and GPIO18 DIN input.  It shall set Philips MSB shift,
32-bit physical transfer/channel/half-sample width, 32-BCLK WS width, two
total slots, and only the selected slot active.  INMP441's 24 valid bits are
interpreted during raw-to-PCM conversion, not as the physical EOF unit.

```text
INMP441 24-bit sample in 32-bit physical slot
  -> contest I2S0 raw DMA buffer
  -> RX EOF interrupt
  -> HPWORK conversion and APB completion
  -> logical int16 PCM callback
  -> voice_echo record buffer
```

The ISR shall only acknowledge DMA completion, mark the transaction done,
and queue HPWORK.  It shall not convert samples or invoke the upper callback.
The worker shall release raw DMA storage only after callback completion.

## 5. RX EOF and DMA Constraints

`CONFIG_I2S_DMADESC_NUM=2` must queue the complete 4096-byte raw request via
`esp32s3_dma_setup()`.  Partial descriptor setup is an error.

The ESP32-S3 register header documents RX EOF in units of
`(RX_BITS_MOD + 1) * (RXEOF_NUM + 1)` bits.  The driver programs the physical
32-bit slot width in `RX_BITS_MOD`, so a 4096-byte raw transaction uses
`RXEOF_NUM = 1023`.  Raw diagnostics remain enabled for the first transaction
to validate sample alignment on hardware.

## 6. Conversion and Diagnostics

The first completed transaction shall log sixteen raw 32-bit words plus
raw non-zero count, low-eight-bit non-zero count, minimum, and maximum.  The
initial conversion candidate is the upper signed 16 bits of a left-justified
24-bit word (`raw >> 16`), but the final shift must be supported by those raw
diagnostics.

Per recording, `voice_echo` shall report min, max, mean/DC, RMS, peak, and
clip count for converted logical PCM.  Normal speech must not be accepted as
success merely because it reaches full-scale values.

