   116	static void voice_complete(struct i2s_dev_s *dev, struct ap_buffer_s *apb,
   117	                           void *arg, int result)
   118	{
   119	  struct voice_transfer_s *transfer = arg;
   120	  size_t nbytes = apb == NULL ? 0 : apb->nbytes;
   121	  bool abandoned;
   122	
   123	  (void)dev;
   124	
   125	  if (transfer->log_rx)
   126	    {
   127	      printf("voice_echo: RX callback chunk=%u result=%d bytes=%zu\n",
   128	             transfer->chunk, result, nbytes);
   129	      voice_rx_release();
   130	    }
   131	
   132	  if (transfer->log_tx)
   133	    {
   134	      printf("voice_echo: TX callback chunk=%u result=%d bytes=%zu\n",
   135	             transfer->chunk, result, nbytes);
   136	    }
   137	
   138	  nxmutex_lock(&transfer->lock);
   139	  abandoned = transfer->abandoned;
   140	
   141	  if (abandoned)
   142	    {
   143	      /* The lower-half still owns one reference and will release it after
   144	       * this callback.  Release the application's original reference here.
   145	       */
   146	
   147	      nxmutex_unlock(&transfer->lock);
   148	      if (apb != NULL)
   149	        {
   150	          apb_free(apb);
   151	        }
   152	      nxmutex_destroy(&transfer->lock);
   153	      nxsem_destroy(&transfer->done);
   154	      free(transfer);
   155	      return;
   156	    }
   157	
   158	  if (transfer->retain_apb && apb != NULL && result >= 0)
   159	    {
   160	      apb_reference(apb);
   161	      transfer->apb = apb;
   162	    }
   163	
   164	  transfer->result = result;
   165	  transfer->callback_done = true;
   166	  nxsem_post(&transfer->done);
   167	  nxmutex_unlock(&transfer->lock);
   168	}
