   191	static bool voice_abandon_transfer(struct voice_transfer_s *transfer)
   192	{
   193	  nxmutex_lock(&transfer->lock);
   194	  if (transfer->callback_done)
   195	    {
   196	      nxmutex_unlock(&transfer->lock);
   197	      return false;
   198	    }
   199	
   200	  transfer->abandoned = true;
   201	  nxmutex_unlock(&transfer->lock);
   202	  return true;
   203	}
