   617	static int voice_play(struct i2s_dev_s *speaker, const int16_t *samples,
   618	                      size_t count)
   619	{
   620	  size_t output_count = (count * VOICE_OUTPUT_RATE + VOICE_INPUT_RATE - 1) /
   621	                        VOICE_INPUT_RATE;
   622	  size_t output_index = 0;
   623	  unsigned int chunk_index = 0;
   624	  int ret;
   625	
   626	  ret = I2S_IOCTL(speaker, AUDIOIOC_START, 0);
   627	  printf("voice_echo: SPK start ret=%d\n", ret);
   628	  if (ret < 0)
   629	    {
   630	      return ret;
   631	    }
   632	
   633	  while (output_index < output_count)
   634	    {
   635	      struct ap_buffer_s *apb;
   636	      struct voice_transfer_s *transfer;
   637	      size_t chunk = output_count - output_index;
   638	      size_t i;
   639	      bool submitted;
   640	
   641	      if (chunk > VOICE_DMA_BYTES / sizeof(int16_t))
   642	        {
   643	          chunk = VOICE_DMA_BYTES / sizeof(int16_t);
   644	        }
   645	
   646	      ret = voice_buffer_alloc(&apb, VOICE_DMA_BYTES);
   647	      if (ret < 0)
   648	        {
   649	          goto errout;
   650	        }
   651	
   652	      transfer = calloc(1, sizeof(*transfer));
   653	      if (transfer == NULL)
   654	        {
   655	          apb_free(apb);
   656	          ret = -ENOMEM;
   657	          goto errout;
   658	        }
   659	
   660	      for (i = 0; i < chunk; i++)
   661	        {
   662	          size_t source = ((output_index + i) * VOICE_INPUT_RATE) /
   663	                          VOICE_OUTPUT_RATE;
   664	
   665	          ((int16_t *)apb->samp)[i] = samples[source];
   666	        }
   667	
   668	      apb->nbytes = chunk * sizeof(int16_t);
   669	      apb->nsamples = chunk;
   670	      voice_transfer_init(transfer, false, false, true, chunk_index);
   671	      printf("voice_echo: TX submit chunk=%u bytes=%zu\n", chunk_index,
   672	             apb->nbytes);
   673	      ret = I2S_SEND(speaker, apb, voice_complete, transfer,
   674	                     MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
   675	      submitted = ret >= 0;
   676	      printf("voice_echo: TX submit chunk=%u ret=%d\n", chunk_index, ret);
   677	      if (submitted)
   678	        {
   679	          ret = voice_wait_transfer(transfer,
   680	                                    MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
   681	        }
   682	
   683	      if (ret < 0)
   684	        {
   685	          printf("voice_echo: TX wait chunk=%u failed: %d\n", chunk_index,
   686	                 ret);
   687	          if (submitted && voice_abandon_transfer(transfer))
   688	            {
   689	              int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);
   690	
   691	              printf("voice_echo: SPK stop ret=%d\n", stop_ret);
   692	              /* The callback owns transfer and the application's APB
   693	               * reference after abandonment.  It releases both safely.
   694	               */
   695	
   696	              return ret;
   697	            }
   698	
   699	          voice_transfer_destroy(transfer);
   700	          free(transfer);
   701	          apb_free(apb);
   702	          goto errout;
   703	        }
   704	
   705	      voice_transfer_destroy(transfer);
   706	      free(transfer);
   707	      apb_free(apb);
   708	      output_index += chunk;
   709	      chunk_index++;
   710	    }
   711	
   712	errout:
   713	  {
   714	    int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);
   715	
   716	    printf("voice_echo: SPK stop ret=%d\n", stop_ret);
   717	    if (ret >= 0 && stop_ret < 0)
   718	      {
   719	        ret = stop_ret;
   720	      }
   721	  }
   722	
   723	  return ret;
   724	}
