   756	static void contest_i2s_tx_set_rate(FAR struct contest_i2s_tx_s *priv)
   757	{
   758	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
   759	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
   760	  uint32_t freq_diff = CONTEST_I2S_SOURCE_CLOCK % mclk;
   761	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS * priv->data_width;
   762	  uint32_t bclk_div = mclk / bclk;
   763	  uint32_t numerator = 0;
   764	  uint32_t denominator = 1;
   765	  uint32_t regval;
   766	  uint32_t a;
   767	
   768	  /* This is the CLK160 fractional-divider procedure used by the reference
   769	   * ESP32-S3 I2S lower-half.  At 24 kHz it resolves to 26 + 1/24.
   770	   */
   771	
   772	  if (freq_diff != 0)
   773	    {
   774	      for (a = 2; a <= 63; a++)
   775	        {
   776	          uint32_t b = (freq_diff * a + mclk / 2) / mclk;
   777	
   778	          if (b != 0 && freq_diff * a == mclk * b)
   779	            {
   780	              numerator = b;
   781	              denominator = a;
   782	              break;
   783	            }
   784	        }
   785	    }
   786	
   787	  regval = getreg32(I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
   788	  regval &= ~I2S_TX_CLKM_DIV_NUM_M;
   789	  regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_NUM, mclk_div);
   790	  putreg32(regval, I2S_TX_CLKM_CONF_REG(CONTEST_I2S_TX_PORT));
   791	
   792	  regval = getreg32(I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT));
   793	  regval &= ~(I2S_TX_CLKM_DIV_Z_M | I2S_TX_CLKM_DIV_Y_M |
   794	              I2S_TX_CLKM_DIV_X_M | I2S_TX_CLKM_DIV_YN1_M);
   795	  if (numerator != 0)
   796	    {
   797	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Z, numerator);
   798	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_Y, denominator % numerator);
   799	      regval |= FIELD_TO_VALUE(I2S_TX_CLKM_DIV_X,
   800	                               denominator / numerator - 1);
   801	    }
   802	
   803	  putreg32(regval, I2S_TX_CLKM_DIV_CONF_REG(CONTEST_I2S_TX_PORT));
   804	  modifyreg32(I2S_TX_CONF1_REG(CONTEST_I2S_TX_PORT), I2S_TX_BCK_DIV_NUM_M,
   805	              FIELD_TO_VALUE(I2S_TX_BCK_DIV_NUM, bclk_div - 1));
   806	  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_UPDATE);
   807	}
