}

static void voice_oled_init(struct voice_oled_s *oled)
{
  memset(oled, 0, sizeof(*oled));

  if (board_oled_initialize() < 0)
    {
      printf("OLED unavailable\n");
      return;
    }

  oled->dev = board_oled_getdev();
  if (oled->dev == NULL || oled->dev->getplaneinfo(oled->dev, 0,
                                                    &oled->plane) < 0)
    {
      printf("OLED unavailable\n");
      return;
    }

  oled->available = true;
}

static int voice_record(struct i2s_dev_s *mic, int16_t *samples,
                        size_t capacity, size_t *count,
                        int16_t *minimum, int16_t *maximum, int16_t *peak,
                        int64_t *sum, uint64_t *squares, size_t *clip_count)
{
  unsigned int empty_transfers = 0;
  unsigned int chunk = 0;
  clock_t deadline;
  int ret;

  *count = 0;
  *minimum = INT16_MAX;
  *maximum = INT16_MIN;
  *peak = 0;
  *sum = 0;
  *squares = 0;
  *clip_count = 0;

  ret = I2S_IOCTL(mic, AUDIOIOC_START, 0);
  printf("voice_echo: MIC start ret=%d\n", ret);
  if (ret < 0)
    {
      return ret;
    }

  deadline = clock_systime_ticks() + MSEC2TICK(VOICE_RECORD_TIMEOUT_MS);

  while (*count < capacity)
    {
      struct ap_buffer_s *apb;
      struct voice_transfer_s *transfer;
      size_t nbytes;
      size_t nsamples;
      size_t i;
      clock_t remaining;
      clock_t wait_ticks;
      size_t request_bytes;
      bool submitted;

      request_bytes = MIN(VOICE_DMA_BYTES,
                          (capacity - *count) * sizeof(int16_t));
      ret = voice_buffer_alloc(&apb, request_bytes);
      if (ret < 0)
        {
          goto errout;
        }

      transfer = calloc(1, sizeof(*transfer));
      if (transfer == NULL)
        {
          apb_free(apb);
          ret = -ENOMEM;
          goto errout;
        }

      voice_transfer_init(transfer, true, true, false, chunk);

      remaining = deadline - clock_systime_ticks();
      if ((int32_t)remaining <= 0)
        {
          voice_transfer_destroy(transfer);
          free(transfer);
          apb_free(apb);
          ret = -ETIMEDOUT;
          goto errout;
        }

      wait_ticks = MIN(MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS), remaining);
      if (!voice_rx_claim())
        {
          printf("voice_echo: previous RX transaction still pending\n");
          voice_transfer_destroy(transfer);
          free(transfer);
          apb_free(apb);
          ret = -EBUSY;
          goto errout;
        }

      printf("voice_echo: RX submit chunk=%u bytes=%zu\n", chunk,
             request_bytes);
      ret = I2S_RECEIVE(mic, apb, voice_complete, transfer, wait_ticks);
      submitted = ret >= 0;
      if (!submitted)
        {
          voice_rx_release();
        }
      printf("voice_echo: RX submit chunk=%u ret=%d\n", chunk, ret);
      if (submitted)
        {
          ret = voice_wait_transfer(transfer, wait_ticks);
        }

      if (ret < 0)
        {
          printf("voice_echo: RX wait chunk=%u failed: %d\n", chunk, ret);
          if (submitted && ret == -ETIMEDOUT)
            {
              /* The ESP32-S3 lower-half currently does not cancel an
               * enqueued RX transaction on its timeout field.  Keep the
               * context alive for a late callback instead of creating a
               * use-after-free.  The callback releases the APB and context.
               */

              if (voice_abandon_transfer(transfer))
                {
                  (void)I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
                  goto errout;
                }

              nxmutex_lock(&transfer->lock);
              ret = transfer->result;
              nxmutex_unlock(&transfer->lock);
            }
          else
            {
              voice_transfer_destroy(transfer);
              free(transfer);
              apb_free(apb);
            }

          if (ret < 0)
            {
              goto errout;
            }
        }

      voice_transfer_destroy(transfer);
      if (transfer->apb == NULL)
        {
          free(transfer);
          apb_free(apb);
          ret = -EIO;
          goto errout;
        }

      nbytes = transfer->apb->nbytes;
      nbytes -= nbytes % sizeof(int16_t);

      nbytes -= nbytes % sizeof(int16_t);
      nbytes = nbytes > (capacity - *count) * sizeof(int16_t) ?
               (capacity - *count) * sizeof(int16_t) : nbytes;
      nsamples = nbytes / sizeof(int16_t);
      memcpy(&samples[*count], transfer->apb->samp, nbytes);
      apb_free(transfer->apb);
      apb_free(apb);
      free(transfer);

      for (i = 0; i < nsamples; i++)
        {
          int16_t value = samples[*count + i];
          int16_t absolute = value == INT16_MIN ? INT16_MAX :
                             (value < 0 ? -value : value);

          if (value < *minimum)
            {
              *minimum = value;
            }

          if (value > *maximum)
            {
              *maximum = value;
            }

          if (absolute > *peak)
            {
              *peak = absolute;
            }

          *sum += value;
          *squares += (int64_t)value * value;
          if (value == INT16_MIN || value == INT16_MAX)
            {
              (*clip_count)++;
            }
        }

      *count += nsamples;
      chunk++;
      if (nsamples == 0)
        {
          if (++empty_transfers >= 6)
            {
              ret = -ETIMEDOUT;
              goto errout;
            }
        }
      else
        {
          empty_transfers = 0;
        }
    }

  ret = 0;

errout:
  {
    int stop_ret = I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
    printf("voice_echo: MIC stop ret=%d\n", stop_ret);
    if (ret >= 0 && stop_ret < 0)
      {
        ret = stop_ret;
      }
  }

  return ret;
}

static uint32_t voice_isqrt(uint64_t value)
{
  uint64_t bit = UINT64_C(1) << 62;
  uint64_t root = 0;

  while (bit > value)
    {
      bit >>= 2;
    }

  while (bit != 0)
    {
      if (value >= root + bit)
        {
          value -= root + bit;
          root = (root >> 1) + bit;
        }
      else
        {
          root >>= 1;
        }

      bit >>= 2;
    }

  return (uint32_t)root;
}

static int voice_play(struct i2s_dev_s *speaker, const int16_t *samples,
                      size_t count)
{
  size_t output_count = (count * VOICE_OUTPUT_RATE + VOICE_INPUT_RATE - 1) /
                        VOICE_INPUT_RATE;
  size_t output_index = 0;
  unsigned int chunk_index = 0;
  int ret;

  ret = I2S_IOCTL(speaker, AUDIOIOC_START, 0);
  printf("voice_echo: SPK start ret=%d\n", ret);
  if (ret < 0)
    {
      return ret;
    }

  while (output_index < output_count)
    {
      struct ap_buffer_s *apb;
      struct voice_transfer_s *transfer;
      size_t chunk = output_count - output_index;
      size_t i;
      bool submitted;

      if (chunk > VOICE_DMA_BYTES / sizeof(int16_t))
        {
          chunk = VOICE_DMA_BYTES / sizeof(int16_t);
        }

      ret = voice_buffer_alloc(&apb, VOICE_DMA_BYTES);
      if (ret < 0)
        {
          goto errout;
        }

      transfer = calloc(1, sizeof(*transfer));
      if (transfer == NULL)
        {
          apb_free(apb);
          ret = -ENOMEM;
          goto errout;
        }

      for (i = 0; i < chunk; i++)
        {
          size_t source = ((output_index + i) * VOICE_INPUT_RATE) /
                          VOICE_OUTPUT_RATE;

          ((int16_t *)apb->samp)[i] = samples[source];
        }

      apb->nbytes = chunk * sizeof(int16_t);
      apb->nsamples = chunk;
      voice_transfer_init(transfer, false, false, true, chunk_index);
      printf("voice_echo: TX submit chunk=%u bytes=%zu\n", chunk_index,
             apb->nbytes);
      ret = I2S_SEND(speaker, apb, voice_complete, transfer,
                     MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
      submitted = ret >= 0;
      printf("voice_echo: TX submit chunk=%u ret=%d\n", chunk_index, ret);
      if (submitted)
        {
          ret = voice_wait_transfer(transfer,
                                    MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
        }

      if (ret < 0)
        {
          printf("voice_echo: TX wait chunk=%u failed: %d\n", chunk_index,
                 ret);
          if (submitted && voice_abandon_transfer(transfer))
            {
              int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);

              printf("voice_echo: SPK stop ret=%d\n", stop_ret);
              /* The callback owns transfer and the application's APB
               * reference after abandonment.  It releases both safely.
               */

              return ret;
            }

          voice_transfer_destroy(transfer);
          free(transfer);
          apb_free(apb);
          goto errout;
        }

      voice_transfer_destroy(transfer);
      free(transfer);
      apb_free(apb);
      output_index += chunk;
      chunk_index++;
    }

errout:
  {
    int stop_ret = I2S_IOCTL(speaker, AUDIOIOC_STOP, 0);

    printf("voice_echo: SPK stop ret=%d\n", stop_ret);
    if (ret >= 0 && stop_ret < 0)
      {
        ret = stop_ret;
      }
  }

  return ret;
}

int main(int argc, char *argv[])
{
  struct i2s_dev_s *mic;
  struct i2s_dev_s *speaker;
  struct voice_oled_s oled;
  int16_t *samples;
  size_t capacity = VOICE_INPUT_RATE * VOICE_ECHO_RECORD_SECONDS;
  bool once_alias = argc == 2 && strcmp(argv[1], "--once") == 0;
  int ret;

  if (argc > 2 || (argc == 2 && !once_alias))
    {
      printf("Usage: voice_echo [--once]\n");
      return EXIT_FAILURE;
    }

  printf("voice_echo: MIC acquire start\n");
  mic = board_voice_mic_i2s();
  if (mic != NULL)
    {
      printf("voice_echo: MIC acquire OK\n");
    }

  speaker = board_voice_speaker_i2s();
  if (mic == NULL || speaker == NULL)
    {
      printf("I2S unavailable\n");
      return EXIT_FAILURE;
    }

  ret = voice_configure_i2s(mic, speaker);
  if (ret < 0)
    {
      printf("I2S format configuration failed: %d\n", ret);
      return EXIT_FAILURE;
    }

  samples = malloc(capacity * sizeof(*samples));
  if (samples == NULL)
    {
      printf("Record buffer allocation failed\n");
      return EXIT_FAILURE;
    }

  voice_oled_init(&oled);
  printf("MIC: I2S0 RX, SPK: I2S1 TX\n");
  printf("Rate: %d Hz -> %d Hz, slot: %d bit, sample: %d bit, mono\n",
         VOICE_INPUT_RATE, VOICE_OUTPUT_RATE, VOICE_SLOT_BITS,
         VOICE_SAMPLE_BITS);
  printf("Record duration: %d s\n", VOICE_ECHO_RECORD_SECONDS);

  {
    int16_t minimum;
    int16_t maximum;
    int16_t peak;
    int64_t sum;
    uint64_t squares;
    size_t clip_count;
    size_t count;

    voice_oled_show(&oled, "REC", "5 SEC");
    printf("voice_echo: recording %d seconds...\n",
           VOICE_ECHO_RECORD_SECONDS);
    ret = voice_record(mic, samples, capacity, &count, &minimum, &maximum,
                       &peak, &sum, &squares, &clip_count);
    if (ret < 0)
      {
        printf("voice_echo: MIC RX failed: %d\n", ret);
        voice_oled_show(&oled, "MIC ERROR", "");
      }
    else
      {
        printf("voice_echo: captured %zu bytes\n",
               count * sizeof(*samples));
        printf("voice_echo: min=%d max=%d peak=%d\n", minimum, maximum,
               peak);
        printf("voice_echo: mean=%ld rms=%lu clip_count=%zu\n",
               (long)(sum / (int64_t)count),
               (unsigned long)voice_isqrt(squares / count), clip_count);
        voice_oled_show(&oled, "PLAY", "");
        printf("voice_echo: playing...\n");
        ret = voice_play(speaker, samples, count);
        if (ret < 0)
          {
            printf("voice_echo: SPK TX failed: %d\n", ret);
            voice_oled_show(&oled, "SPK ERROR", "");
          }
        else
          {
            printf("voice_echo: playback complete\n");
            voice_oled_show(&oled, "DONE", "");
          }
      }
  }

  free(samples);
  return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
}

