  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), 0, I2S_TX_RESET);
  modifyreg32(I2S_TX_CONF_REG(CONTEST_I2S_TX_PORT), I2S_TX_RESET, 0);
