  struct i2s_dev_s *mic = NULL;
  struct i2s_dev_s *speaker = NULL;
  struct voice_oled_s oled;
  int16_t *samples = NULL;
  size_t capacity = VOICE_INPUT_RATE * VOICE_ECHO_RECORD_SECONDS;
  switch (cmd)
    {
      case AUDIOIOC_START:
        flags = spin_lock_irqsave(&priv->lock);
        priv->streaming = true;
        priv->eof_count = 0;
        priv->chained_count = 0;
        priv->underrun_count = 0;
        priv->started_once = false;
        priv->idle = false;
        spin_unlock_irqrestore(&priv->lock, flags);
        up_enable_irq(priv->tx_irq);
        return OK;

      case AUDIOIOC_STOP:
        flags = spin_lock_irqsave(&priv->lock);
        priv->streaming = false;
        contest_i2s_tx_capture_state(priv, priv->active);
        contest_i2s_tx_stop_hw(priv);
        if (priv->active != NULL)
          {
            xfer = priv->active;
            xfer->result = -ECANCELED;
            contest_i2s_tx_done_push(priv, xfer);
            priv->active = NULL;
            schedule = true;
          }

        if (priv->pending != NULL)
          {
            xfer = priv->pending;
            xfer->result = -ECANCELED;
            contest_i2s_tx_done_push(priv, xfer);
            priv->pending = NULL;
            schedule = true;
          }

        priv->idle = false;
        spin_unlock_irqrestore(&priv->lock, flags);
        syslog(LOG_INFO, "[C-I2S] tx eof=%lu chained=%lu underrun=%lu\n",
               (unsigned long)priv->eof_count,
               (unsigned long)priv->chained_count,
               (unsigned long)priv->underrun_count);
        if (schedule)
          {
            contest_i2s_tx_dump_state(priv);
            if (work_available(&priv->tx_work))
              {
                work_queue(HPWORK, &priv->tx_work, contest_i2s_tx_worker,
                           priv, 0);
              }
          }

        return OK;

      default:
        return -ENOTTY;
    }
}

