   472	static void contest_i2s_set_rate(FAR struct contest_i2s_s *priv)
   473	{
   474	  uint32_t mclk = priv->rate * CONTEST_I2S_MCLK_MULTIPLE;
   475	  uint32_t mclk_div = CONTEST_I2S_SOURCE_CLOCK / mclk;
   476	  uint32_t remainder = CONTEST_I2S_SOURCE_CLOCK % mclk;
   477	  uint32_t bclk = priv->rate * CONTEST_I2S_SLOTS *
   478	                  CONTEST_INMP441_SLOT_BITS;
   479	  uint32_t bclk_div = mclk / bclk;
   480	  uint32_t regval;
   481	  uint32_t numerator = 0;
   482	  uint32_t denominator = 1;
   483	  uint32_t a;
   484	
   485	  /* Match the ESP32-S3 reference driver's CLK160 fractional divider. */
   486	
   487	  if (remainder != 0)
   488	    {
   489	      for (a = 2; a <= 63; a++)
   490	        {
   491	          uint32_t b = (remainder * a + mclk / 2) / mclk;
   492	
   493	          if (b != 0 && remainder * a == mclk * b)
   494	            {
   495	              numerator = b;
   496	              denominator = a;
   497	              break;
   498	            }
   499	        }
   500	    }
   501	
   502	  if (numerator == 0)
   503	    {
   504	      denominator = 1;
   505	    }
   506	
   507	  regval = getreg32(I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
   508	  regval &= ~I2S_RX_CLKM_DIV_NUM_M;
   509	  regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_NUM, mclk_div);
   510	  putreg32(regval, I2S_RX_CLKM_CONF_REG(CONTEST_I2S_PORT));
   511	
   512	  regval = getreg32(I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
   513	  regval &= ~(I2S_RX_CLKM_DIV_Z_M | I2S_RX_CLKM_DIV_Y_M |
   514	              I2S_RX_CLKM_DIV_X_M | I2S_RX_CLKM_DIV_YN1_M);
   515	  if (numerator != 0)
   516	    {
   517	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Z, numerator);
   518	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_Y, denominator % numerator);
   519	      regval |= FIELD_TO_VALUE(I2S_RX_CLKM_DIV_X,
   520	                               denominator / numerator - 1);
   521	    }
   522	
   523	  putreg32(regval, I2S_RX_CLKM_DIV_CONF_REG(CONTEST_I2S_PORT));
   524	
   525	  modifyreg32(I2S_RX_CONF1_REG(CONTEST_I2S_PORT), I2S_RX_BCK_DIV_NUM_M,
   526	              FIELD_TO_VALUE(I2S_RX_BCK_DIV_NUM, bclk_div - 1));
   527	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_UPDATE);
   528	}
