   530	static void contest_i2s_rx_worker(FAR void *arg)
   531	{
   532	  FAR struct contest_i2s_s *priv = arg;
   533	  FAR struct contest_i2s_xfer_s *xfer;
   534	  FAR struct ap_buffer_s *apb;
   535	  i2s_callback_t callback;
   536	  FAR void *callback_arg;
   537	  int result;
   538	  uint32_t irq_status;
   539	  irqstate_t flags;
   540	  size_t logical_bytes;
   541	  size_t raw_bytes;
   542	  size_t logical_samples;
   543	  unsigned int i;
   544	
   545	  flags = spin_lock_irqsave(&priv->lock);
   546	  xfer = priv->done;
   547	  irq_status = priv->irq_status;
   548	  spin_unlock_irqrestore(&priv->lock, flags);
   549	
   550	  if (xfer == NULL)
   551	    {
   552	      return;
   553	    }
   554	
   555	  result = xfer->result;
   556	  logical_bytes = priv->logical_bytes;
   557	  raw_bytes = priv->raw_bytes;
   558	  logical_samples = logical_bytes / sizeof(int16_t);
   559	
   560	  syslog(LOG_INFO, "[C-I2S] rx eof status=%08lx\n",
   561	         (unsigned long)irq_status);
   562	
   563	  if (result >= 0 &&
   564	      (logical_bytes == 0 ||
   565	       raw_bytes != logical_samples * sizeof(uint32_t)))
   566	    {
   567	      result = -EIO;
   568	    }
   569	
   570	  if (result >= 0)
   571	    {
   572	      FAR int16_t *pcm = (FAR int16_t *)(xfer->apb->samp +
   573	                                         xfer->apb->curbyte);
   574	
   575	      up_invalidate_dcache((uintptr_t)priv->raw,
   576	                           (uintptr_t)priv->raw + raw_bytes);
   577	
   578	      if (!priv->raw_logged)
   579	        {
   580	          /* This runs after GDMA EOF and cache invalidation, before the
   581	           * first raw32-to-PCM conversion.  It is deliberately one-shot.
   582	           */
   583	
   584	          contest_i2s_log_raw_diagnostics(priv, logical_samples);
   585	          priv->raw_logged = true;
   586	        }
   587	
   588	      for (i = 0; i < logical_samples; i++)
   589	        {
   590	          /* INMP441 samples are expected to be left-justified in the raw
   591	           * slot.  The first transaction's raw log is the hardware gate for
   592	           * retaining this conversion shift.
   593	           */
   594	
   595	          pcm[i] = (int16_t)((int32_t)priv->raw[i] >>
   596	                             CONTEST_I2S_RX_PCM_SHIFT);
   597	        }
   598	
   599	      xfer->apb->nbytes = logical_bytes;
   600	      xfer->apb->nsamples = logical_samples;
   601	    }
   602	  else
   603	    {
   604	      xfer->apb->nbytes = 0;
   605	      xfer->apb->nsamples = 0;
   606	    }
   607	
   608	  /* Retain done through raw conversion so receive() cannot reuse the static
   609	   * raw buffer.  It is safe to admit the next transfer immediately before
   610	   * the callback because the worker no longer accesses this transaction.
   611	   */
   612	
   613	  apb = xfer->apb;
   614	  callback = xfer->callback;
   615	  callback_arg = xfer->arg;
   616	
   617	  flags = spin_lock_irqsave(&priv->lock);
   618	  if (priv->done == xfer)
   619	    {
   620	      priv->done = NULL;
   621	    }
   622	
   623	  spin_unlock_irqrestore(&priv->lock, flags);
   624	
   625	  syslog(LOG_INFO, "[C-I2S] rx worker bytes=%zu\n", logical_bytes);
   626	  syslog(LOG_INFO, "[C-I2S] rx callback\n");
   627	  callback(&priv->dev, apb, callback_arg, result);
   628	  apb_free(apb);
   629	}
