   642	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
   643	
   644	  if ((status & (DMA_IN_SUC_EOF_CH0_INT_ST |
   645	                 DMA_IN_ERR_EOF_CH0_INT_ST)) == 0)
   646	    {
   647	      return OK;
   648	    }
   649	
   650	  flags = spin_lock_irqsave(&priv->lock);
   651	  if (priv->active != NULL)
   652	    {
   653	      priv->active->result = (status & DMA_IN_SUC_EOF_CH0_INT_ST) != 0 ?
   654	                             OK : -EIO;
   655	      priv->done = priv->active;
   656	      priv->active = NULL;
   657	      priv->irq_status = status;
   658	      contest_i2s_stop_hw(priv);
   659	      work…1510 tokens truncated… 810	  xfer->nbytes = logical_bytes;
   811	  xfer->result = -EINPROGRESS;
   812	  priv->logical_bytes = logical_bytes;
   813	  priv->raw_bytes = raw_bytes;
   814	  queued = esp32s3_dma_setup(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
   815	                              (FAR uint8_t *)priv->raw, raw_bytes, false,
   816	                              priv->dma_channel);
   817	  if (queued != raw_bytes)
   818	    {
   819	      flags = spin_lock_irqsave(&priv->lock);
   820	      priv->reserved = false;
   821	      spin_unlock_irqrestore(&priv->lock, flags);
   822	      apb_free(apb);
   823	      return -ENOMEM;
   824	    }
   825	
   826	  eof_samples = raw_bytes * 8 / CONTEST_INMP441_SLOT_BITS;
   827	  if (eof_samples == 0 || eof_samples > I2S_RX_EOF_NUM_V + 1)
   828	    {
   829	      flags = spin_lock_irqsave(&priv->lock);
   830	      priv->reserved = false;
   831	      spin_unlock_irqrestore(&priv->lock, flags);
   832	      apb_free(apb);
   833	      return -EINVAL;
   834	    }
   835	
   836	  /* Publish active before enabling EOF so a completion cannot be lost. */
   837	
   838	  flags = spin_lock_irqsave(&priv->lock);
   839	  if (!priv->streaming)
   840	    {
   841	      priv->reserved = false;
   842	      spin_unlock_irqrestore(&priv->lock, flags);
   843	      apb_free(apb);
   844	      return -ECANCELED;
   845	    }
   846	
   847	  priv->active = xfer;
   848	  priv->reserved = false;
   849	  esp32s3_dma_load(xfer->desc, priv->dma_channel, false);
   850	  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
   851	  SET_GDMA_CH_BITS(DMA_IN_INT_ENA_CH0_REG, priv->dma_channel,
   852	                   DMA_IN_SUC_EOF_CH0_INT_ENA | DMA_IN_ERR_EOF_CH0_INT_ENA);
   853	  modifyreg32(I2S_RXEOF_NUM_REG(CONTEST_I2S_PORT), I2S_RX_EOF_NUM_M,
   854	              FIELD_TO_VALUE(I2S_RX_EOF_NUM, eof_samples - 1));
   855	  esp32s3_dma_enable(priv->dma_channel, false);
   856	  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_START);
   857	  spin_unlock_irqrestore(&priv->lock, flags);
   858	
   859	  syslog(LOG_INFO, "[C-I2S] rx submit bytes=%zu\n", logical_bytes);
   860	  syslog(LOG_INFO, "[C-I2S] raw bytes=%zu logical bytes=%zu\n", raw_bytes,
   861	         logical_bytes);
   862	  syslog(LOG_INFO, "[C-I2S] rx dma start eof=%lu\n",
   863	         (unsigned long)(eof_samples - 1));
   864	  return OK;
   865	}
