   867	static int contest_i2s_ioctl(FAR struct i2s_dev_s *dev, int cmd,
   868	                             unsigned long arg)
   869	{
   870	  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
   871	  FAR struct contest_i2s_xfer_s *xfer = NULL;
   872	  irqstate_t flags;
   873	
   874	  (void)arg;
   875	
   876	  switch (cmd)
   877	    {
   878	      case AUDIOIOC_START:
   879	        flags = spin_lock_irqsave(&priv->lock);
   880	        priv->streaming = true;
   881	        spin_unlock_irqrestore(&priv->lock, flags);
   882	        return OK;
   883	
   884	      case AUDIOIOC_STOP:
   885	        flags = spin_lock_irqsave(&priv->lock);
   886	        priv->streaming = false;
   887	        if (priv->active != NULL)
   888	          {
   889	            xfer = priv->active;
   890	            xfer->result = -ECANCELED;
   891	            priv->done = xfer;
   892	            priv->active = NULL;
   893	            contest_i2s_stop_hw(priv);
   894	          }
   895	
   896	        spin_unlock_irqrestore(&priv->lock, flags);
   897	        if (xfer != NULL)
   898	          {
   899	            work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker,
   900	                       priv, 0);
   901	          }
   902	
   903	        return OK;
   904	
   905	      default:
   906	        return -ENOTTY;
   907	    }
   908	}
