static int contest_i2s_rxchannels(FAR struct i2s_dev_s *dev,
                                  uint8_t channels)
{
  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;

  if (channels != 1 && channels != 2)
    {
      return -EINVAL;
    }

  priv->channels = channels;
  return OK;
}

static uint32_t contest_i2s_rxsamplerate(FAR struct i2s_dev_s *dev,
                                         uint32_t rate)
{
  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;

  if (rate != CONTEST_I2S_RATE)
    {
      return 0;
    }

  priv->rate = rate;
  contest_i2s_set_rate(priv);
  return rate;
}

static uint32_t contest_i2s_rxdatawidth(FAR struct i2s_dev_s *dev,
                                        int bits)
{
  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;

  if (bits != CONTEST_I2S_WIDTH)
    {
      return 0;
    }

  priv->data_width = bits;
  contest_i2s_set_format(priv);
  contest_i2s_set_rate(priv);
  return bits;
}

static int contest_i2s_receive(FAR struct i2s_dev_s *dev,
                               FAR struct ap_buffer_s *apb,
                               i2s_callback_t callback, FAR void *arg,
                               uint32_t timeout)
{
  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
  FAR struct contest_i2s_xfer_s *xfer = &priv->xfer;
  irqstate_t flags;
  size_t logical_bytes;
  size_t logical_samples;
  size_t raw_bytes;
  uint32_t queued;
  uint32_t eof_samples;

  (void)timeout;

  if (apb == NULL || callback == NULL || apb->samp == NULL)
    {
      return -EINVAL;
    }

  logical_bytes = apb->nmaxbytes - apb->curbyte;
  logical_bytes -= logical_bytes % sizeof(int16_t);
  logical_samples = logical_bytes / sizeof(int16_t);
  raw_bytes = logical_samples * sizeof(uint32_t);
  if (logical_bytes == 0 || raw_bytes > sizeof(priv->raw))
    {
      return -EINVAL;
    }

  apb_reference(apb);

  /* Reserve the one supported transaction while the DMA descriptor is built
   * outside the spinlock.  apb_reference() and DMA setup are not IRQ-side
   * operations and must not run while interrupts are locked.
   */

  flags = spin_lock_irqsave(&priv->lock);
  if (!priv->streaming || priv->reserved || priv->active != NULL ||
      priv->done != NULL)
    {
      spin_unlock_irqrestore(&priv->lock, flags);
      apb_free(apb);
      return -EBUSY;
    }

  priv->reserved = true;
  spin_unlock_irqrestore(&priv->lock, flags);

  xfer->apb = apb;
  xfer->callback = callback;
  xfer->arg = arg;
  xfer->nbytes = logical_bytes;
  xfer->result = -EINPROGRESS;
  priv->logical_bytes = logical_bytes;
  priv->raw_bytes = raw_bytes;
  queued = esp32s3_dma_setup(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
                              (FAR uint8_t *)priv->raw, raw_bytes, false,
                              priv->dma_channel);
  if (queued != raw_bytes)
    {
      flags = spin_lock_irqsave(&priv->lock);
      priv->reserved = false;
      spin_unlock_irqrestore(&priv->lock, flags);
      apb_free(apb);
      return -ENOMEM;
    }

  eof_samples = raw_bytes * 8 / CONTEST_INMP441_SLOT_BITS;
  if (eof_samples == 0 || eof_samples > I2S_RX_EOF_NUM_V + 1)
    {
      flags = spin_lock_irqsave(&priv->lock);
      priv->reserved = false;
      spin_unlock_irqrestore(&priv->lock, flags);
      apb_free(apb);
      return -EINVAL;
    }

  /* Publish active before enabling EOF so a completion cannot be lost. */

  flags = spin_lock_irqsave(&priv->lock);
  if (!priv->streaming)
    {
      priv->reserved = false;
      spin_unlock_irqrestore(&priv->lock, flags);
      apb_free(apb);
      return -ECANCELED;
    }

  priv->active = xfer;
  priv->reserved = false;
  esp32s3_dma_load(xfer->desc, priv->dma_channel, false);
  SET_GDMA_CH_REG(DMA_IN_INT_CLR_CH0_REG, priv->dma_channel, UINT32_MAX);
  SET_GDMA_CH_BITS(DMA_IN_INT_ENA_CH0_REG, priv->dma_channel,
                   DMA_IN_SUC_EOF_CH0_INT_ENA | DMA_IN_ERR_EOF_CH0_INT_ENA);
  modifyreg32(I2S_RXEOF_NUM_REG(CONTEST_I2S_PORT), I2S_RX_EOF_NUM_M,
              FIELD_TO_VALUE(I2S_RX_EOF_NUM, eof_samples - 1));
  esp32s3_dma_enable(priv->dma_channel, false);
  modifyreg32(I2S_RX_CONF_REG(CONTEST_I2S_PORT), 0, I2S_RX_START);
  spin_unlock_irqrestore(&priv->lock, flags);

  syslog(LOG_INFO, "[C-I2S] rx submit bytes=%zu\n", logical_bytes);
  syslog(LOG_INFO, "[C-I2S] raw bytes=%zu logical bytes=%zu\n", raw_bytes,
         logical_bytes);
  syslog(LOG_INFO, "[C-I2S] rx dma start eof=%lu\n",
         (unsigned long)(eof_samples - 1));
  return OK;
}

static int contest_i2s_ioctl(FAR struct i2s_dev_s *dev, int cmd,
                             unsigned long arg)
{
  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
  FAR struct contest_i2s_xfer_s *xfer = NULL;
  irqstate_t flags;

  (void)arg;

  switch (cmd)
    {
      case AUDIOIOC_START:
        flags = spin_lock_irqsave(&priv->lock);
        priv->streaming = true;
        spin_unlock_irqrestore(&priv->lock, flags);
        return OK;

      case AUDIOIOC_STOP:
        flags = spin_lock_irqsave(&priv->lock);
        priv->streaming = false;
        if (priv->active != NULL)
          {
            xfer = priv->active;
            xfer->result = -ECANCELED;
            priv->done = xfer;
            priv->active = NULL;
            contest_i2s_stop_hw(priv);
          }

        spin_unlock_irqrestore(&priv->lock, flags);
        if (xfer != NULL)
          {
            work_queue(HPWORK, &priv->rx_work, contest_i2s_rx_worker,
                       priv, 0);
          }

