static int contest_i2s_receive(FAR struct i2s_dev_s *dev,
                               FAR struct ap_buffer_s *apb,
                               i2s_callback_t callback, FAR void *arg,
                               uint32_t timeout)
{
  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
  FAR struct contest_i2s_rx_xfer_s *xfer = NULL;
  irqstate_t flags;
  size_t logical_bytes;
  size_t logical_samples;
  size_t raw_bytes;
  uint32_t queued;
  unsigned int i;

  (void)timeout;

  if (apb == NULL || callback == NULL || apb->samp == NULL)
    {
      return -EINVAL;
    }

  logical_bytes = apb->nmaxbytes - apb->curbyte;
  logical_bytes -= logical_bytes % sizeof(int16_t);
  logical_samples = logical_bytes / sizeof(int16_t);
  raw_bytes = logical_samples * sizeof(uint32_t);
  if (logical_bytes == 0 || raw_bytes > CONTEST_I2S_RX_RAW_MAX_BYTES)
    {
      return -EINVAL;
    }

  apb_reference(apb);

  /* Reserve a free transaction while the descriptor is built outside the
   * spinlock.  active and pending each retain independent raw DMA storage.
   */

  flags = spin_lock_irqsave(&priv->lock);
  if (!priv->streaming || priv->reserved || priv->pending != NULL)
    {
      spin_unlock_irqrestore(&priv->lock, flags);
      apb_free(apb);
      return -EBUSY;
    }

  for (i = 0; i < CONTEST_I2S_RX_XFER_COUNT; i++)
    {
      if (!priv->xfer[i].in_use)
        {
          xfer = &priv->xfer[i];
          xfer->in_use = true;
          break;
        }
    }

  if (xfer == NULL)
    {
      spin_unlock_irqrestore(&priv->lock, flags);
      apb_free(apb);
      return -EBUSY;
    }

  priv->reserved = true;
  spin_unlock_irqrestore(&priv->lock, flags);

  xfer->next = NULL;
  xfer->apb = apb;
  xfer->callback = callback;
  xfer->arg = arg;
  xfer->logical_bytes = logical_bytes;
  xfer->raw_bytes = raw_bytes;
  xfer->result = -EINPROGRESS;
  queued = esp32s3_dma_setup(xfer->desc, CONTEST_I2S_DMA_DESC_COUNT,
                              (FAR uint8_t *)xfer->raw, raw_bytes, false,
                              priv->dma_channel);
  if (queued != raw_bytes)
    {
      flags = spin_lock_irqsave(&priv->lock);
      priv->reserved = false;
      xfer->in_use = false;
      spin_unlock_irqrestore(&priv->lock, flags);
      apb_free(apb);
      return -ENOMEM;
    }

  /* Publish before hardware can complete.  The first transaction becomes
   * active; the second becomes pending and is started by the EOF ISR.
   */

  flags = spin_lock_irqsave(&priv->lock);
  if (!priv->streaming)
    {
      priv->reserved = false;
      xfer->in_use = false;
      spin_unlock_irqrestore(&priv->lock, flags);
      apb_free(apb);
      return -ECANCELED;
    }

  priv->reserved = false;
  if (priv->active == NULL)
    {
      if (priv->started_once && priv->idle)
        {
          priv->underrun_count++;
        }

      priv->active = xfer;
      contest_i2s_rx_start_active(priv);
    }
  else
    {
      priv->pending = xfer;
    }

  spin_unlock_irqrestore(&priv->lock, flags);

  if (priv->eof_count < 3)
    {
      syslog(LOG_INFO, "[C-I2S] rx submit bytes=%zu\n", logical_bytes);
      syslog(LOG_INFO, "[C-I2S] raw bytes=%zu logical bytes=%zu\n",
             raw_bytes, logical_bytes);
      syslog(LOG_INFO, "[C-I2S] rx dma start eof=%lu\n",
             (unsigned long)(raw_bytes * 8 /
                             CONTEST_INMP441_SLOT_BITS - 1));
    }

  return OK;
}

static int contest_i2s_ioctl(FAR struct i2s_dev_s *dev, int cmd,
                             unsigned long arg)
{
  FAR struct contest_i2s_s *priv = (FAR struct contest_i2s_s *)dev;
  FAR struct contest_i2s_rx_xfer_s *xfer;
  irqstate_t flags;
  bool schedule = false;

  (void)arg;

  switch (cmd)
    {
      case AUDIOIOC_START:
        flags = spin_lock_irqsave(&priv->lock);
        priv->streaming = true;
        priv->eof_count = 0;
        priv->chained_count = 0;
        priv->underrun_count = 0;
        priv->started_once = false;
        priv->idle = false;
        spin_unlock_irqrestore(&priv->lock, flags);
        return OK;

      case AUDIOIOC_STOP:
        flags = spin_lock_irqsave(&priv->lock);
        priv->streaming = false;
        contest_i2s_stop_hw(priv);
        if (priv->active != NULL)
          {
            xfer = priv->active;
            xfer->result = -ECANCELED;

  ret = I2S_IOCTL(mic, AUDIOIOC_START, 0);
  printf("voice_echo: MIC start ret=%d\n", ret);
  if (ret < 0)
    {
      return ret;
    }

  deadline = clock_systime_ticks() + MSEC2TICK(VOICE_RECORD_TIMEOUT_MS);
  while (submitted_bytes < target_bytes && in_flight < VOICE_RX_SLOT_COUNT)
    {
      size_t request_bytes = MIN(VOICE_DMA_BYTES,
                                 target_bytes - submitted_bytes);

      ret = voice_rx_slot_submit(mic, &slots[in_flight], request_bytes,
                                 submit_chunk++);
      if (ret < 0)
        {
          goto errout;
        }

      submitted_bytes += request_bytes;
      submitted++;
      in_flight++;
    }

  while (in_flight != 0)
    {
      struct voice_rx_slot_s *slot = &slots[wait_slot];
      clock_t remaining = deadline - clock_systime_ticks();
      clock_t wait_ticks;

      if ((int32_t)remaining <= 0)
        {
          ret = -ETIMEDOUT;
          goto errout;
        }

      wait_ticks = MIN(MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS), remaining);
      ret = voice_rx_slot_wait(slot, wait_ticks);
      if (ret < 0)
        {
          printf("voice_echo: RX wait chunk=%u failed: %d\n", slot->chunk,
                 ret);
          goto errout;
        }

      ret = voice_rx_account(slot, samples, capacity, count, minimum,
                             maximum, peak, sum, squares, clip_count,
                             max_adjacent_delta, &boundaries);
      if (ret < 0)
        {
          printf("voice_echo: RX chunk=%u invalid logical byte count\n",
                 slot->chunk);
          goto errout;
        }

      voice_rx_slot_release(slot);
      completed++;
      in_flight--;
      if (submitted_bytes < target_bytes)
        {
          size_t request_bytes = MIN(VOICE_DMA_BYTES,
                                     target_bytes - submitted_bytes);

          ret = voice_rx_slot_submit(mic, slot, request_bytes,
                                     submit_chunk++);
          if (ret < 0)
            {
              goto errout;
            }

          submitted_bytes += request_bytes;
          submitted++;
          in_flight++;
        }

      wait_slot = (wait_slot + 1) % VOICE_RX_SLOT_COUNT;
    }

  if (*count != capacity || submitted_bytes != target_bytes)
    {
      ret = -EIO;
      goto errout;
    }

  ret = I2S_IOCTL(mic, AUDIOIOC_STOP, 0);
  printf("voice_echo: MIC stop ret=%d\n", ret);
  printf("voice_echo: RX submitted=%u completed=%u\n", submitted,
         completed);
  voice_rx_report_boundaries(&boundaries);
  return ret;

errout:
  (void)voice_rx_abort(mic, slots);
  printf("voice_echo: RX submitted=%u completed=%u\n", submitted,
         completed);
  return ret;
}

