#define CONTEST_I2S_SOURCE_CLOCK        160000000UL
#define CONTEST_I2S_MCLK_MULTIPLE       256
#define CONTEST_I2S_DMA_DESC_COUNT      CONFIG_I2S_DMADESC_NUM

struct contest_i2s_xfer_s
{
  FAR struct contest_i2s_xfer_s *next;
