              I2S_RX_TDM_TOT_CHAN_NUM_M | CONTEST_I2S_RX_TDM_CHAN_MASK,
              FIELD_TO_VALUE(I2S_RX_TDM_TOT_CHAN_NUM,
                             CONTEST_I2S_SLOTS - 1) |
