  ret = I2S_SEND(speaker, slot->apb, voice_complete, slot->transfer,
                 MSEC2TICK(VOICE_TRANSFER_TIMEOUT_MS));
  if (chunk < 2 || ret < 0)
    {
      printf("voice_echo: TX submit chunk=%u ret=%d\n", chunk, ret);
    }

