    }

  nsamples = nbytes / sizeof(int16_t);
  if (nsamples == 0)
    {
      return -EIO;
    }

  memcpy(&samples[*count], transfer->apb->samp, nbytes);
  for (i = 0; i < nsamples; i++)
    {
      int16_t value = samples[*count + i];
      int16_t absolute = value == INT16_MIN ? INT16_MAX :
                         (value < 0 ? -value : value);

      if (i == 0)
        {
          chunk_first = value;
        }

      chunk_last = value;
      if (value == 0)
        {
          zero_count++;
        }
      else if (first_nonzero == SIZE_MAX)
        {
          first_nonzero = i;
        }

      if (value < chunk_min)
        {
          chunk_min = value;
        }

      if (value > chunk_max)
        {
          chunk_max = value;
        }

      if (i != 0)
        {
          int32_t delta = (int32_t)value - samples[*count + i - 1];

          if (delta < 0)
            {
              delta = -delta;
            }

          if ((uint32_t)delta > chunk_delta)
            {
              chunk_delta = delta;
            }
        }

      if (*count + i != 0)
        {
          int32_t delta = (int32_t)value - samples[*count + i - 1];

          if (delta < 0)
            {
              delta = -delta;
            }

          if ((uint32_t)delta > *max_adjacent_delta)
            {
              *max_adjacent_delta = delta;
            }
        }

