        free(s_voice.pcm_buf);
        s_voice.pcm_buf = NULL;
        pthread_mutex_unlock(&s_voice.lock);
        return -ret;
    }

    /* Now start capture — wait for recording thread to be ready first */
    sem_wait(&s_voice.rec_ready);

    if (audio_capture_start(s_voice.cap) < 0) {

/* ── Voice failure cooldown — prevent error-message cascade ──── */

static volatile bool s_voice_cooldown;
static time_t s_voice_cooldown_until;

/**
 * Reads messages from the outbound queue and dispatches them to the
 * appropriate channel (FeiShu, WebSocket, CLI, etc.).
 */
static void* outbound_dispatch_task(void* arg)
{
    (void)arg;
    syslog(LOG_INFO, "[%s] Outbound dispatch started\n", TAG);

    while (!g_shutdown_requested) {
        agent_msg_t msg;
        if (message_bus_pop_outbound(&msg, 1000) != OK)
            continue;
        msg.channel[sizeof(msg.channel) - 1] = '\0';
        msg.chat_id[sizeof(msg.chat_id) - 1] = '\0';

        if (!msg.content) {
            syslog(LOG_WARNING, "[%s] Skip outbound message with NULL content\n", TAG);
            continue;
        }

        syslog(LOG_INFO, "[%s] Dispatching response → %s:%s\n", TAG, msg.channel, msg.chat_id);

        /* Let registered taps intercept before normal dispatch */
        if (mbus_tap_try_deliver(&msg)) {
            free(msg.content);
            continue;
        }

        if (strcmp(msg.channel, AGENT_CHAN_FEISHU) == 0) {
            bool delivered = false;
#ifdef CONFIG_AI_AGENT_FEISHU
            const char* app_id = feishu_get_app_id();
            if (app_id && app_id[0] != '\0') {
                feishu_send_message(msg.chat_id, msg.content);
                delivered = true;
            }
#endif
#ifdef CONFIG_AI_AGENT_NODE
            if (!delivered) {
                delivered = node_client_send_chat_message(
                    msg.channel, msg.chat_id, msg.content) == OK;
            }
#endif
            if (!delivered) {
                syslog(LOG_WARNING,
                    "[%s] Feishu message dropped: no local config "
                    "and no gateway\n",
                    TAG);
            }
        } else if (strcmp(msg.channel, AGENT_CHAN_WEBSOCKET) == 0) {
            ws_server_send(msg.chat_id, msg.content);
#ifdef CONFIG_AI_AGENT_MQTT
        } else if (strcmp(msg.channel, AGENT_CHAN_MQTT) == 0) {
            mqtt_channel_send(msg.chat_id, msg.content);
#endif
        } else if (strcmp(msg.channel, AGENT_CHAN_VOICE) == 0) {
            /* Check voice cooldown — skip voice dispatch if a recent
             * speak call failed, to prevent error-message cascade. */
            if (s_voice_cooldown && time(NULL) < s_voice_cooldown_until) {
                syslog(LOG_WARNING,
                    "[%s] voice cooldown active, dropping message\n", TAG);
            } else {
                s_voice_cooldown = false;
                int vret = voice_channel_speak(msg.content);
                if (vret != 0) {
                    syslog(LOG_ERR, "[%s] voice_channel_speak failed: %d\n", TAG, vret);
                    s_voice_cooldown = true;
                    s_voice_cooldown_until = time(NULL) + 5;
                }
            }
#ifdef CONFIG_AI_AGENT_LVGL_UI
        } else if (strcmp(msg.channel, AGENT_CHAN_LVGL_UI) == 0) {
            int uret = lvgl_ui_channel_send(msg.content);
            if (uret != 0) {
                syslog(LOG_ERR, "[%s] lvgl_ui_channel_send failed: %d\n", TAG, uret);
            }
#endif
#ifdef CONFIG_AI_AGENT_WEIXIN
        } else if (strcmp(msg.channel, AGENT_CHAN_WEIXIN) == 0) {
            /* chat_id format: "from_user_id|context_token" */
            char uid[64] = "";
            const char* ctx = "";
            char* sep = strchr(msg.chat_id, '|');
            if (sep) {
                size_t ulen = (size_t)(sep - msg.chat_id);
                if (ulen >= sizeof(uid))
                    ulen = sizeof(uid) - 1;
                memcpy(uid, msg.chat_id, ulen);
                uid[ulen] = '\0';
                ctx = sep + 1;
            } else {
                strncpy(uid, msg.chat_id, sizeof(uid) - 1);
            }
            weixin_channel_send(uid, ctx, msg.content);
#endif
        } else if (strcmp(msg.channel, AGENT_CHAN_SYSTEM) == 0) {
            syslog(LOG_INFO, "[%s] System message [%s]: %.128s\n", TAG, msg.chat_id, msg.content);
#ifdef CONFIG_FEATURE_SYSTEM_VELACLAW
        } else if (strcmp(msg.channel, AGENT_CHAN_QUICKAPP) == 0) {
            quickapp_mq_dispatch(msg.chat_id, msg.content);
#endif
        } else if (strcmp(msg.channel, "cli") == 0) {
            pthread_mutex_lock(&g_stdout_lock);
            printf("\n[Agent]: %s\nvela> ", msg.content);
            fflush(stdout);
            pthread_mutex_unlock(&g_stdout_lock);
            syslog(LOG_INFO, "[agent] [Agent]: %s\n", msg.content);
        } else {
            syslog(LOG_WARNING, "[%s] Unknown channel: %s\n", TAG, msg.channel);
        }
    if (cJSON_IsObject(hdr)) {
        cJSON* eid = cJSON_GetObjectItem(hdr, "event_id");
        if (cJSON_IsString(eid) && eid->valuestring[0]) {
            if (dedup_check_and_record(eid->valuestring)) {
                goto cleanup; /* Duplicate event, skip silently */
            }
        }
    }

    /* Check event type */
    {
        const char* event_type = "";
        if (cJSON_IsObject(hdr)) {
            cJSON* et = cJSON_GetObjectItem(hdr, "event_type");
            if (cJSON_IsString(et)) {
                event_type = et->valuestring;
            }
        }
        if (strcmp(event_type, "im.message.receive_v1") != 0) {
            syslog(LOG_DEBUG, "[%s] ignored event_type=%s\n", TAG, event_type);
            goto cleanup;
        }
    }

    if (!cJSON_IsObject(ev)) {
        goto cleanup;
    }

    if (filter_sender(ev)) {
        goto cleanup;
    }

    /* Check if sender is a bot (for rate limiting) */
    bool is_bot_sender = false;
    {
        cJSON* sender = cJSON_GetObjectItem(ev, "sender");
        if (cJSON_IsObject(sender)) {
            cJSON* sender_type = cJSON_GetObjectItem(sender, "sender_type");
            if (cJSON_IsString(sender_type) &&
                strcmp(sender_type->valuestring, "app") == 0) {
                is_bot_sender = true;
            }
        }
    }

    cJSON* msg = cJSON_GetObjectItem(ev, "message");
    if (!cJSON_IsObject(msg)) {
        goto cleanup;
    }

    cJSON* chat_id_j = cJSON_GetObjectItem(msg, "chat_id");
    cJSON* content_j = cJSON_GetObjectItem(msg, "content");
    cJSON* msg_type_j = cJSON_GetObjectItem(msg, "message_type");
    const char* msg_type = cJSON_IsString(msg_type_j) ? msg_type_j->valuestring : "text";

    syslog(LOG_DEBUG, "[%s] msg_type=%s\n", TAG, msg_type);

    /* Bot-to-bot rate limiting */
    if (is_bot_sender && cJSON_IsString(chat_id_j)) {
        if (bot_rate_limited(chat_id_j->valuestring)) {
            goto cleanup;
        }
    }

    if (filter_stale_message(msg)) {
        goto cleanup;
    }

    if (!cJSON_IsString(chat_id_j)) {
        goto cleanup;
    }

    if (!cJSON_IsString(content_j) && strcmp(msg_type, "image") != 0) {
        goto cleanup;
    }

    bool is_text = (strcmp(msg_type, "text") == 0);
    bool is_post = (strcmp(msg_type, "post") == 0);
    bool is_image = (strcmp(msg_type, "image") == 0);

    if (!is_text && !is_post && !is_image) {
        syslog(LOG_DEBUG, "[%s] Unsupported msg_type=%s, skipping\n", TAG, msg_type);
        goto cleanup;
    }

    if (is_image) {
        handle_image_message(msg, chat_id_j->valuestring, content_j);
        goto cleanup;
    }

    /* Text/Post message handling */
    {
        char post_image_key[128] = { 0 };
        cJSON* cj = cJSON_Parse(content_j->valuestring);

        if (!cj) {
            syslog(LOG_WARNING, "[%s] content JSON parse failed, dropping\n", TAG);
            goto cleanup;
        }

        if (is_post) {
            text = extract_post_text(cj, post_image_key, sizeof(post_image_key));
        } else {
            cJSON* ti = cJSON_GetObjectItem(cj, "text");
            if (cJSON_IsString(ti)) {
                text = strdup(ti->valuestring);
            }
        }
        cJSON_Delete(cj);

        if (post_image_key[0] && text) {
            download_post_image(post_image_key, msg, &text);
        }

        if (!text || !text[0]) {
            free(text);
            text = NULL;
            goto cleanup;
        }

        char* trimmed = trim_unicode_whitespace(text);
        if (!*trimmed) {
            syslog(LOG_DEBUG, "[%s] Empty text after trim, skipping\n", TAG);
            free(text);
            text = NULL;
            goto cleanup;
        }
        if (trimmed != text) {
            memmove(text, trimmed, strlen(trimmed) + 1);
        }

        if (!validate_text_content(text)) {
            free(text);
            text = NULL;
            goto cleanup;
        }

        if (process_group_mentions(msg, &text)) {
            text = NULL;
            goto cleanup;
        }

        cJSON* msg_id_j = cJSON_GetObjectItem(msg, "message_id");
        if (cJSON_IsString(msg_id_j) && msgid_dedup_check(msg_id_j->valuestring)) {
            syslog(LOG_WARNING, "[%s] Duplicate message_id %s, skipping\n",
                TAG, msg_id_j->valuestring);
            free(text);
            text = NULL;
            goto cleanup;
        }

        if (!post_image_key[0] && content_dedup_check(chat_id_j->valuestring, text)) {
            free(text);
            text = NULL;
            goto cleanup;
        }

        /* Final empty check */
        {
            const char* p = text;
            while (*p && ((unsigned char)*p <= 0x20)) {
                p++;
            }
            if (!*p) {
                syslog(LOG_WARNING, "[%s] Final check: empty content, dropping\n", TAG);
                free(text);
                text = NULL;
                goto cleanup;
            }
        }

        syslog(LOG_INFO, "[%s] MSG from [%.24s] len=%zu\n", TAG,
            chat_id_j->valuestring, strlen(text));

        agent_msg_t m = { 0 };
        strncpy(m.channel, AGENT_CHAN_FEISHU, sizeof(m.channel) - 1);
        strncpy(m.chat_id, chat_id_j->valuestring, sizeof(m.chat_id) - 1);
        m.content = text;
        message_bus_push_inbound(&m);
        text = NULL; /* ownership transferred */
    }

cleanup:
    free(text);
    free(payload_str);
    cJSON_Delete(root);
