 64	 *
 65	 * Description:
 66	 *   pause task execution on the CPU
 67	 *   check whether there are tasks delivered to specified cpu
 68	 *   and try to run them.
 69	 *
 70	 * Input Parameters:
 71	 *   cpu - The index of the CPU to be paused.
 72	 *
 73	 * Returned Value:
 74	 *   Zero on success; a negated errno value on failure.
 75	 *
 76	 * Assumptions:
 77	 *   Called from within a critical section;
 78	 *
 79	 ****************************************************************************/
 80	
 81	int up_send_smp_sched(int cpu)
 82	{
 83	  /* Execute the intercpu interrupt */
 84	
 85	  xtensa_intercpu_interrupt(cpu, CPU_INTCODE_PAUSE);
 86	
 87	  return OK;
 88	}
 89	
 90	/****************************************************************************
 91	 * Name: up_send_smp_call
 92	 *
 93	 * Description:
 94	 *   Send smp call to target cpu.
 95	 *
 96	 * Input Parameters:
 97	 *   cpuset - The set of CPUs to receive the SGI.
 98	 *
 99	 * Returned Value:
100	 *   None.
101	 *
102	 ****************************************************************************/
103	
104	void up_send_smp_call(cpu_set_t cpuset)
105	{
106	  int cpu;
107	
108	  for (; cpuset != 0; cpuset &= ~(1 << cpu))
109	    {
110	      cpu = ffs(cpuset) - 1;
111	      up_send_smp_sched(cpu);
112	    }
113	}
