    58	/****************************************************************************
    59	 * Name: setup_smartfs
    60	 *
    61	 * Description:
    62	 *   Provide a block driver wrapper around MTD partition and mount a
    63	 *   SMART FS over it.
    64	 *
    65	 * Parameters:
    66	 *   smartn - Number used to register the mtd partition: /dev/smartx, where
    67	 *            x = smartn.
    68	 *   mtd    - Pointer to a pre-allocated mtd partition.
    69	 *   mnt_pt - Mount point
    70	 *
    71	 * Returned Value:
    72	 *   Zero on success; a negated errno value on failure.
    73	 *
    74	 ****************************************************************************/
    75	
    76	#if defined (CONFIG_ESP32S3_SPIFLASH_SMARTFS)
    77	static int setup_smartfs(int smartn, struct mtd_dev_s *mtd,
    78	                         const char *mnt_pt)
    79	{
    80	  int ret = OK;
    81	  char path[22];
    82	
    83	  ret = smart_initialize(smartn, mtd, NULL);
    84	  if (ret < 0)
    85	    {
    86	      syslog(LOG_INFO, "smart_initialize failed, "
    87	             "Trying to erase first...\n");
    88	      ret = mtd->ioctl(mtd, MTDIOC_BULKERASE, 0);
    89	      if (ret < 0)
    90	        {
    91	          syslog(LOG_ERR, "ERROR: ioctl(BULKERASE) failed: %d\n", ret);
    92	          return ret;
    93	        }
    94	
    95	      syslog(LOG_INFO, "Erase successful, initializing it again.\n");
    96	      ret = smart_initialize(smartn, mtd, NULL);
    97	      if (ret < 0)
    98	        {
    99	          syslog(LOG_ERR, "ERROR: smart_initialize failed: %d\n", ret);
   100	          return ret;
   101	        }
   102	    }
   103	
   104	  if (mnt_pt != NULL)
   105	    {
   106	      snprintf(path, sizeof(path), "/dev/smart%d", smartn);
   107	
   108	      ret = nx_mount(path, mnt_pt, "smartfs", 0, NULL);
   109	      if (ret < 0)
   110	        {
   111	          syslog(LOG_ERR, "ERROR: Failed to mount the FS volume: %d\n", ret);
   112	          if (ret == -ENODEV)
   113	            {
   114	              syslog(LOG_WARNING, "Smartfs seems unformatted. "
   115	                     "Did you run 'mksmartfs /dev/smart%d'?\n", smartn);
   116	            }
   117	
   118	          return ret;
   119	        }
   120	    }
   121	
   122	  return ret;
   123	}
   124	
   125	#endif
