  1071	/****************************************************************************
  1072	 * Name: esp32s3_spiflash_alloc_mtdpart
  1073	 *
  1074	 * Description:
  1075	 *   Allocate an MTD partition from the ESP32-S3 SPI Flash.
  1076	 *
  1077	 * Input Parameters:
  1078	 *   mtd_offset - MTD Partition offset from the base address in SPI Flash.
  1079	 *   mtd_size   - Size for the MTD partition.
  1080	 *   encrypted  - Flag indicating whether the newly allocated partition will
  1081	 *                have its content encrypted.
  1082	 *
  1083	 * Returned Value:
  1084	 *   ESP32-S3 SPI Flash MTD data pointer if success or NULL if fail.
  1085	 *
  1086	 ****************************************************************************/
  1087	
  1088	struct mtd_dev_s *esp32s3_spiflash_alloc_mtdpart(uint32_t mtd_offset,
  1089	                                                 uint32_t mtd_size,
  1090	                                                 bool encrypted)
  1091	{
  1092	  const struct esp32s3_mtd_dev_s *priv;
  1093	  const esp_rom_spiflash_chip_t *chip;
  1094	  struct mtd_dev_s *mtd_part;
  1095	  uint32_t blocks;
  1096	  uint32_t startblock;
  1097	  uint32_t size;
  1098	
  1099	  if (encrypted)
  1100	    {
  1101	      priv = &g_esp32s3_spiflash_encrypt;
  1102	    }
  1103	  else
  1104	    {
  1105	      priv = &g_esp32s3_spiflash;
  1106	    }
  1107	
  1108	  chip = &(*priv->data)->chip;
  1109	
  1110	  finfo("ESP32-S3 SPI Flash information:\n");
  1111	  finfo("\tID = 0x%" PRIx32 "\n", chip->device_id);
  1112	  finfo("\tStatus mask = 0x%" PRIx32 "\n", chip->status_mask);
  1113	  finfo("\tChip size = %" PRId32 " KB\n", chip->chip_size / 1024);
  1114	  finfo("\tPage size = %" PRId32 " B\n", chip->page_size);
  1115	  finfo("\tSector size = %" PRId32 " KB\n", chip->sector_size / 1024);
  1116	  finfo("\tBlock size = %" PRId32 " KB\n", chip->block_size / 1024);
  1117	
  1118	  ASSERT((mtd_offset + mtd_size) <= chip->chip_size);
  1119	  ASSERT((mtd_offset % chip->sector_size) == 0);
  1120	  ASSERT((mtd_size % chip->sector_size) == 0);
  1121	
  1122	  if (mtd_size == 0)
  1123	    {
  1124	      size = chip->chip_size - mtd_offset;
  1125	    }
  1126	  else
  1127	    {
  1128	      size = mtd_size;
  1129	    }
  1130	
  1131	  finfo("\tMTD offset = 0x%" PRIx32 "\n", mtd_offset);
  1132	  finfo("\tMTD size = 0x%" PRIx32 "\n", size);
  1133	
  1134	  startblock = MTD_SIZE2BLK(priv, mtd_offset);
  1135	  blocks = MTD_SIZE2BLK(priv, size);
  1136	
  1137	  mtd_part = mtd_partition((struct mtd_dev_s *)&priv->mtd, startblock,
  1138	                           blocks);
  1139	  if (!mtd_part)
  1140	    {
  1141	      ferr("ERROR: Failed to create MTD partition\n");
  1142	      return NULL;
  1143	    }
  1144	
  1145	  return mtd_part;
  1146	}
