+/****************************************************************************
+ * board/contest_board/src/contest_storage.c
+ *
+ * SPDX-License-Identifier: Apache-2.0
+ ****************************************************************************/
+
+#include <nuttx/config.h>
+
+#ifdef CONFIG_CONTEST_BOARD_PERSISTENT_DATA
+
+#include <sys/mount.h>
+
+#include <errno.h>
+#include <stdbool.h>
+#include <stdint.h>
+#include <syslog.h>
+
+#include <nuttx/fs/fs.h>
+#include <nuttx/kmalloc.h>
+#include <nuttx/mtd/mtd.h>
+
+#include "esp32s3_spiflash.h"
+#include "esp32s3_spiflash_mtd.h"
+
+#define CONTEST_DATA_MTD_PATH "/dev/contest_data"
+#define CONTEST_DATA_MOUNTPT "/data"
+#define CONTEST_DATA_PROBE_SIZE 4096
+#define CONTEST_DATA_PROBE_BLOCKS 2
+
+static bool contest_data_is_erased(FAR struct mtd_dev_s *mtd)
+{
+  FAR uint8_t *buffer;
+  size_t block;
+  bool erased = true;
+
+  buffer = kmm_malloc(CONTEST_DATA_PROBE_SIZE);
+  if (buffer == NULL)
+    {
+      return false;
+    }
+
+  for (block = 0; block < CONTEST_DATA_PROBE_BLOCKS && erased; block++)
+    {
+      ssize_t nread;
+      size_t index;
+
+      nread = mtd->read(mtd, block * CONTEST_DATA_PROBE_SIZE,
+                        CONTEST_DATA_PROBE_SIZE, buffer);
+      if (nread != CONTEST_DATA_PROBE_SIZE)
+        {
+          erased = false;
+          break;
+        }
+
+      for (index = 0; index < CONTEST_DATA_PROBE_SIZE; index++)
+        {
+          if (buffer[index] != 0xff)
+            {
+              erased = false;
+              break;
+            }
+        }
+    }
+
+  kmm_free(buffer);
+  return erased;
+}
+
+int contest_persistent_data_initialize(void)
+{
+  FAR struct mtd_dev_s *mtd;
+  int ret;
+
+  ret = esp32s3_spiflash_init();
+  if (ret < 0)
+    {
+      syslog(LOG_ERR, "ERROR: SPI flash init failed: %d\n", ret);
+      return ret;
+    }
+
+  mtd = esp32s3_spiflash_alloc_mtdpart(CONFIG_ESP32S3_STORAGE_MTD_OFFSET,
+                                       CONFIG_ESP32S3_STORAGE_MTD_SIZE,
+                                       false);
+  if (mtd == NULL)
+    {
+      syslog(LOG_ERR, "ERROR: persistent MTD allocation failed\n");
+      return -ENODEV;
+    }
+
+  ret = register_mtddriver(CONTEST_DATA_MTD_PATH, mtd, 0700, NULL);
+  if (ret < 0)
+    {
+      syslog(LOG_ERR, "ERROR: persistent MTD registration failed: %d\n",
+             ret);
+      return ret;
+    }
+
+  ret = nx_mount(CONTEST_DATA_MTD_PATH, CONTEST_DATA_MOUNTPT, "littlefs", 0,
+                 NULL);
+  if (ret >= 0)
+    {
+      syslog(LOG_INFO, "Persistent data mounted at %s\n",
+             CONTEST_DATA_MOUNTPT);
+      return 0;
+    }
+
+  if (!contest_data_is_erased(mtd))
+    {
+      syslog(LOG_ERR,
+             "ERROR: persistent LittleFS mount failed on non-erased data\n");
+      return ret;
+    }
+
+  syslog(LOG_WARNING, "Persistent data is erased; formatting once\n");
+  ret = nx_mount(CONTEST_DATA_MTD_PATH, CONTEST_DATA_MOUNTPT, "littlefs", 0,
+                 "forceformat");
+  if (ret < 0)
+    {
+      syslog(LOG_ERR, "ERROR: persistent LittleFS format/mount failed: %d\n",
+             ret);
+      return ret;
+    }
+
+  syslog(LOG_INFO, "Persistent data formatted and mounted at %s\n",
+         CONTEST_DATA_MOUNTPT);
+  return 0;
+}
+
+#endif /* CONFIG_CONTEST_BOARD_PERSISTENT_DATA */
