int contest_board_bringup(void)
{
  int ret = 0;

#ifdef CONFIG_CONTEST_BOARD_PERSISTENT_DATA
  ret = contest_persistent_data_initialize();
  if (ret < 0)
    {
      syslog(LOG_ERR,
             "PERSISTENT DATA FAILED - USING VOLATILE TMPFS (%d)\n", ret);
      ret = nx_mount(NULL, "/data", "tmpfs", 0, NULL);
      if (ret < 0 && ret != -EBUSY)
        {
          syslog(LOG_ERR, "ERROR: Failed to mount /data tmpfs: %d\n", ret);
        }
    }
#elif defined(CONFIG_EXAMPLES_AI_AGENT_VELA)
  ret = nx_mount(NULL, "/data", "tmpfs", 0, NULL);
  if (ret < 0 && ret != -EBUSY)
    {
      syslog(LOG_WARNING, "WARNING: Failed to mount /data tmpfs: %d\n", ret);
    }
#endif

  ret = 0;

