   322	/* Direct path via vela_tls */
   323	static int llm_http_direct(const char* post_data, resp_buf_t* rb,
   324	    int* out_status)
   325	{
   326	    /* Snapshot config under lock */
   327	    char api_key[128], llm_host[128], llm_path[128], llm_port[8], model[64];
   328	    pthread_mutex_lock(&s_llm_lock);
   329	    memcpy(api_key, s_api_key, sizeof(api_key));
   330	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
   331	    memcpy(llm_path, s_llm_path, sizeof(llm_path));
   332	    memcpy(llm_port, s_llm_port, sizeof(llm_port));
   333	    memcpy(model, s_model, sizeof(model));
   334	    pthread_mutex_unlock(&s_llm_lock);
   335	
   336	    /* Allocate the response buffer once and hand it directly to the
   337	     * TLS layer.  Previously we allocated a separate raw_buf and then
   338	     * copied into resp_buf — doubling peak memory usage.  Now the
   339	     * resp_buf IS the raw buffer, eliminating the copy. */
   340	    size_t raw_cap = AGENT_LLM_STREAM_BUF_SIZE;
   341	    if (resp_buf_init(rb, raw_cap) != OK)
   342	        return ERROR;
   343	
   344	    /* OpenAI-compatible format: Authorization: Bearer <key> */
   345	    char auth_header[256];
   346	    snprintf(auth_header, sizeof(auth_header), "Bearer %s", api_key);
   347	
   348	    /* Extract provider ID from model string (e.g. "xiaomi/mimo-claw-0301" →
   349	     * "xiaomi") Mify gateway requires X-Model-Provider-Id header for routing. */
   350	    char provider[64] = { 0 };
   351	    const char* slash = strchr(model, '/');
   352	    if (slash) {
   353	        size_t plen = (size_t)(slash - model);
   354	        if (plen >= sizeof(provider))
   355	            plen = sizeof(provider) - 1;
   356	        memcpy(provider, model, plen);
   357	    }
   358	
   359	    vela_header_t hdrs[] = { { "Authorization", auth_header },
   360	        { provider[0] ? "X-Model-Provider-Id" : NULL,
   361	            provider[0] ? provider : NULL },
   362	        { NULL, NULL } };
   363	
   364	    int status;
   365	    int use_tls = (strcmp(llm_port, "443") == 0);
   366	
   367	    if (use_tls) {
   368	        status = vela_https_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
   369	            rb->data, raw_cap);
   370	    } else {
   371	        status = vela_http_post_json(llm_host, llm_port, llm_path, hdrs, post_data,
   372	            rb->data, raw_cap);
   373	    }
   374	
   375	    if (status < 0) {
   376	        resp_buf_free(rb);
   377	        return ERROR;
   378	    }
   379	
   380	    /* Update length — TLS layer NUL-terminated the buffer */
   381	    rb->len = strlen(rb->data);
   382	
   383	    *out_status = status;
   384	    return OK;
   385	}
