   387	/* Proxy path via CONNECT tunnel */
   388	static int llm_http_via_proxy(const char* post_data, resp_buf_t* rb,
   389	    int* out_status)
   390	{
   391	    /* Snapshot config under lock */
   392	    char api_key[128], llm_host[128], llm_path[128], llm_port[8], model[64];
   393	    pthread_mutex_lock(&s_llm_lock);
   394	    memcpy(api_key, s_api_key, sizeof(api_key));
   395	    memcpy(llm_host, s_llm_host, sizeof(llm_host));
   396	    memcpy(llm_path, s_llm_path, sizeof(llm_path));
   397	    memcpy(llm_port, s_llm_port, sizeof(llm_port));
   398	    memcpy(model, s_model, sizeof(model));
   399	    pthread_mutex_unlock(&s_llm_lock);
   400	
   401	    int port = atoi(llm_port);
   402	    if (port <= 0)
   403	        port = 443;
   404	
   405	    proxy_conn_t* conn = proxy_conn_open(llm_host, port, 30000);
   406	    if (!conn)
   407	        return ERROR;
   408	
   409	    int body_len = (int)strlen(post_data);
   410	    char auth_header[256];
   411	    snprintf(auth_header, sizeof(auth_header), "Bearer %s", api_key);
   412	
   413	    /* Extract provider ID from model (e.g. "xiaomi/mimo-claw-0301" → "xiaomi") */
   414	    char provider_hdr[128] = { 0 };
   415	    const char* slash = strchr(model, '/');
   416	    if (slash) {
   417	        char provider[64] = { 0 };
   418	        size_t plen = (size_t)(slash - model);
   419	        if (plen >= sizeof(provider))
   420	            plen = sizeof(provider) - 1;
   421	        memcpy(provider, model, plen);
   422	        snprintf(provider_hdr, sizeof(provider_hdr), "X-Model-Provider-Id: %s\r\n",
   423	            provider);
   424	    }
   425	
   426	    char header[1024];
   427	    int hlen = snprintf(header, sizeof(header),
   428	        "POST %s HTTP/1.1\r\n"
   429	        "Host: %s\r\n"
   430	        "Content-Type: application/json\r\n"
   431	        "Authorization: %s\r\n"
   432	        "%s"
   433	        "Content-Length: %d\r\n"
   434	        "Connection: close\r\n\r\n",
   435	        llm_path, llm_host, auth_header, provider_hdr, body_len);
   436	
   437	    if (proxy_conn_write(conn, header, hlen) < 0 || proxy_conn_write(conn, post_data, body_len) < 0) {
   438	        proxy_conn_close(conn);
   439	        return ERROR;
   440	    }
   441	
   442	    if (resp_buf_init(rb, AGENT_LLM_STREAM_BUF_SIZE) != OK) {
   443	        proxy_conn_close(conn);
   444	        return ERROR;
   445	    }
   446	
   447	    char tmp[4096];
   448	    while (1) {
   449	        int n = proxy_conn_read(conn, tmp, sizeof(tmp), 120000);
   450	        if (n <= 0)
   451	            break;
   452	        if (resp_buf_append(rb, tmp, (size_t)n) != OK) {
   453	            syslog(LOG_ERR, "[%s] resp_buf_append OOM, truncating\n", TAG);
   454	            break;
   455	        }
   456	    }
   457	    proxy_conn_close(conn);
   458	
   459	    /* Parse status from raw HTTP response */
   460	    *out_status = 0;
   461	    if (rb->len > 5 && strncmp(rb->data, "HTTP/", 5) == 0) {
   462	        const char* sp = strchr(rb->data, ' ');
   463	        if (sp)
   464	            *out_status = atoi(sp + 1);
   465	    }
   466	
   467	    /* Strip HTTP header, keep body */
   468	    char* body = strstr(rb->data, "\r\n\r\n");
   469	    if (body) {
   470	        body += 4;
   471	        size_t blen = rb->len - (size_t)(body - rb->data);
   472	        memmove(rb->data, body, blen);
   473	        rb->len = blen;
   474	        rb->data[rb->len] = '\0';
   475	    }
   476	
   477	    return OK;
   478	}
