   546	/* Extract text from OpenAI response format: choices[0].message.content */
   547	void extract_text(cJSON* root, char* buf, size_t size)
   548	{
   549	    buf[0] = '\0';
   550	    cJSON* choices = cJSON_GetObjectItem(root, "choices");
