   300	            sizeof(g_net_config.rpmsg_cpu))
   301	            != OK
   302	        || g_net_config.rpmsg_cpu[0] == '\0') {
   303	        strncpy(g_net_config.rpmsg_cpu, "ap",
   304	            sizeof(g_net_config.rpmsg_cpu) - 1);
   305	        g_net_config.rpmsg_cpu[sizeof(g_net_config.rpmsg_cpu) - 1] = '\0';
   306	    }
   307	
   308	    /* connect_timeout: default 15 */
   309	    if (claw_config_get("net.connect_timeout", buf, sizeof(buf)) == OK
   310	        && buf[0] != '\0') {
   311	        g_net_config.connect_timeout = atoi(buf);
   312	    } else {
   313	        g_net_config.connect_timeout = 15;
   314	    }
   315	
   316	    /* read_timeout: default 30 */
   317	    memset(buf, 0, sizeof(buf));
   318	    if (claw_config_get("net.read_timeout", buf, sizeof(buf)) == OK
   319	        && buf[0] != '\0') {
   320	        g_net_config.read_timeout = atoi(buf);
   321	    } else {
   322	        g_net_config.read_timeout = 30;
   323	    }
   324	
   325	    /* retry_max: default 3 */
   326	    memset(buf, 0, sizeof(buf));
   327	    if (claw_config_get("net.retry_max", buf, sizeof(buf)) == OK
   328	        && buf[0] != '\0') {
   329	        g_net_config.retry_max = atoi(buf);
   330	    } else {
   331	        g_net_config.retry_max = 3;
   332	    }
   333	
   334	    /* retry_base_sec: default 2 */
   335	    memset(buf, 0, sizeof(buf));
   336	    if (claw_config_get("net.retry_base_sec", buf, sizeof(buf)) == OK
   337	        && buf[0] != '\0') {
   338	        g_net_config.retry_base_sec = atoi(buf);
   339	    } else {
   340	        g_net_config.retry_base_sec = 2;
   340	        g_net_config.retry_base_sec = 2;
   341	    }
   342	
   343	    syslog(LOG_INFO,
   344	        "[%s] Config loaded: proxy=%s cpu=%s timeout=%d/%d retry=%d base=%d\n",
   345	        TAG, g_net_config.proxy_mode, g_net_config.rpmsg_cpu,
   346	        g_net_config.connect_timeout, g_net_config.read_timeout,
   347	        g_net_config.retry_max, g_net_config.retry_base_sec);
