   470	int network_register_listener(net_state_cb_t cb, void* arg)
   471	{
   472	    if (!cb) {
   473	        return -EINVAL;
   474	    }
   475	
   476	    pthread_mutex_lock(&g_net_mutex);
   477	    if (g_listener_count >= NET_MAX_LISTENERS) {
   478	        pthread_mutex_unlock(&g_net_mutex);
   479	        syslog(LOG_ERR, "[%s] Max listeners (%d) reached\n",
   480	            TAG, NET_MAX_LISTENERS);
   481	        return -ENOMEM;
   482	    }
   483	
   484	    g_listeners[g_listener_count].cb = cb;
   485	    g_listeners[g_listener_count].arg = arg;
   486	    g_listener_count++;
   487	    pthread_mutex_unlock(&g_net_mutex);
   488	
   489	    return OK;
   490	}
