 122	/* ── WS handshake ─────────────────────────────────────────────── */
 123	
 124	/**
 125	 * Compute Sec-WebSocket-Accept = base64(SHA1(key + GUID))
 126	 */
 127	static int make_accept_key(const char* key, char* out, size_t out_size)
 128	{
 129	    char combined[256];
 130	    int clen = snprintf(combined, sizeof(combined), "%s%s", key, WS_GUID);
 131	    if (clen <= 0 || clen >= (int)sizeof(combined))
 132	        return -1;
 133	
 134	    unsigned char sha[20];
 135	    if (mbedtls_sha1((const unsigned char*)combined, (size_t)clen, sha) != 0)
 136	        return -1;
 137	
 138	    size_t written = 0;
 139	    if (mbedtls_base64_encode((unsigned char*)out, out_size, &written, sha,
 140	            sizeof(sha))
 141	        != 0)
 142	        return -1;
 143	    out[written] = '\0';
 144	    return (int)written;
 145	}
 146	
 147	/**
 148	 * WebSocket handshake using pre-read buffer.
 149	 * Read full HTTP upgrade request, extract Sec-WebSocket-Key.
 150	 * Returns 0 on success; sends 101 response.
 151	 */
 152	static int do_ws_handshake_ex(int fd, const char* buf, int buf_len,
 153	    char* chat_id_out, size_t chat_id_size)
 154	{
 155	
 156	    /* Extract Sec-WebSocket-Key */
 157	    char* key_hdr = strcasestr(buf, "\r\nSec-WebSocket-Key: ");
 158	    if (!key_hdr) {
 159	        syslog(LOG_WARNING, "[%s] No Sec-WebSocket-Key\n", TAG);
 160	        return -1;
 161	    }
 162	    key_hdr += 21;
 163	    char* eol = strstr(key_hdr, "\r\n");
 164	    if (!eol)
 165	        return -1;
 166	
 167	    char ws_key[128] = { 0 };
 168	    size_t klen = (size_t)(eol - key_hdr);
 169	    if (klen >= sizeof(ws_key))
 170	        return -1;
 171	    memcpy(ws_key, key_hdr, klen);
 172	    ws_key[klen] = '\0';
 173	
 174	    /* Compute accept */
 175	    char accept[64] = { 0 };
 176	    if (make_accept_key(ws_key, accept, sizeof(accept)) < 0)
 177	        return -1;
 178	
 179	    /* Send 101 */
 180	    char resp[512];
 181	    int rlen = snprintf(resp, sizeof(resp),
 182	        "HTTP/1.1 101 Switching Protocols\r\n"
 183	        "Upgrade: websocket\r\n"
 184	        "Connection: Upgrade\r\n"
 185	        "Sec-WebSocket-Accept: %s\r\n\r\n",
 186	        accept);
 187	    if (send(fd, resp, rlen, 0) != rlen)
 188	        return -1;
 189	
 190	    /* Default chat_id from fd (may be overridden by first message) */
 191	    snprintf(chat_id_out, chat_id_size, "ws_%d", fd);
 192	    return 0;
 193	}
