 195	/* ── WS frame encode/decode ───────────────────────────────────── */
 196	
 197	/**
 198	 * Send a text frame (server → client, no masking).
 199	 * Caller must hold s_clients_mtx.
 200	 */
 201	static int ws_send_frame(int fd, const char* payload, size_t len)
 202	{
 203	    unsigned char hdr[10];
 204	    int hdr_len = 0;
 205	
 206	    hdr[0] = 0x81; /* FIN + text opcode */
 207	    if (len < 126) {
 208	        hdr[1] = (unsigned char)len;
 209	        hdr_len = 2;
 210	    } else if (len < 65536) {
 211	        hdr[1] = 126;
 212	        hdr[2] = (unsigned char)(len >> 8);
 213	        hdr[3] = (unsigned char)(len & 0xFF);
 214	        hdr_len = 4;
 215	    } else {
 216	        syslog(LOG_ERR, "[%s] Payload too large: %d\n", TAG, (int)len);
 217	        return -1;
 218	    }
 219	
 220	    if (send(fd, hdr, hdr_len, 0) != hdr_len)
 221	        return -1;
 222	    if (send(fd, payload, len, 0) != (int)len)
 223	        return -1;
 224	    return 0;
 225	}
 226	
 227	/**
 228	 * Read and decode one WS frame; place text payload into buf (NUL-terminated).
 229	 * Returns payload length on success, 0 on close frame, -1 on error.
 230	 */
 231	static int ws_recv_frame(int fd, char* buf, size_t buf_size)
 232	{
 233	    unsigned char b0, b1;
 234	    if (recv(fd, &b0, 1, MSG_WAITALL) != 1)
 235	        return -1;
 236	    if (recv(fd, &b1, 1, MSG_WAITALL) != 1)
 237	        return -1;
 238	
 239	    int opcode = b0 & 0x0F;
 240	    bool masked = (b1 & 0x80) != 0;
 241	    size_t plen = b1 & 0x7F;
 242	
 243	    if (opcode == 0x8)
 244	        return 0; /* Close frame */
 245	
 246	    if (opcode == 0x9 || opcode == 0xA) {
 247	        /* Ping (0x9) or Pong (0xA) — must consume payload before returning,
 248	         * otherwise leftover bytes corrupt the next frame read. */
 249	        if (plen == 126) {
 250	            unsigned char ext[2];
 251	            if (recv(fd, ext, 2, MSG_WAITALL) != 2)
 252	                return -1;
 253	            plen = ((size_t)ext[0] << 8) | ext[1];
 254	        } else if (plen == 127) {
 255	            return -1;
 256	        }
 257	
 258	        unsigned char pp_mask[4] = { 0 };
 259	        if (masked) {
 260	            if (recv(fd, pp_mask, 4, MSG_WAITALL) != 4)
 261	                return -1;
 262	        }
 263	
 264	        if (plen > 125) {
 265	            syslog(LOG_ERR,
 266	                "[%s] Invalid control frame payload length: %d\n",
 267	                TAG, (int)plen);
 268	            return -1;
 269	        }
 270	
 271	        /* Read full control payload so ping can be echoed in pong. */
 272	        unsigned char ctrl_payload[125] = { 0 };
 273	        if (plen > 0) {
 274	            if (recv(fd, ctrl_payload, plen, MSG_WAITALL) != (int)plen)
 275	                return -1;
 276	
 277	            if (masked) {
 278	                for (size_t i = 0; i < plen; i++) {
 279	                    ctrl_payload[i] ^= pp_mask[i % 4];
 280	                }
 281	            }
 282	        }
 283	
 284	        /* Reply with pong if it was a ping */
 285	        if (opcode == 0x9) {
 286	            unsigned char pong_hdr[2] = { 0x8A, (unsigned char)plen };
 287	            send(fd, pong_hdr, 2, 0);
 288	            if (plen > 0) {
 289	                send(fd, ctrl_payload, plen, 0);
 290	            }
 291	        }
 292	        return -2;
 293	    }
 294	
 295	    if (opcode != 0x1 && opcode != 0x2) {
 296	        /* Unknown opcode — skip */
 297	        return -2;
 298	    }
 299	
 300	    if (plen == 126) {
 300	    if (plen == 126) {
 301	        unsigned char ext[2];
 302	        if (recv(fd, ext, 2, MSG_WAITALL) != 2)
 303	            return -1;
 304	        plen = ((size_t)ext[0] << 8) | ext[1];
 305	    } else if (plen == 127) {
 306	        syslog(LOG_ERR, "[%s] 64-bit frame length not supported\n", TAG);
 307	        return -1;
 308	    }
 309	
 310	    unsigned char mask_key[4] = { 0 };
 311	    if (masked) {
 312	        if (recv(fd, mask_key, 4, MSG_WAITALL) != 4)
 313	            return -1;
 314	    }
 315	
 316	    if (plen >= buf_size) {
 317	        syslog(LOG_ERR, "[%s] Frame too large: %d\n", TAG, (int)plen);
 318	        return -1;
 319	    }
 320	
 321	    int received = 0;
 322	    while ((size_t)received < plen) {
 323	        int n = recv(fd, buf + received, plen - received, 0);
 324	        if (n <= 0)
 325	            return -1;
 326	        received += n;
 327	    }
 328	
 329	    if (masked) {
 330	        for (size_t i = 0; i < plen; i++) {
 331	            ((unsigned char*)buf)[i] ^= mask_key[i % 4];
 332	        }
 333	    }
 334	
 335	    buf[plen] = '\0';
 336	    return (int)plen;
 337	}
