 339	/* ── Per-client thread ────────────────────────────────────────── */
 340	
 341	typedef struct {
 342	    int fd;
 343	} client_arg_t;
 344	
 345	static void* client_thread(void* arg)
 346	{
 347	    client_arg_t ca = *(client_arg_t*)arg;
 348	    free(arg);
 349	    int fd = ca.fd;
 350	
 351	    /* Peek HTTP headers to decide: REST API or WebSocket */
 352	    char* peek_buf = malloc(2048);
 353	    if (!peek_buf) {
 354	        close(fd);
 355	        return NULL;
 356	    }
 357	    int peek_total = 0;
 358	    while (peek_total < 2048 - 1) {
 359	        int n = recv(fd, peek_buf + peek_total,
 360	            2048 - 1 - peek_total, 0);
 361	        if (n <= 0) {
 362	            free(peek_buf);
 363	            close(fd);
 364	            return NULL;
 365	        }
 366	        peek_total += n;
 367	        peek_buf[peek_total] = '\0';
 368	        if (strstr(peek_buf, "\r\n\r\n"))
 369	            break;
 370	    }
 371	
 372	    /* Try REST API (config/skills/logs) */
 373	#ifdef CONFIG_AI_AGENT_REST_API
 374	    if (api_try_handle(fd, peek_buf, peek_total)) {
 375	        free(peek_buf);
 376	        struct linger lg = { .l_onoff = 1, .l_linger = 0 };
 377	        setsockopt(fd, SOL_SOCKET, SO_LINGER, &lg, sizeof(lg));
 378	        close(fd);
 379	        return NULL;
 380	    }
 381	#endif
 382	
 383	    /* Not REST API - proceed with WebSocket handshake using pre-read buffer */
 384	    char chat_id[32];
 385	    if (do_ws_handshake_ex(fd, peek_buf, peek_total,
 386	            chat_id, sizeof(chat_id))
 387	        != 0) {
 388	        syslog(LOG_WARNING, "[%s] Handshake failed for fd=%d\n", TAG, fd);
 389	        free(peek_buf);
 390	        close(fd);
 391	        return NULL;
 392	    }
 393	    free(peek_buf);
 394	
 395	    /* Register client */
 396	    pthread_mutex_lock(&s_clients_mtx);
 397	    ws_client_t* client = add_client_locked(fd);
 398	    if (!client) {
 399	        pthread_mutex_unlock(&s_clients_mtx);
 400	        syslog(LOG_WARNING, "[%s] Max clients reached, closing fd=%d\n", TAG, fd);
 401	        /* Politely close */
 402	        unsigned char close_frame[2] = { 0x88, 0x00 };
 403	        send(fd, close_frame, 2, 0);
 404	        close(fd);
 405	        return NULL;
 406	    }
 407	    snprintf(client->chat_id, sizeof(client->chat_id), "%s", chat_id);
 408	    pthread_mutex_unlock(&s_clients_mtx);
 409	
 410	    /* Send connect.challenge so Nodes can identify themselves */
 411	#ifdef CONFIG_AI_AGENT_NODE
 412	    node_manager_send_challenge(fd);
 413	#endif
 414	
 415	    /* Read loop — stack-allocated so each client thread has its own buffer */
 416	    char frame_buf[4096];
 417	    while (s_running) {
 418	        int n = ws_recv_frame(fd, frame_buf, sizeof(frame_buf));
 419	        if (n < 0 && n != -2)
 420	            break; /* -2 = ignored opcode, not an error */
 421	        if (n == 0)
 422	            break; /* clean close */
 423	        if (n < 0)
 424	            continue; /* ignored frame */
 425	
 426	        /* Try Node protocol first — if handled, skip chat processing */
 427	#ifdef CONFIG_AI_AGENT_NODE
 428	        if (node_manager_handle_message(fd, frame_buf, n))
 429	            continue;
 430	#endif
 431	
 432	        /* Parse JSON message */
 433	        cJSON* root = cJSON_Parse(frame_buf);
 434	        if (!root) {
 435	            syslog(LOG_WARNING, "[%s] Invalid JSON from fd=%d (%d bytes): %.200s\n",
 436	                TAG, fd, n, frame_buf);
 437	            continue;
 438	        }
 439	
 440	        cJSON* type_item = cJSON_GetObjectItem(root, "type");
 441	        cJSON* content_item = cJSON_GetObjectItem(root, "content");
 442	
 443	        if (cJSON_IsString(type_item) && strcmp(type_item->valuestring, "message") == 0 && cJSON_IsString(content_item)) {
 444	
 445	            /* Determine/update chat_id */
 446	            cJSON* cid_item = cJSON_GetObjectItem(root, "chat_id");
 447	            pthread_mutex_lock(&s_clients_mtx);
 448	            ws_client_t* c = find_by_fd_locked(fd);
 449	            if (c) {
 450	                if (cJSON_IsString(cid_item)) {
