 483	/* ── Accept loop ──────────────────────────────────────────────── */
 484	
 485	static void* accept_thread(void* arg)
 486	{
 487	    (void)arg;
 488	    while (s_running) {
 489	        struct pollfd pfd = { .fd = s_listen_fd, .events = POLLIN };
 490	        int pr = poll(&pfd, 1, 500);
 491	        if (pr <= 0)
 492	            continue;
 493	
 494	        struct sockaddr_in addr;
 495	        socklen_t addr_len = sizeof(addr);
 496	        int cfd = accept(s_listen_fd, (struct sockaddr*)&addr, &addr_len);
 497	        if (cfd < 0)
 498	            continue;
 499	
 500	        client_arg_t* ca = malloc(sizeof(client_arg_t));
 501	        if (!ca) {
 502	            close(cfd);
 503	            continue;
 504	        }
 505	        ca->fd = cfd;
 506	
 507	        pthread_t tid;
 508	        pthread_attr_t attr;
 509	        pthread_attr_init(&attr);
 510	        pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
 511	        pthread_attr_setstacksize(&attr, AGENT_WS_CLIENT_STACK);
 512	        if (pthread_create(&tid, &attr, client_thread, ca) != 0) {
 513	            free(ca);
 514	            close(cfd);
 515	        }
 516	        pthread_attr_destroy(&attr);
 517	    }
 518	    return NULL;
 519	}
