 527	    s_listen_fd = socket(AF_INET, SOCK_STREAM, 0);
 528	    if (s_listen_fd < 0) {
 529	        syslog(LOG_ERR, "[%s] socket() failed\n", TAG);
 530	        return ERROR;
 531	    }
 532	
 533	    int opt = 1;
 534	    setsockopt(s_listen_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
 535	
 536	    struct sockaddr_in addr = {
 537	        .sin_family = AF_INET,
 538	        .sin_port = htons(AGENT_WS_PORT),
 539	        .sin_addr.s_addr = INADDR_ANY,
 540	    };
 541	
 542	    if (bind(s_listen_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
 543	        syslog(LOG_ERR, "[%s] bind() failed on port %d, errno=%d\n", TAG,
 544	            AGENT_WS_PORT, errno);
 545	        close(s_listen_fd);
 546	        s_listen_fd = -1;
 547	        return ERROR;
 548	    }
 549	
 550	    if (listen(s_listen_fd, AGENT_WS_MAX_CLIENTS) < 0) {
 551	        syslog(LOG_ERR, "[%s] listen() failed\n", TAG);
 552	        close(s_listen_fd);
 553	        s_listen_fd = -1;
 554	        return ERROR;
 555	    }
 556	
 557	    s_running = true;
 558	
 559	    pthread_t tid;
 560	    pthread_attr_t attr;
 561	    pthread_attr_init(&attr);
 562	    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
 563	    pthread_attr_setstacksize(&attr, AGENT_CLI_STACK);
 564	    int rc = pthread_create(&tid, &attr, accept_thread, NULL);
 565	    pthread_attr_destroy(&attr);
 566	
 567	    if (rc != 0) {
 568	        syslog(LOG_ERR, "[%s] Failed to create accept thread\n", TAG);
 569	        s_running = false;
 570	        close(s_listen_fd);
 571	        s_listen_fd = -1;
 572	        return ERROR;
 573	    }
