 585	    /* Build JSON response */
 586	    cJSON* resp = cJSON_CreateObject();
 587	    cJSON_AddStringToObject(resp, "type", "response");
 588	    cJSON_AddStringToObject(resp, "content", text);
 589	    cJSON_AddStringToObject(resp, "chat_id", chat_id);
