 595	    pthread_mutex_lock(&s_clients_mtx);
 596	    ws_client_t* client = find_by_chat_id_locked(chat_id);
 597	    int rc = -1;
 598	    if (client) {
 599	        rc = ws_send_frame(client->fd, json_str, strlen(json_str));
 600	        if (rc != 0) {
 601	            syslog(
 602	                LOG_WARNING,
 603	                "[%s] Send failed to %s (fd will be cleaned up by client thread)\n",
 604	                TAG, chat_id);
 605	            /* Don't remove/close here — the client_thread owns the fd lifecycle.
 606	             * The recv() in client_thread will fail and trigger cleanup. */
