        int status = vela_https_get(argv[2], "443", "/",
            resp, sizeof(resp));
        clock_gettime(CLOCK_MONOTONIC, &t1);
        long ms = (t1.tv_sec - t0.tv_sec) * 1000L
            + (t1.tv_nsec - t0.tv_nsec) / 1000000L;
        printf("Status: %d, Latency: %ldms\n", status, ms);
    } else {
