+        ret = pthread_cond_timedwait(&g_cli_ready_cond, &g_cli_ready_lock,
+                                     &deadline);
+      }
+    bool ready = g_cli_ready;
+    pthread_mutex_unlock(&g_cli_ready_lock);
+    return ready ? OK : (ret == ETIMEDOUT ? -ETIMEDOUT : -EIO);
+}
