n++    ret = ws_server_start();\\n++    if (ret != OK)\\n++      {\\n++        goto failed;\\n++      }\\n++\\n++    syslog(LOG_INFO, \\\"[AI-DOG-DIAG] agent_loop start\\\\n\\\");\\n++    ret = agent_loop_start();\\n++    if (ret != OK)\\n++      {\\n++        ws_server_stop();\\n++        goto failed;\\n++      }\\n++\\n+ #ifdef CONFIG_AI_AGENT_NODE\\n+-        node_client_start();\\n++    if (node_client_start() != OK)\\n++      {\\n++        syslog(LOG_WARNING, \\\"[%s] node_client_start failed\\\\n\\\", TAG);\\n++      }\\n+ #endif\\n+ #ifdef CONFIG_AI_AGENT_MQTT\\n+-        mqtt_channel_start();\\n++    if (mqtt_channel_start() != OK)\\n++      {\\n++        syslog(LOG_WARNING, \\\"[%s] mqtt_channel_start failed\\\\n\\\", TAG);\\n++      }\\n+ #endif\\n+ #ifdef CONFIG_AI_AGENT_WEIXIN\\n+-        weixin_channel_start();\\n+-#endif\\n+-        g_net_services_started = true;\\n++    if (weixin_channel_start() != OK)\\n++      {\\n++        syslog(LOG_WARNING, \\\"[%s] weixin_channel_start failed\\\\n\\\", TAG);\\n++      }\\n++#endif\\n++\\n++    pthread_mutex_lock(&g_net_services_lock);\\n++    g_net_services_state = NET_SERVICES_RUNNING;\\n++    pthread_mutex_unlock(&g_net_services_lock);\\n++    syslog(LOG_INFO, \\\"[%s] All network services started!\\\\n\\\", TAG);\\n++    return OK;\\n++\\n++failed:\\n++    pthread_mutex_lock(&g_net_services_lock);\\n++    g_net_services_state = NET_SERVICES_FAILED;\\n++    pthread_mutex_unlock(&g_net_services_lock);\\n++    syslog(LOG_WARNING, \\\"[%s] Network services failed: %d\\\\n\\\", TAG, ret);\\n++    return ret;\\n++}\\n++\\n++#ifdef CONFIG_AI_AGENT_NET_RPMSG\\n++static void net_state_change_cb(net_state_t state, void* arg)\\n++{\\n++    (void)arg;\\n++    if (state == NET_STATE_CONNECTED) {\\n++        syslog(LOG_INFO, \\\"[%s] Network recovered, starting services\\\\n\\\", TAG);\\n++        start_network_services_once();\\n+     } else if (state == NET_STATE_DISCONNECTED) {\\n+         syslog(LOG_WARNING,\\n+             \\\"[%s] Network lost, services may be affected\\\\n\\\", TAG);\\n+-        /* Services will handle disconnection via their own error paths.\\n+-         * We just log the event here. g_net_services_started stays true\\n+-         * so we don't re-start services that are already running. */\\n++        /* Services handle disconnection through their own error paths. */\\n+     }\\n+ }\\n+ #endif\\n+@@ -154,6 +237,7 @@\\n+ \\n+     if (network_wait_connected(30000) == OK) {\\n+         syslog(LOG_INFO, \\\"[%s] Network connected: %s\\\\n\\\", TAG, network_get_ip());\\n++        syslog(LOG_INFO, \\\"[AI-DOG-DIAG] network_connected\\\\n\\\");\\n+ \\n+ #if AGENT_SKILL_SYNC_ENABLED\\n+         /* Sync skills from Bitable before starting agent loop */\\n+@@ -162,32 +246,7 @@\\n+         }\\n+ #endif\\n+ \\n+-#ifdef CONFIG_AI_AGENT_FEISHU\\n+-        if (feishu_bot_start() != OK)\\n+-            syslog(LOG_WARNING, \\\"[%s] feishu_bot_start failed\\\\n\\\", TAG);\\n+-#endif\\n+-        if (agent_loop_start() != OK)\\n+-            syslog(LOG_WARNING, \\\"[%s] agent_loop_start failed\\\\n\\\", TAG);\\n+-        if (ws_server_start() != OK)\\n+-            syslog(LOG_WARNING, \\\"[%s] ws_server_start failed\\\\n\\\", TAG);\\n+-#ifdef CONFIG_AI_AGENT_NODE\\n+-        if (node_client_start() != OK)\\n+-            syslog(LOG_WARNING, \\\"[%s] node_client_start failed\\\\n\\\", TAG);\\n+-#endif\\n+-#ifdef CONFIG_AI_AGENT_MQTT\\n+-        if (mqtt_channel_start() != OK)\\n+-            syslog(LOG_WARNING, \\\"[%s] mqtt_channel_start failed\\\\n\\\", TAG);\\n+-#endif\\n+-#ifdef CONFIG_AI_AGENT_WEIXIN\\n+-        if (weixin_channel_start() != OK)\\n+-            syslog(LOG_WARNING, \\\"[%s] weixin_channel_start failed\\\\n\\\", TAG);\\n+-#endif\\n+-\\n+-        syslog(LOG_INFO, \\\"[%s] All network services started!\\\\n\\\", TAG);\\n+-\\n+-#ifdef CONFIG_AI_AGENT_NET_RPMSG\\n+-        g_net_services_started = true;\\n+-#endif\\n++        start_network_services_once();\\n+     } else {\\n+         syslog(LOG_WARNING, \\\"[%s] Network timeout — net services not started.\\\\n\\\", TAG);\\n+         syslog(LOG_WARNING, \\\"[%s] Use 'config_show' / 'set_*' CLI commands to configure.\\\\n\\\", TAG);\\n+@@ -603,6 +662,10 @@\\n+     {\\n+         int rc = nsh_commands_init();\\n+         BOOT_LOG_RC(&t0, \\\"P4\\\", \\\"nsh_commands_init\\\", rc);\\n++        pthread_mutex_lock(&g_net_services_lock);\\n++        g_core_ready = (rc == OK);\\n++        pthread_mutex_unlock(&g_net_services_lock);\\n++        syslog(LOG_INFO, \\\"[AI-DOG-DIAG] core_ready=%d\\\\n\\\", rc == OK);\\n+     }\\n+ \\n+     /* ── Phase 5: Network — async, does NOT block ready ────── */\\n+@@ -682,7 +745,16 @@\\n+     }\\n+ #endif\\n+ \\n+-    /* Network watcher thread: reconnect + wait + start net services */\\n++    /* ── Phase 6: CLI thread — complete before network services ── */\\n++    {\\n++        int rc = nsh_commands_start();\\n++        BOOT_LOG_RC(&t0, \\\"P6\\\", \\\"nsh_commands_start\\\", rc);\\n++        pthread_mutex_lock(&g_net_services_lock);\\n++        g_cli_ready = (rc == OK);\\n++        pthread_mutex_unlock(&g_net_services_lock);\\n++    }\\n++\\n++    /* Network watcher thread: reconnect + wait + start net services. */\\n+     if (agent_task_create(network_watch_task, \\\"net_watch\\\",\\n+             AGENT_OUTBOUND_STACK, NULL,\\n+             AGENT_OUTBOUND_PRIO)\\n+@@ -691,12 +763,6 @@\\n+     }\\n+     BOOT_LOG(&t0, \\\"P5\\\", \\\"network_watch thread started (async)\\\");\\n+ \\n+-    /* ── Phase 6: CLI thread — all services now in known state ── */\\n+-    {\\n+-        int rc = nsh_commands_start();\\n+-        BOOT_LOG_RC(&t0, \\\"P6\\\", \\\"nsh_commands_start\\\", rc);\\n+-    }\\n+-\\n+     syslog(LOG_INFO, \\\"[%s] [boot +%ldms] AI Agent ready. Type 'help' in NSH for commands.\\\\n\\\",\\n+         TAG, boot_ms(&t0));\\n+ \\n+diff --git a/packages/ai_agent/src/core/agent_loop.c b/packages/ai_agent/src/core/agent_loop.c\\n+--- a/packages/ai_agent/src/core/agent_loop.c\\n++++ b/packages/ai_agent/src/core/agent_loop.c\\n+@@ -1371,11 +1371,30 @@\\n+         messages = cJSON_CreateArray();\\n+     }\\n+ \\n++    if (!messages) {\\n++        return NULL;\\n++    }\\n++\\n+     cJSON* user_msg = cJSON_CreateObject();\\n+ \\n+-    cJSON_AddStringToObject(user_msg, \\\"role\\\", \\\"user\\\");\\n+-    cJSON_AddStringToObject(user_msg, \\\"content\\\", content);\\n+-    cJSON_AddItemToArray(messages, user_msg);\\n++    if (!user_msg) {\\n++        cJSON_Delete(messages);\\n++        return NULL;\\n++    }\\n++\\n++    if (!cJSON_AddStringToObject(user_msg, \\\"role\\\", \\\"user\\\") ||\\n++        !cJSON_AddStringToObject(user_msg, \\\"content\\\", content)) {\\n++        cJSON_Delete(user_msg);\\n++        cJSON_Delete(messages);\\n++        return NULL;\\n++    }\\n++\\n++    if (!cJSON_AddItemToArray(messages, user_msg)) {\\n++        cJSON_Delete(user_msg);\\n++        cJSON_Delete(messages);\\n++        return NULL;\\n++    }\\n++\\n+     return messages;\\n+ }\\n+ \\n+@@ -1535,13 +1554,33 @@\\n+         context_build_system_prompt(sys_prompt, ctx_size);\\n+         inject_session_context(sys_prompt, ctx_size,\\n+             msg.channel, msg.chat_id);\\n++        syslog(LOG_INFO, \\\"[AI-DOG-DIAG] ask stage=prompt\\\\n\\\");\\n+ \\n+         /* Refresh tools JSON — Node tools are dynamic */\\n+         free(tools_json);\\n+         tools_json = tool_registry_get_tools_json();\\n++        if (!tools_json) {\\n++            syslog(LOG_ERR, \\\"[AI-DOG-DIAG] ask tools JSON allocation failed\\\\n\\\");\\n++            dispatch_response(&msg,\\n++                strdup(\\\"Unable to prepare the tool registry.\\\"));\\n++            free(msg.image_b64);\\n++            free(msg.content);\\n++            continue;\\n++        }\\n++        syslog(LOG_INFO, \\\"[AI-DOG-DIAG] ask stage=tools bytes=%d\\\\n\\\",\\n++            (int)strlen(tools_json));\\n+ \\n+         cJSON* messages = build_messages(msg.chat_id, msg.content,\\n+             history_json, hist_size);\\n++        if (!messages) {\\n++            syslog(LOG_ERR, \\\"[AI-DOG-DIAG] ask message JSON allocation failed\\\\n\\\");\\n++            dispatch_response(&msg,\\n++                strdup(\\\"Unable to prepare the request.\\\"));\\n++            free(msg.image_b64);\\n++            free(msg.content);\\n++            continue;\\n++        }\\n++        syslog(LOG_INFO, \\\"[AI-DOG-DIAG] ask stage=messages\\\\n\\\");\\n+ \\n+         char* final_text = NULL;\\n+ \\n+@@ -1552,6 +1591,7 @@\\n+         } else {\\n+             /* ReAct loop */\\n+             s_llm_path_count++;\\n++            syslog(LOG_INFO, \\\"[AI-DOG-DIAG] ask stage=react\\\\n\\\");\\n+             final_text = run_react_loop(sys_prompt, messages,\\n+                 tools_json, tool_output, tool_size, &msg);\\n+             cJSON_Delete(messages);\\n+diff --git a/packages/ai_agent/src/llm/llm_proxy.c b/packages/ai_agent/src/llm/llm_proxy.c\\n+--- a/packages/ai_agent/src/llm/llm_proxy.c\\n++++ b/packages/ai_agent/src/llm/llm_proxy.c\\n+@@ -703,9 +703,16 @@\\n+     }\\n+ \\n+     cJSON* body = cJSON_CreateObject();\\n++    if (!body) {\\n++        syslog(LOG_ERR, \\\"[AI-DOG-DIAG] llm request body allocation failed\\\\n\\\");\\n++        return ERROR;\\n++    }\\n+ \\n+-    cJSON_AddStringToObject(body, \\\"model\\\",\\n+-        model_name_for_api(model, llm_host));\\n++    if (!cJSON_AddStringToObject(body, \\\"model\\\",\\n++        model_name_for_api(model, llm_host))) {\\n++        cJSON_Delete(body);\\n++        return ERROR;\\n++    }\\n+ \\n+     if (is_openai_compat_host(llm_host)) {\\n+         cJSON_AddNumberToObject(body, \\\"max_completion_tokens\\\",\\n+@@ -719,10 +726,28 @@\\n+     cJSON* msgs = cJSON_Duplicate(messages, 1);\\n+     cJSON* sys_msg = cJSON_CreateObject();\\n+ \\n+-    cJSON_AddStringToObject(sys_msg, \\\"role\\\", \\\"system\\\");\\n+-    cJSON_AddStringToObject(sys_msg, \\\"content\\\", system_prompt);